window.HROFFICE={"updated":"2026-10-28","updatedKR":"2026년 10월 28일","updatedEN":"28 October 2026","total":130,"kor":51,"top":[{"date":"2026-10-06","tag":"협업","tagEN":"Collaboration","k":"에델만 'Trust at Work 2026': 동료 신뢰 82%→73%로 가장 크게 하락 — 조직 변화 경험이 나빴던 직원은 '가치관 다른 동료' 신뢰 50%","e":"Edelman Trust at Work 2026: trust in co-workers falls furthest, from 82% to 73%, and to 50% for colleagues with different values after a bad change experience","url":"https://www.edelman.com/newsroom/richard-edelmans-6am-blog/trust-at-work-2026"},{"date":"2026-10-24","tag":"리더십","tagEN":"Leadership","k":"팀장 고민 2,500여 건 분석 — 1위는 소통·관계, 피드백·육성 고민은 3년 새 7위→2위","e":"Analysis of 2,500 team-leader concerns: communication and relationships rank first, and feedback and development jump from 7th to 2nd in three years","url":"https://magazine.hankyung.com/business/article/202610229095b"},{"date":"2026-10-22","tag":"몰입","tagEN":"Engagement","k":"Korea Workplace Index ③: 10년 조직진단에서 리더십 긍정률 42.6%에 정체, 애착은 66.1%→44.6% — '리더는 만족까지만 데려다준다'","e":"Korea Workplace Index (3): over ten years leadership stays at 42.6% positive while attachment falls from 66.1% to 44.6%","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39678"},{"date":"2026-10-20","tag":"커뮤니케이션","tagEN":"Communication","k":"퇴근 후 업무 연락 부담 52.2%로 줄었지만 77.7%는 '근무시간 외엔 연락 안 하는 게 당연' 인식 확대 필요 — '법보다 사내 규칙으로' 46.6%","e":"52.2% of Korean workers find after-hours messages a burden, fewer than in 2024, and 77.7% want a norm of no contact outside hours, preferably through company rules","url":"https://www.segye.com/newsView/20261020507204"},{"date":"2026-10-24","tag":"업무 혁신","tagEN":"Work innovation","k":"직능연 조사: AI 효율은 정보 검색 33.4%·요약 22.4%에 몰리고 기획은 1.4% — 회사가 일방 도입하면 만족도 87.9%로 하락","e":"KRIVET survey: AI gains concentrate in information search (33.4%) and summaries (22.4%), not planning (1.4%), and satisfaction falls to 87.9% when AI is imposed top-down","url":"https://www.etoday.co.kr/news/view/2639400"},{"date":"2026-10-06","tag":"업무 효율","tagEN":"Efficiency","k":"NBER 연구(약 9,000명): 회의에 주 4.7시간·인건비의 14% — 무조건 줄이기보다 정보 전달용 반복 회의부터 가려내라","e":"NBER study of about 9,000 workers: meetings take 4.7 hours a week and 14% of payroll, so cut routine status meetings first rather than all meetings","url":"https://www.shrm.org/topics-tools/news/meetings-may-be-more-valuable-than-many-think"},{"date":"2026-10-27","tag":"업무 소프트웨어","tagEN":"Work software","k":"엑셀 코파일럿 '데이터 정리'·'스킬 빌더' 정식 배포 — 웹 엑셀에선 말로 Power Query를 만드는 '데이터 가져오기'","e":"Copilot in Excel rolls out Clean data and Skill builder, and Excel for the web gets a Get data skill that builds Power Query from plain language","url":"https://techcommunity.microsoft.com/blog/excelblog/whats-new-in-excel-october-2026/4549758"},{"date":"2026-10-13","tag":"HR 제도","tagEN":"HR policy","k":"노동장관 '포괄임금제 금지 법에 담아야, 정년연장 법안 연내 처리' — 감독 101곳 중 82곳에서 공짜 노동 적발","e":"Korea's labour minister backs a legal ban on all-inclusive pay and a retirement-age extension bill this year, as inspections find unpaid work at 82 of 101 sites","url":"https://www.asiatoday.co.kr/kn/view.php?key=20261013010003792"}],"groups":[{"code":"LEAD","kTitle":"리더십·코칭 — 팀장·관리자","eTitle":"Leadership and coaching - team leaders and managers","items":[{"code":"LEAD","date":"2026-10-27","src":"DBR","title":"DBR '韓 기업 권한부여 지수 24점 낙제' — ICSB 사람 중심 기업가정신 지수에서 한국은 기업가정신 2위·인간 번영 26위, 직원 헌신을 끌어내려면 믿고 맡겨야","eTitle":"DBR: Korean Firms Score a Failing 24 on Empowerment - Korea Ranks 2nd for Entrepreneurship but 26th for Human Flourishing in the ICSB Index, and Commitment Requires Trust and Delegation","kSum":"세계중소기업학회(ICSB)가 2026년 발표한 사람 중심 기업가정신 지수(HCE Index)는 GEM 기업가정신 자료와 갤럽 월드폴의 인간 번영 자료를 묶어 43개 경제권을 비교했는데, 한국은 기업가정신 80점(2위)에 비해 인간 번영은 44점(26위, 표본 평균 49.3점)에 그쳤다. 김기찬 ICSB 의장은 DBR 기고에서 격차가 생기는 곳이 권한 부여라며, 일자리와 일할 조건을 갖춰 주는 역량 활성화는 64.1점으로 평균을 웃돌지만 직원을 믿고 판단·선택 권한을 넘기는 권한 부여는 24.1점으로 평균과 격차가 가장 크다고 지적했다. 직원을 관리 비용이나 보상·처벌에만 반응하는 존재로 보는 통제 중심 경영이 원인이라며, 해법은 새 제도가 아니라 사람을 이해하고(Understanding)·투자하고(Investing)·신뢰해 권한을 넘기는(Trusting) 경영자의 'UIT' 행동이라고 제시했다(구독 기사, 공개된 앞부분 기준).","eSum":"The 2026 Human-Centred Entrepreneurship (HCE) Index from the International Council for Small Business (ICSB) combines GEM entrepreneurship data with Gallup World Poll human-flourishing data for 43 economies; Korea scores 80 on entrepreneurship (2nd) but only 44 on human flourishing (26th, below the 49.3 sample average). Writing in DBR, ICSB chair Kim Ki-chan says the gap lies in empowerment: Korea scores an above-average 64.1 on capability enablement, such as creating jobs and working conditions, but only 24.1 on trusting employees with judgement and choices, the widest gap from the average. He blames control-centred management that treats staff as a cost or as responding only to reward and punishment, and calls for leaders to practise 'UIT' - understanding, investing in and trusting people - rather than new schemes (subscriber article; summary based on the free opening section).","kImp":"팀장이 팀원의 일상적인 판단까지 세세한 결재로 묶어 두고 있지 않은지 점검하고, 팀원이 스스로 결정해도 되는 범위(일정 조정, 정해진 금액 이하 지출, 정형화된 대외 회신 등)를 문서로 정해 넘기는 것이 책임감과 몰입을 높이는 출발점이 될 수 있다.","eImp":"Team leaders could check whether routine decisions are tied up in detailed approval steps and write down the scope team members can decide on their own, such as schedule changes, spending below a set limit and standard external replies; handing over that scope is a starting point for stronger ownership and engagement.","url":"https://dbr.donga.com/article/view/1203/article_no/12318","prio":2,"kor":true,"tags":["LDR","ENG"],"tool":""},{"code":"LEAD","date":"2026-10-26","src":"Knowledge at Wharton","title":"와튼 연구: 원격근무에 가장 강하게 반대하는 리더의 공통 특성은 '나르시시즘'… 포춘 500 CEO 259명 분석, 직원 불신이 아니라 권력·지위 욕구 때문","eTitle":"Wharton Research: Narcissism Is the One Trait That Consistently Predicts Leaders' Resistance to Remote Work, Driven by a Desire for Power and Status Rather Than Distrust of Staff","kSum":"애덤 그랜트 와튼스쿨 교수 연구팀이 Organizational Behavior and Human Decision Processes에 실은 논문을 Knowledge at Wharton이 2026년 10월 26일 소개했다. 포춘 500 CEO 259명의 공개 자료(연차보고서 속 사진의 비중, 서명 크기, 2인자 대비 보수 등) 분석과 설문·실험으로 이어진 세 연구에서 원격근무 반대를 일관되게 예측한 성격 특성은 나르시시즘뿐이었고, 그 동기는 직원에 대한 불신이 아니라 권력·지위 욕구였다. 연구진은 모두 출근하는 '앵커 데이'(특히 신입·주니어 지도용), 출근 일수보다 상호작용의 질 중시, 직무별로 다른 근무 방식 허용, 원격이 어렵다면 근무 시간 선택권 부여 등을 제안했다.","eSum":"Knowledge at Wharton on 26 October 2026 featured a paper by Wharton professor Adam Grant and doctoral candidates Marissa Shandell and Courtney Elliott in Organizational Behavior and Human Decision Processes. Across three studies, starting with an archival analysis of 259 Fortune 500 CEOs using proxies such as photo prominence in annual reports, signature size and pay relative to the next-highest executive, followed by a survey and an experiment, narcissism was the only trait that consistently predicted resistance to remote work, and the resistance stemmed from a desire for power and status rather than a lack of trust in employees. The authors recommend anchor days when everyone is in, especially for mentoring newcomers, valuing the quality of interactions over attendance, allowing different arrangements for different roles, and offering schedule flexibility where remote days are not possible.","kImp":"출근·재택 규칙을 정할 때 팀장 본인의 선호가 아니라 '어떤 업무가 대면에서 더 잘 되는가'를 기준으로 삼고, 신입·주니어 지도가 필요한 요일을 팀 공통 출근일로 정해 두면 불필요한 갈등을 줄일 수 있다.","eImp":"When setting office and home-working rules, team leaders should start from which tasks genuinely work better face to face rather than their own preferences, and fixing a common office day around coaching newer and junior staff can head off needless conflict.","url":"https://knowledge.wharton.upenn.edu/article/why-narcissistic-leaders-dont-like-remote-work/","prio":2,"kor":false,"tags":["LDR","REMOTE","WR"],"tool":""},{"code":"LEAD","date":"2026-10-24","src":"한경비즈니스","title":"팀장 고민 2,500여 건 분석…1위는 '소통·관계', 피드백·육성 고민은 3년 새 7위→2위로 급등","eTitle":"An Analysis of About 2,500 Team-Leader Concerns Puts Communication and Relationships First, as Feedback and Development Jump From 7th to 2nd in Three Years","kSum":"IGM세계경영연구원이 2024~2026년 'STORM 팀장과정' 참가자가 낸 고민 2,500여 건을 분석한 결과, 3년 합산 1위는 소통·관계였고 성과관리·평가, 업무위임·배분, 피드백·육성, 동기부여가 뒤를 이었다. 피드백·육성은 2024년 7위에서 2026년 2위로 올라 가장 큰 변화를 보였고, AI 관련 고민도 처음으로 상위 7위 안에 들었다. 소통 고민에는 경영진 방침을 팀원에게 전달하는 일, 회식을 꺼리는 신입과의 관계 맺기, 상사 기대와 팀원 의견 사이의 균형 등이 포함됐다.","eSum":"IGM Global Management Institute analysed roughly 2,500 concerns submitted by participants in its STORM team-leader course from 2024 to 2026. Communication and relationships ranked first over the three years, followed by performance management and evaluation, delegation and task allocation, feedback and development, and motivation. Feedback and development rose from 7th in 2024 to 2nd in 2026, the biggest shift, and an AI-related concern entered the top seven for the first time. Communication worries included relaying senior direction to the team, building rapport with new hires who avoid after-work dinners and balancing a boss's expectations against team members' views.","kImp":"팀장 교육·면담 주제를 '업무 지시'에서 피드백 대화와 '상사 방침을 팀 언어로 풀어 전달하기' 연습으로 옮기고, AI 도입으로 불안해하는 팀원에게는 팀 우선순위부터 분명히 정해 주는 것이 좋다.","eImp":"Team-leader training and one-to-ones can move from task instruction towards practising feedback conversations and translating senior direction into the team's own terms, and leaders should first set clear team priorities for staff who feel anxious about AI.","url":"https://magazine.hankyung.com/business/article/202610229095b","prio":2,"kor":true,"tags":["LDR","COACH"],"tool":""},{"code":"LEAD","date":"2026-10-23","src":"DBR","title":"DBR '회의에서 조용한 팀원, 정말 의욕이 없는 걸까?' — 침묵은 태도가 아니라 '말해 봐야 안 바뀐다'는 학습의 결과, 질문을 늘리기 전에 팀장이 주는 위압감부터 걷어야","eTitle":"DBR: Quiet Team Members Are Not Necessarily Unmotivated - Silence Is Learned From 'Speaking Up Changes Nothing', So Leaders Should Remove the Intimidation Before Asking More Questions","kSum":"DBR 팀장클럽 리포트에서 리더십 작가 김진영은 회의 때 침묵하던 팀원들이 회의가 끝난 뒤 탕비실·엘리베이터에서는 다양한 의견을 나누는 현상을 짚으며, 질문 횟수를 늘리거나 '편하게 말하라'고 독려하는 것만으로는 침묵을 깰 수 없다고 했다. 10월 20일 글은 같은 질문도 팀장이 위압적으로 느껴지면 팀원에게 '무슨 답을 원하나', '잘못 답하면 어떻게 되나'라는 계산을 낳는다며, 그 위압감은 성격보다 반대 의견에 한 번 정색한 장면, 평가·업무 배분 권한, 늘 결론을 먼저 말하는 습관이 쌓인 인식에서 생긴다고 설명했다. 10월 23일 후속 글은 의욕과 실제 주어지는 기회의 간극이 클수록 침묵이 늘고, 침묵은 대개 '말해 봐야 아무것도 안 바뀌더라'는 경험이 반복된 학습의 결과라고 짚었다(구독 기사, 공개된 앞부분 기준).","eSum":"In DBR's team-leader series, leadership writer Kim Jin-young notes that team members who stay silent in meetings often share their views freely in the pantry or the lift afterwards, and argues that asking more often or urging people to speak freely will not break the silence. A 20 October piece says the same question can feel like a threat when a leader is seen as forceful, prompting staff to calculate what answer is wanted and what happens if they get it wrong; that perception is built less by personality than by a single sharp reaction to dissent, control over appraisals and work allocation, and a habit of announcing the conclusion first. A follow-up on 23 October says silence grows with the gap between motivation and real opportunity, and is usually learned after repeated experiences that speaking up changes nothing (subscriber articles; summary based on the free opening sections).","kImp":"주간 회의에서 팀장이 먼저 결론을 말하지 말고 팀원 의견부터 듣는 순서로 바꾸고, 지난 회의에서 나온 제안이 실제로 무엇을 바꿨는지 다음 회의 첫머리에 알려 '말하면 바뀐다'는 경험을 쌓게 할 만하다. 반대 의견에 한 번 정색한 반응이 오래 기억된다는 점도 팀장이 의식해야 한다.","eImp":"In weekly meetings, team leaders could hear team members before stating their own conclusion and open each meeting by reporting what the last round of suggestions actually changed, so people learn that speaking up makes a difference. Leaders should also remember that a single sharp reaction to dissent is remembered for a long time.","url":"https://dbr.donga.com/teamleader/view/article_no/188","prio":2,"kor":true,"tags":["LDR","PS","SPEAK"],"tool":""},{"code":"LEAD","date":"2026-10-23","src":"SHRM","title":"관리자가 세세하게 간섭하는 이유는 불신만이 아니다: 결과 책임·하이브리드로 인한 가시성 저하·위계 문화가 원인… SHRM, '결과 중심 목표와 단계적 위임' 권고","eTitle":"SHRM: Micromanagement Stems From Accountability Pressure, Low Visibility in Hybrid Work and Hierarchical Cultures as Much as Distrust, So Set Outcome Goals and Delegate in Stages","kSum":"SHRM 인도판 블로그가 2026년 10월 23일 실은 글은 관리자가 감독 강도를 정할 때 신뢰는 여러 요인 중 하나일 뿐이며, 고객 마감처럼 결과 책임이 클 때와 하이브리드 근무로 진행 상황이 잘 보이지 않을 때 확인·보고 요구가 늘어난다고 분석했다. 위계적 보고 문화와 높은 권력 거리, 리더십 교육 없이 실무 고성과자를 관리자로 올리는 관행도 밀착 감독을 부추긴다고 했다. 처방으로는 결과·마감·품질 기준만 정하고 방법은 직원에게 맡기기, 신입은 잦은 검토에서 정해진 점검 시점을 거쳐 완전한 책임으로 단계적으로 넘기기, 주 1회나 격주 정기 점검 대화, 신임 관리자 대상 위임·코칭 교육을 제시했다.","eSum":"A SHRM India blog post published on 23 October 2026 argues that trust is only one input when managers decide how closely to supervise, with oversight rising when they are accountable for results such as fixed client deadlines and when hybrid work makes progress harder to see. Hierarchical reporting, high power distance and promoting strong individual contributors into management without leadership training also encourage hands-on supervision. It recommends defining the outcome, deadline and quality standard while leaving the method to the employee, handing over work in stages from frequent reviews to planned checkpoints to full ownership, holding fixed weekly or fortnightly check-ins, and training new managers in delegation and coaching.","kImp":"새로 합류한 팀원에게는 처음부터 전권을 주기보다 '초기 잦은 검토 → 정해진 중간 점검 → 단독 책임'의 3단계 위임 계획을 미리 알려 주면, 간섭으로 느끼지 않으면서 진행 상황도 놓치지 않을 수 있다.","eImp":"Telling new team members up front about a three-stage delegation plan, from frequent early reviews to set checkpoints to full ownership, lets managers keep track of progress without it feeling like interference.","url":"https://www.shrm.org/in/topics-tools/news/blogs/are-managers-micromanaging-because-they-do-not-trust-their-teams","prio":1,"kor":false,"tags":["LDR","COACH","REMOTE"],"tool":""},{"code":"LEAD","date":"2026-10-22","src":"HR Insight","title":"Korea Workplace Index ③ — 10년 조직진단 데이터: 리더십 긍정률 42.6%에 정체, 애착은 66.1%→44.6% 하락…“리더는 만족까지만 데려다준다”","eTitle":"Korea Workplace Index (3): Ten Years of Diagnostic Data Show Leadership Stuck at 42.6% Positive While Attachment Fell From 66.1% to 44.6%","kSum":"HR Insight와 조직건강검진센터·HCM컨설팅&리서치(H2C)가 10년간 축적한 조직건강 진단 데이터를 분석한 연재 3편으로, 긍정 리더십 6요인(진정성·결집·방향제시·공정성·배려와 육성·개방)의 긍정률이 41.2~44.9%(종합 42.6%)에 몰려 뚜렷한 강점이 없고, 10년간 리더십 평가는 제자리인 반면 회사 애착 긍정률은 66.1%에서 44.6%로 떨어졌다. 리더십은 조직만족 개인차의 31.5%를 설명하지만 애착은 14.6%, 탈진은 12.9%만 설명하고, 애착·열의·이직의도·탈진에 대한 영향의 62~85%가 만족을 거쳐 전달돼 '평범한 리더십은 구성원을 만족까지만 데려다준다'고 결론냈다. 애착에는 '배려와 육성'(긍정률 41.2%로 최저)이, 탈진·이직의도에는 기분에 따른 지시·결정 번복 같은 '방향 부재·변덕'이 크게 작용했으며, 파괴적 리더 행동을 자주 목격했다는 응답은 13.5%로 드물지만 그 영향력은 38~59%에 달했다.","eSum":"The third instalment of HR Insight and H2C's Korea Workplace Index, drawing on ten years of organisational health diagnostic data, finds positive ratings for six leadership factors bunched at 41.2-44.9% (42.6% overall) with no clear strength, flat for a decade while positive attachment to the company fell from 66.1% to 44.6%. Leadership explains 31.5% of individual differences in satisfaction but only 14.6% for attachment and 12.9% for burnout, and 62-85% of its effect on attachment, engagement, turnover intention and burnout runs through satisfaction, leading the authors to conclude that ordinary leadership only takes people as far as satisfaction. Care and development, the lowest-rated factor at 41.2%, matters most for attachment, while erratic, mood-driven direction drives burnout and turnover intention; destructive leader behaviour is reported by only 13.5% but carries 38-59% influence.","kImp":"팀장 리더십 교육에서 좋은 행동을 더하는 것만큼 드물지만 영향이 큰 부정 행동(기분에 따른 지시, 결정 번복, 갈등 방치)을 줄이는 데 초점을 두고, 조직문화 설문에 성장 지원과 지시의 예측 가능성을 따로 묻는 문항을 넣어 볼 만하다. 팀장 스스로 지난 한 달간 결정을 몇 번 뒤집었는지 돌아보는 것부터 시작할 수 있다.","eImp":"Team leader training could put as much weight on cutting rare but high-impact negative behaviours, such as mood-driven instructions, reversed decisions and unresolved conflict, as on adding good ones, and staff surveys could ask separately about growth support and how predictable instructions are. Leaders can start by counting how often they reversed a decision in the past month.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39678","prio":3,"kor":true,"tags":["LDR","ENG","RET"],"tool":""},{"code":"LEAD","date":"2026-10-22","src":"Stanford GSB Insights","title":"스탠퍼드 GSB: 망가진 위계는 '경쟁 과열·불공정·불안정'으로 드러난다… 할레비 교수, 평가 기준 다양화·공동 리더십·동료 기여 인정을 처방","eTitle":"Stanford GSB: Broken Hierarchies Are Ultra-Competitive, Unjust and Unstable, and Nir Halevy Prescribes Broader Evaluation, Shared Leadership and Recognising Peers' Contributions","kSum":"스탠퍼드 경영대학원 인사이트가 2026년 10월 22일 실은 니르 할레비 교수(신간 'Level Up') 인터뷰에 따르면, 그는 발레 무용수·즉흥극 배우·운동선수·공무원·군인 등 100명 이상을 인터뷰해 망가진 위계가 지나치게 경쟁적이고 불공정하며 불안정하다는 공통점을 찾았다. 불공정은 분배 불공정, 설명 없는 결정 같은 절차 불공정, 부당한 대우의 세 가지로 나타나며, 권한은 주되 존중은 주지 않는 역할처럼 사람이 아니라 구조가 문제인 경우도 있다고 했다. 그는 관리자에게 다양한 기여를 인정하도록 평가·보상 체계를 고치고 직무별로 다른 경력 트랙을 두며 팀·프로젝트를 공동으로 이끌라고 권했고, 팀원에게는 동료의 기여를 인정하고 리더 역할을 맡으면 동료와의 공동 리더를 제안해 보라고 조언했다.","eSum":"In an interview published by Stanford GSB Insights on 22 October 2026, organisational behaviour professor Nir Halevy, author of Level Up, draws on more than 100 interviews with ballet dancers, improv performers, athletes, government officials and military personnel to describe broken hierarchies as ultra-competitive, unjust and unstable. Injustice takes three forms, distributive unfairness, procedural unfairness such as unexplained decisions, and mistreatment, and sometimes the structure rather than the people is at fault, as with roles that carry power without status. He urges managers to revise evaluation and incentive systems to recognise a wider range of contributions, create parallel career tracks and share leadership through co-led teams or projects, and suggests team members acknowledge colleagues' contributions and propose co-leading with a peer when asked to lead.","kImp":"결정 이유를 설명하지 않는 것만으로도 '절차가 불공정하다'는 인식이 생기므로, 팀장은 업무 배분·평가 결정을 내릴 때 기준과 이유를 짧게라도 공유하고, 큰 과제는 두 명이 공동 책임자로 이끌게 해 볼 만하다.","eImp":"Unexplained decisions alone can make a process feel unfair, so team leaders should briefly share the criteria and reasons behind work allocation and appraisal decisions, and consider having two people co-lead larger assignments.","url":"https://www.gsb.stanford.edu/insights/how-fix-broken-hierarchy-inside","prio":1,"kor":false,"tags":["LDR","PERF","COLLAB"],"tool":""},{"code":"LEAD","date":"2026-10-19","src":"메가경제","title":"배재훈 한국코치협회장(전 HMM 사장) \"코칭은 만병통치약 아니다\"…경영 50%·멘토링 30%·코칭 20%, 위임은 방임이 아니라 범위·결과를 정해 주는 것","eTitle":"Korea Coach Association President and Former HMM CEO Bae Jae-hoon Says Coaching Is No Cure-All, Suggesting Leaders Spend About 50% on Management, 30% on Mentoring and 20% on Coaching, and That Delegation Means Setting Scope and Results","kSum":"LG전자·판토스·HMM 경영자 출신인 배재훈 한국코치협회장은 메가경제 인터뷰에서 리더는 모든 일을 직접 지시하기보다 비전과 시스템을 세우고 권한을 주되 필요할 때 개입해야 한다며, 리더 역할을 대략 경영 50%·멘토링 30%·코칭 20%로 나눠 보라고 했다. 위임은 방임이 아니라 범위와 기대 결과를 정하고 피드백과 점검을 이어 가는 것이며, 비상 상황에서는 질문보다 직접 지시가 맞다고 했다. 코칭은 '문제가 무엇인지, 목표가 무엇인지, 어떤 선택지가 있는지'를 물어 당사자가 답을 찾게 하는 질문·경청·피드백이고 결국 행동으로 이어져야 한다고 설명했다. 장기 적자 상태의 HMM에 취임했을 때는 대주주·정부 보고 요구로 직원 시간이 보고서에 쏠려 있어 '새 사장이 왔다고 새 보고서를 만들지 말라'고 지시하고, 직속 상사 없이 직원들과 이야기하는 자리를 열었다고 소개했다.","eSum":"In a Mega Economy interview, Bae Jae-hoon, president of the Korea Coach Association and a former executive at LG Electronics, Pantos and HMM, says leaders should set the vision and systems and hand over authority while stepping in when needed, suggesting a rough split of 50% management, 30% mentoring and 20% coaching. Delegation is not abdication but defining scope and expected results and continuing feedback and oversight, and in emergencies direct instruction beats questioning. He describes coaching as questioning, listening and feedback that help people define the problem, goal and options themselves, and that must lead to action. When he took over a loss-making HMM, staff time was consumed by reports demanded by major shareholders and government bodies, so he told managers not to create new reports for the new CEO and held open sessions with staff without their direct bosses present.","kImp":"팀장은 팀원이 문제를 들고 오면 바로 답을 주기보다 '무엇이 문제이고 목표는 무엇이며 어떤 선택지가 있는지'를 먼저 물어보고, 비상 대응처럼 시간이 없는 일은 예외로 분명히 지시하는 식으로 상황별 리더십을 나눠 써 볼 만하다. 새 보고 양식을 늘리기 전에 기존 보고 중 없앨 것부터 찾는 것도 방법이다.","eImp":"When team members bring a problem, a team leader can first ask what the problem is, what the goal is and what options exist rather than handing over an answer, while giving clear direct instructions in time-critical situations such as emergency response; before adding any new report format, it helps to look for existing reports to drop.","url":"https://www.megaeconomy.co.kr/news/newsview.php?ncode=1065577973576164","prio":2,"kor":true,"tags":["LDR","COACH"],"tool":""},{"code":"LEAD","date":"2026-10-19","src":"HR Dive","title":"감시·통제의 '무거운 리더십' 대신 '가벼운 리더십' — Z세대 몰입의 열쇠는 관계와 설명","eTitle":"Leading 'light' may be the key to engaging Gen Z — and everyone else","kSum":"HR Dive의 에밀리 셤웨이 선임기자가 인터뷰한 리더십 개발 전문가 댄 러스트(Infopro Learning 부사장)는 감시와 통제에 기대는 '무거운' 리더십 대신, 깊은 개인적 관계를 맺고 무관심해 보이는 행동을 처벌할 반항이 아니라 이해해야 할 신호로 보는 '가벼운' 리더십을 제안했다. 그는 Z세대의 직설과 무관심은 리더가 만든 문화를 반영하는 것일 수 있으며 '그들은 그저 숨기는 데 서툴 뿐'이라고 말한다. 그는 설명 없는 문화와 전략에 쉽게 동의하지 않는 Z세대의 목적에 대한 질문을 판단 없이 받아 관행을 다시 생각하거나 더 잘 설명하고, 개인 관심사까지 다루는 1:1 대화와 상시 피드백으로 직원 각자의 사연과 동기를 파악하라고 권했다. 직원을 '가족'이라 부르는 것은 경고 신호라고 덧붙였다.","eSum":"In an interview with HR Dive senior editor Emilie Shumway, Dan Rust, vice president of global leadership development at Infopro Learning, contrasts 'heavy' leadership built on surveillance and tight control with 'light' leadership that builds deeper personal connections and treats disengaged behavior as information to understand rather than defiance to punish. He suggests Gen Z's bluntness and disengagement may reflect the culture leaders create: 'I think they're just worse at hiding it.' Because Gen Z resists culture or strategy that is not explained, he advises taking their questions about purpose without judgment and then rethinking or better explaining the practice, holding one-on-ones that cover personal interests, giving continuous feedback and learning each employee's story; calling employees 'family' is a red flag.","kImp":"젊은 직원이 '이 보고는 왜 이렇게 해야 하나요'라고 물을 때 직급으로 누르기보다 관행의 이유를 설명하고, 설명이 안 되면 관행 자체를 다시 따져 보는 것이 이탈을 막는 첫걸음이다. 팀장이 업무 얘기에만 머물지 않는 짧은 1:1 대화를 정기적으로 갖고, 되풀이되는 질문은 업무 방식 개선 안건으로 팀 회의에 올려 볼 만하다.","eImp":"When younger staff ask why a report has to be done a certain way, explaining the reason, or rethinking the practice if no good reason exists, does more to keep them than pulling rank. Team leaders could hold regular short one-on-ones that go beyond work topics and bring recurring questions to team meetings as process-improvement items.","url":"https://www.hrdive.com/news/leading-light-may-be-the-key-to-engaging-gen-z-and-everyone-else/833373/","prio":1,"kor":false,"tags":["LDR","ENG","COACH"],"tool":""},{"code":"LEAD","date":"2026-10-16","src":"DBR","title":"DBR '최악의 상사를 리더십 교재로' — 일을 비판하는 '요구가 많은 상사'와 사람을 깎아내리는 '파괴적 상사'를 구분해 교훈을 회수하라","eTitle":"DBR: Turning the Worst Boss Into Leadership Material - Separate the 'Demanding Boss' Who Criticises the Work From the 'Destructive Boss' Who Attacks the Person","kSum":"DBR 팀장클럽 리포트(10월 16일)는 편안한 강의실에서 듣는 리더십 이론보다 나쁜 상사와 일하며 매일 부딪힌 시행착오가 더 오래 기억에 남는다며, 이미 겪은 부정적 경험에서 앞으로의 리더십에 쓸 교훈을 찾아내라고 권했다. 다만 나쁜 상사도 두 유형으로 나눠야 한다고 했다. 높은 기준으로 '일'을 비판해 대화 뒤 '무엇을 어떻게 고칠지'가 남는 요구가 많은 상사와, '사람'을 모욕하고 인격을 깎아내려 피드백이 아닌 상처를 남기는 파괴적인 상사다. 글은 유형을 구분한 뒤 경험에서 배울 점을 회수하는 3단계를 제시한다(구독 기사, 공개된 앞부분 기준).","eSum":"A 16 October piece in DBR's team-leader series argues that lessons learned through daily friction with a bad boss last longer than leadership theory heard in a comfortable classroom, so managers should mine those negative experiences for lessons they can use. It says bad bosses must be split into two types: the demanding boss, who judges the work against high standards and leaves people knowing what to fix, and the destructive boss, who insults and belittles the person and leaves hurt rather than feedback. The article then sets out three steps for recovering lessons once the type is identified (subscriber article; summary based on the free opening section).","kImp":"신임 팀장 교육이나 팀장 워크숍에서 '내가 겪은 최악의 상사' 경험을 익명 사례로 나누되, 기준이 높은 업무 지적과 인격을 깎아내리는 공격을 구분하는 토론을 하면 직장 내 괴롭힘 예방과 피드백 방식 개선을 함께 다룰 수 있다. 피드백을 준 뒤 상대에게 '무엇을 어떻게 고칠지'가 남았는지를 스스로 점검하는 기준으로도 쓸 만하다.","eImp":"New-manager training or team-leader workshops could use anonymised 'worst boss' stories and discuss the line between demanding criticism of the work and personal attacks, which supports both workplace-harassment prevention and better feedback habits. A simple self-check after giving feedback is whether the other person now knows what to fix and how.","url":"https://dbr.donga.com/teamleader/view/article_no/186","prio":1,"kor":true,"tags":["LDR","COACH","TRN"],"tool":""},{"code":"LEAD","date":"2026-10-15","src":"HR Dive","title":"리더 17%만 '변화 대응에 자신 있다' — DDI 글로벌 리더십 전망 2027(리더 1만1천여 명)","eTitle":"Leaders say they are worried about their ability to handle change","kSum":"컨설팅사 DDI가 리더 1만1,000명 이상과 HR 전문가 약 2,500명의 응답을 분석한 '글로벌 리더십 전망 2027'에서 변화를 예측하고 대응하는 데 자신 있다는 리더는 17%에 그쳤고, 자신감이 없는 리더는 차질 속에서 생산성을 유지할 가능성이 3분의 1 수준이었다. 불안한 리더는 확실한 이직 의향을 밝힐 가능성이 5.1배 높았고, 완전히 몰입한 리더는 9%뿐이었지만 이들은 팀의 최고 역량을 끌어낼 가능성이 8.8배 높았다. 리더 81%가 AI의 생산성 향상을 꼽으면서도 신기술 활용에 준비됐다는 응답은 14%였고, 고위 경영진을 신뢰하는 실무자는 21%에 그쳤다. DDI CEO 테이시 바이엄은 변화 속도를 늦출 수 없으니 변화를 이끄는 리더에게 성과를 내면서 역량을 쌓을 시간과 여력을 주라고 권했다.","eSum":"DDI's Global Leadership Forecast 2027, based on more than 11,000 leader responses and about 2,500 HR professionals, found only 17% of leaders feel confident anticipating and reacting to change, and those lacking that confidence were one-third as likely to stay productive during setbacks. Anxious leaders were 5.1 times more likely to report a definite intention to leave, and just 9% were fully engaged, although those who were proved 8.8 times more likely to regularly bring out the best in their teams. While 81% of leaders cited AI productivity gains, only 14% felt ready to use emerging technologies, and only 21% of individual contributors trust senior leadership. DDI CEO Tacy Byham urged organizations to give leaders driving change the time and capacity to build skills while still delivering results.","kImp":"새 시스템·제도 도입이 겹치는 시기에는 변화를 이끄는 팀장부터 자신감을 잃고 지치기 쉽다. 분기 계획 회의에서 다가올 변화의 일정과 필요한 역량을 미리 짚어 주고, 변화 과제를 맡은 팀장에게 교육과 준비에 쓸 시간을 업무 목표에서 실제로 떼어 줄 만하다.","eImp":"When new systems and policy changes pile up, the team leaders asked to drive change are often the first to lose confidence and burn out. Use quarterly planning meetings to preview upcoming changes and the skills they will require, and carve real time out of those leaders' targets for their own training and preparation.","url":"https://www.hrdive.com/news/leaders-say-they-are-worried-about-their-ability-to-handle-change/833077/","prio":3,"kor":false,"tags":["LDR","CHG","AI"],"tool":""},{"code":"LEAD","date":"2026-10-12","src":"Harvard Business Review","title":"HBR 연구: 리더의 '진정성'은 실패담 고백이 아니라 '대가를 감수한 선택'을 밝힐 때 생긴다… 10개 실험·2,000여 명","eTitle":"HBR Research: Leaders Look Authentic When They Disclose Costly, Unconventional Choices, Not When They Share Setbacks, Across 10 Experiments With Over 2,000 Participants","kSum":"HBR이 2026년 10월 12일 실은 나므라타 고얄·크리슈나 사바니·스벤 엥게서·베로니카 욥의 연구는 10개 실험(참가자 2,000명 이상)에서, 리더가 개인적 대가를 치른 비관행적 선택을 스스로 밝힐 때 진정성과 지지가 높아졌고 특히 이미 자리를 잡은 리더에게서 효과가 컸다고 밝혔다. 반면 고통스러운 좌절을 털어놓는 것은 동정은 얻었지만 진정성 인식은 거의 높이지 못했고, 남을 이용한 선택을 밝히면 신뢰가 깎였다. 연구진은 취약성과 진정성을 구분하고, 불운보다 선택을 공개하며, 관행에서 벗어나기 전에 신뢰부터 쌓으라고 조언했다. (구독 기사, 공개된 앞부분 기준)","eSum":"A Harvard Business Review article published on 12 October 2026 by Namrata Goyal, Krishna Savani, Sven Engesser and Veronika Job reports 10 experiments with more than 2,000 participants. Voluntarily disclosing an unconventional choice that carried a personal cost boosted perceived authenticity and support, especially for established leaders, whereas sharing setbacks drew sympathy but little perceived authenticity, and disclosing exploitative choices damaged trust. The authors advise leaders to distinguish vulnerability from authenticity, disclose choices rather than misfortunes, and build credibility before departing from convention. (Subscription article; based on the publicly visible opening section.)","kImp":"팀장이 팀원과 신뢰를 쌓으려 할 때는 힘들었던 경험담보다 '왜 그 결정을 했고 무엇을 포기했는지'를 설명하는 편이 효과적이므로, 업무 우선순위를 바꿀 때 그 이유와 감수한 비용을 함께 밝혀 볼 만하다.","eImp":"Team leaders seeking trust gain more from explaining why they made a decision and what they gave up than from sharing hardships, so when changing priorities they should state both the reasons and the costs accepted.","url":"https://hbr.org/2026/10/research-when-being-authentic-undermines-your-leadership","prio":2,"kor":false,"tags":["LDR"],"tool":""},{"code":"LEAD","date":"2026-10-06","src":"HR Dive","title":"관리자에게 부하 육성 시간이 있으면 '잔류 의향' 84%, 없으면 41% — Wiley 약 1,500명 조사","eTitle":"The biggest predictor of L&D success? How much time managers can spare.","kSum":"와일리 워크플레이스 인텔리전스가 9월 25일 발표한 약 1,500명 대상 경력 경로 조사에서, 관리자가 부하 육성에 시간을 낼 수 있을 때는 직원의 84%가 회사에 남을 가능성이 매우 높다고 답했지만 그렇지 않을 때는 41%에 그쳤다. 관리자가 곁에 있을 때 조직 문화에 열의를 느낀다는 응답도 76%로, 관리자가 없을 때(23%)의 3배를 넘었다. 몰입을 가장 높일 요인으로는 기술 개발·교육이 멘토링과 승진 투명성보다 많이 꼽혔다. 와일리는 관리자 시간을 보호하고 관리자 가용성을 '문화적 장식'이 아닌 인재 유지 지표로 다루라고 권했다.","eSum":"A Wiley Workplace Intelligence survey of nearly 1,500 people on career pathing, released on September 25, found that 84% of employees are very likely to stay when their manager has time to develop them, versus 41% when the manager does not. Some 76% said they are excited about the culture when their manager is available, compared with 23% when not. Skills development and training topped the factors that would most improve engagement, ahead of mentorship and advancement transparency. Wiley urges employers to protect manager time and treat manager availability as a retention metric, 'not a culture nicety'.","kImp":"팀장이 보고서·결재·회의에 묶이면 팀원을 가르칠 시간이 가장 먼저 사라진다. 팀장의 반복 행정 업무를 줄이거나 자동화하는 일이 곧 인재 유지 대책이라는 근거로 쓸 수 있고, 팀장별 1:1 면담·업무 지도 시간을 월 단위로 기록해 살펴볼 만하다.","eImp":"When team leaders are tied up with reports, approvals and meetings, time to develop their people is the first thing lost. Use this as evidence that cutting or automating managers' routine admin is itself a retention measure, and track each manager's monthly time spent on one-on-ones and coaching.","url":"https://www.hrdive.com/news/the-biggest-predictor-of-ld-success-how-much-time-managers-can-spare/832243/","prio":2,"kor":false,"tags":["COACH","RET","TRN"],"tool":""},{"code":"LEAD","date":"2026-09-28","src":"Harvard Business Review","title":"HBR: 리더 자리를 망설이는 직원은 '준비 부족'이 아니라 '성숙함'일 수 있다… 자원자만 보지 말고 망설임의 이유를 물어 후보를 가려라","eTitle":"HBR: Reluctance to Step Into Leadership Can Signal Maturity, Not a Lack of Potential, So Look Past Volunteers and Explore What Drives a Candidate's Hesitation","kSum":"HBR이 2026년 9월 28일 실은 알렉시스 자너·마르틴 구트만·스콧 앨런의 글은 조직이 리더를 하겠다고 나서는 열의를 준비된 신호로 여기고 망설이는 직원은 간과하기 쉽다고 지적했다. 저자들은 '리더가 되고 싶은 것과 리더가 될 준비가 된 것은 다르다'며, 망설임은 자기 인식과 역할의 요구·대가에 대한 현실적 판단을 반영할 수 있다고 봤다. 이들은 자원자만 보지 말고 기대·동기·역량 공백·리더 역할의 현실을 솔직하게 대화해 '망설이지만 준비된 사람', '경험이 더 필요한 사람', '리더 역할이 맞지 않는 사람'을 구분하고, 설득보다 더 나은 선발과 지원에 집중하라고 권했다. (구독 기사, 공개된 앞부분 기준)","eSum":"In a Harvard Business Review article published on 28 September 2026, Alexis Zahner, Martin Gutmann and Scott J. Allen argue that organisations often read eagerness to lead as readiness and overlook employees who hesitate, noting that being eager to lead is not the same as being ready to lead. Reluctance can reflect self-awareness and a realistic view of the role's demands and trade-offs. They advise looking beyond volunteers and holding candid conversations about expectations, motivations, development gaps and the realities of leadership to separate the reluctant but ready, those who need more experience and those for whom leadership is a poor fit, focusing on better selection and support rather than persuasion. (Subscription article; based on the publicly visible opening section.)","kImp":"팀장 후보를 고를 때 손을 드는 사람만 보지 말고 조용히 일 잘하는 팀원에게 '리더 역할에서 무엇이 걱정되는지'를 직접 물어, 걱정이 업무량이나 교육 부족이라면 그 부분부터 지원하는 방식으로 후보군을 넓혀 볼 만하다.","eImp":"When picking future team leaders, managers should not only look at those who volunteer but ask quietly capable staff what worries them about leading, and widen the pool by first addressing concerns such as workload or lack of training.","url":"https://hbr.org/2026/09/is-reluctance-to-step-into-leadership-a-sign-of-maturity-or-a-red-flag","prio":2,"kor":false,"tags":["LDR","TRN"],"tool":""},{"code":"LEAD","date":"2026-09-21","src":"HR Insight","title":"LG화학, 리더 1,000여 명 개발을 AI로 개인화…진단 결과 넣으면 AI가 풀이하고 실행계획 1:1 코칭하는 사내 앱 'ALICE'","eTitle":"LG Chem Personalises Development for About 1,000 Leaders With AI, Using an In-House App, ALICE, That Debriefs Diagnostic Results and Coaches Each Leader on an Action Plan","kSum":"HR Insight 10월호에 따르면 LG화학은 고성과 리더의 10가지 행동 특성을 정해 공통 교육을 운영해 왔지만, 소수의 리더십 개발팀이 1,000여 명의 리더를 지원하다 보니 리더마다 다른 고민을 다루기 어려웠다. 이에 진단·교육·코칭·실행 전 과정에 AI를 적용해 2025년 사내 앱 'ALICE(AI Leadership Insight & Coaching Experience)'를 내놨고, 리더가 진단 결과와 관련 정보를 입력하면 AI 디브리핑과 실행계획 수립을 위한 1:1 코칭을 받는다. 2026년에는 사내 AX 조직과 함께 진단·결과 리포트·후속 단계를 잇는 통합 리더십 시스템을 구축했다. 기사에는 성과 지표가 나오지 않는다. (구독 기사, 공개된 앞부분 기준)","eSum":"According to HR Insight's October issue, LG Chem had defined ten behaviours of high-performing leaders and ran common training on them, but a small leadership development team supporting about 1,000 leaders struggled to address each leader's different challenges. It applied AI across diagnosis, training, coaching and execution, launching an in-house app, ALICE (AI Leadership Insight and Coaching Experience), in 2025: leaders enter their diagnostic results and context and receive an AI debrief and one-to-one coaching on an action plan. In 2026, with its internal AI transformation unit, it built an integrated leadership system linking diagnosis, result reports and follow-up steps. The article reports no outcome metrics.","kImp":"다면진단이나 리더십 교육을 받은 팀장이 결과지를 덮어 두지 않도록, 진단 직후 '바꿀 행동 한 가지와 이번 달 실행 계획'을 상사·HR과 함께 정하는 짧은 후속 면담을 붙이는 것부터 해 볼 만하다.","eImp":"So that team leaders do not file away their 360-degree results or training notes, organisations can add a short follow-up conversation right after the diagnosis in which the leader agrees with their manager or HR on one behaviour to change and a plan for the month.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=109&bi_pidx=39574","prio":1,"kor":true,"tags":["LDR","COACH","AI"],"tool":""},{"code":"LEAD","date":"2026-09-15","src":"Harvard Business Review","title":"HBR \"승진할수록 '대화 독점·세세한 간섭'을 과소평가한다\" — 전문직 1만 명·고위 리더 400명 연구","eTitle":"You Think You're a Good Collaborator. Do the People You Manage Agree?","kSum":"하이디 가드너(하버드 로스쿨 석좌 펠로)와 이반 마트비악은 1만 명 이상의 전문직과 400명의 고위 리더를 연구한 결과, 사람은 승진할수록 협업을 해치는 두 행동인 대화 독점과 세세한 간섭(micromanaging)을 점점 더 과소평가한다고 밝혔다. 많은 고위 리더가 스스로 경청하고 권한을 주는 협업가라고 여기지만 함께 일하는 사람들의 데이터는 다르게 나타났다. 이런 습관은 전문성을 보여 주고 높은 품질을 고집하던, 과거 성공을 이끈 강점에서 자라난다. 필자들은 자기 행동에 대한 솔직한 데이터를 구하고, 비판적 피드백을 합리화하지 말고, 문제 습관을 구체적인 대체 행동으로 바꾸고, 간단한 자기 점검 장치를 두라고 권한다.","eSum":"Heidi K. Gardner, a distinguished fellow at Harvard Law School, and Ivan Matviak draw on research with more than 10,000 professionals and 400 senior leaders to show that as people advance they increasingly underestimate two collaboration-damaging behaviors: dominating conversations and micromanaging. Most senior leaders describe themselves as listeners who empower others, but data from the people they work with tell a different story. Both habits grow out of strengths that drove earlier success, such as showing expertise and insisting on quality work. The authors recommend seeking honest data on one's own behavior, resisting the urge to rationalize critical feedback, replacing problem habits with specific alternatives and setting up simple accountability structures.","kImp":"팀장은 회의에서 자신이 말하는 시간과 팀원 문서를 직접 고쳐 쓰는 빈도를 스스로 과소평가하기 쉽다. 분기마다 팀원에게 '회의 독점'과 '세세한 간섭' 두 가지만 묻는 짧은 익명 피드백을 받고, 회의에서는 '먼저 묻고 마지막에 말하기'를 규칙으로 정해 볼 만하다.","eImp":"Team leaders tend to underestimate how much airtime they take in meetings and how often they rewrite their staff's documents themselves. Run a short quarterly anonymous survey asking team members about just these two behaviors, and adopt an 'ask first, speak last' rule for meetings.","url":"https://hbr.org/2026/09/you-think-youre-a-good-collaborator-do-the-people-you-manage-agree","prio":2,"kor":false,"tags":["LDR","COACH","COLLAB"],"tool":""},{"code":"LEAD","date":"2026-09-11","src":"DBR","title":"DBR '팀원마다 대화법을 다르게' — 코칭·멘토링·컨설팅·카운슬링을 '답이 있나, 미래인가 과거인가' 두 질문으로 고르고, 방식은 팀원에게 확인하라","eTitle":"DBR: Talk to Each Team Member Differently - Pick Coaching, Mentoring, Consulting or Counselling by Asking Whether They Have the Answer and Whether the Issue Is Future or Past, Then Confirm the Mode With Them","kSum":"DBR 팀장클럽 리포트(9월 11일)는 팀원의 성과를 끌어올리는 대화가 코칭만은 아니라며, 질문으로 팀원이 미래의 해결책을 찾게 돕는 코칭, 리더의 경험으로 해법을 제시하는 멘토링, 지나간 문제를 진단해 해결책을 제안하는 컨설팅, 어려움과 감정을 듣고 막힌 마음을 풀어 주는 카운슬링을 상황에 따라 골라 쓰라고 했다. 대화 전에 '이 사람에게 지금 답이 있는가', '다룰 것이 앞으로의 과제인가 지나간 일·감정인가'를 자문하고, '지금은 내가 방법을 알려줄까요, 아니면 같이 정리해 볼까요?' 한 문장으로 팀원이 원하는 방식을 확인하며, 답을 모르는 신입에게는 코칭보다 멘토링이나 컨설팅으로 길을 먼저 보여 주라고 권했다(구독 기사, 공개된 앞부분 기준).","eSum":"An 11 September piece in DBR's team-leader series says coaching is not the only conversation that lifts performance: coaching helps people find future solutions through questions, mentoring offers answers from the leader's experience, consulting diagnoses past problems and proposes fixes, and counselling listens to difficulties and emotions to clear blockages. Before a conversation, leaders should ask whether the person has the answer now and whether the topic is a future task or a past event or feeling, confirm the mode with one sentence such as 'Shall I show you how, or shall we work it out together?', and show newcomers who lack answers the way first through mentoring or consulting rather than coaching (subscriber article; summary based on the free opening section).","kImp":"1:1 면담이나 업무 지도 때 팀장이 먼저 '방법을 알려줄지, 같이 정리할지'를 묻는 습관을 들이고, 신입 직원에게는 첫 몇 주 동안 질문보다 실제 처리 예시를 먼저 보여 주는 방식으로 온보딩을 짜 볼 만하다.","eImp":"In one-to-ones and on-the-job guidance, team leaders could make a habit of first asking whether the person wants to be shown how or to work it out together, and design onboarding so new staff see worked examples in their first weeks before being coached with questions.","url":"https://dbr.donga.com/teamleader/view/article_no/176","prio":2,"kor":true,"tags":["COACH","LDR"],"tool":""},{"code":"LEAD","date":"2026-09-09","src":"Gallup","title":"갤럽: AI를 많이 쓸수록 '일자리 잃을까' 불안은 커지지만, 존중받고 배려받는다고 느끼는 직원은 그 격차가 최대 11.1%p 작다… 불안을 줄이는 건 기술이 아니라 관리자","eTitle":"Gallup: Frequent AI Users Fear Job Loss More, but the Gap Shrinks by Up to 11.1 Points Among Workers Who Feel Respected and Cared For, Making Managers the Key to Reducing Anxiety","kSum":"갤럽이 2026년 9월 9일 공개한 분석(2023년~2026년 1분기 4개 조사, 미국 직장인 약 3만 건 관측)에 따르면 AI를 매일 또는 주 여러 번 쓰는 직원은 드물게 쓰는 직원보다 5년 안에 자기 일자리가 없어질 것이라고 예상할 가능성이 두 배 이상 높았다. 그러나 존중받는다고 강하게 느끼는 직원은 잦은 AI 사용과 불안의 연관이 6.8%p, 회사가 자기 웰빙을 배려한다고 느끼는 직원은 11.1%p 작았다. 같은 사람을 시간에 따라 추적했을 때 이런 불안은 몰입 저하, 번아웃 증가, 적극적 구직 4.1%p 증가와 연결됐다. 갤럽은 AI 도입을 기술만이 아닌 소통의 과제로 보고, 자주 쓰는 직원과 1:1로 업무 변화·핵심 역량·평가 방식을 이야기하며, 연차가 짧은 직원에게는 직접 대화·멘토링을 우선하라고 권했다.","eSum":"Gallup, in an analysis published on 9 September 2026 using four waves of panel data on employed US adults from 2023 to Q1 2026 (nearly 30,000 worker observations), found that workers using AI daily or several times a week were more than twice as likely as infrequent users to expect their job to be eliminated within five years. Yet among workers who felt highly respected, the link between frequent AI use and displacement fear was 6.8 points smaller, and among those who felt their organisation cares about their wellbeing it was 11.1 points smaller. Tracking the same people over time, such fear was associated with lower engagement, higher burnout and a 4.1-point rise in active job searching. Gallup urges managers to treat AI rollout as a communication challenge, hold one-to-ones with frequent users on how their work, core skills and evaluation will change, and prioritise direct conversations and mentoring for less experienced staff.","kImp":"새 AI 도구를 팀에 들일 때 팀장은 공지 메일로 끝내지 말고 많이 쓰게 될 팀원과 1:1로 '무엇이 바뀌고 어떤 역량이 계속 중요한지, 평가는 어떻게 할지'를 설명하고, 도입 목적을 인력 감축이 아니라 팀 역량 강화로 분명히 밝히는 것이 불안을 줄인다.","eImp":"When bringing a new AI tool into the team, leaders should go beyond an announcement email, explain in one-to-ones with the heaviest users what will change, which skills remain central and how performance will be judged, and make clear the goal is stronger team capability rather than fewer people.","url":"https://www.gallup.com/workplace/713231/ai-not-reassure-workers-managers-do.aspx","prio":2,"kor":false,"tags":["LDR","AI","CHG"],"tool":""},{"code":"LEAD","date":"2026-09-08","src":"DBR","title":"DBR '열정적인 직원에게 일을 더 주는 관리자' — 일을 좋아하니 추가 업무도 좋아하리라는 '동기의 과잉 단순화', 핵심 업무 성과 저하 위험(Organization Science 2026)","eTitle":"DBR: Managers Give More Work to Passionate Employees - 'Motive Oversimplification' Assumes People Who Love Their Job Will Enjoy Extra Tasks Too, Risking Core Performance (Organization Science 2026)","kSum":"DBR 9월 2호(9월 8일 발행)는 Bae·Woolley의 2026년 『Organization Science』(37권 3호) 논문을 소개했다. 미국 노스이스턴대 연구진은 실제 관리자·직원 조사, 실제 직원 프로필을 쓴 실험, 추가 업무를 맡으면 금전적으로 손해를 보도록 설계한 실험 등 여러 조건에서 관리자가 내재적 동기가 높은 직원에게 추가 업무를 더 배정하는 경향을 일관되게 확인했고, 관리자가 직원의 기존 성과·근속·업무량을 알 때도 마찬가지였다. 원인은 '이 직원은 자기 일을 좋아한다'를 '추가 업무도 좋아하고 번아웃에도 강할 것'으로 넓혀 해석하는 '동기의 과잉 단순화'였는데, 실제로 그런 직원이 본업과 무관한 추가 업무를 더 즐기거나 번아웃에 강하지는 않았다(구독 기사, 공개된 앞부분 기준).","eSum":"DBR's 2nd September issue (published 8 September) reviews a 2026 Organization Science paper (vol. 37, no. 3) by Bae and Woolley. Northeastern University researchers found, across surveys of real managers and employees, experiments using real employee profiles and experiments where taking extra tasks cost participants money, that managers consistently assign additional work to intrinsically motivated employees, even when they know those employees' past performance, tenure and workload. The cause is 'motive oversimplification': managers stretch 'this person loves their job' into 'they will enjoy extra tasks and resist burnout', yet such employees did not actually enjoy unrelated extra tasks more or resist burnout better (subscriber article; summary based on the free opening section).","kImp":"팀장이 추가 업무(TF·회의 대응·자료 작성)를 배정할 때 '늘 맡아 주던 사람'에게만 가는지 분기마다 배정 내역을 살펴보고, 맡기기 전에 본업 일정과 함께 그 일을 하고 싶은지 직접 물어볼 만하다.","eImp":"Team leaders could review each quarter whether extra assignments such as task forces, meeting support or report writing keep landing on the same willing people, and ask directly whether someone wants the task, alongside their core workload, before assigning it.","url":"https://dbr.donga.com/article/view/1201/article_no/12262","prio":2,"kor":true,"tags":["LDR","WELL","PERF"],"tool":""},{"code":"LEAD","date":"2026-08-10","src":"SHRM","title":"SHRM \"지시형 관리만으론 부족, 코칭이 현장 관리자의 필수 역량\" — 상시 코칭 대화 실천법","eTitle":"Coaching Is Becoming a Core Leadership Skill for Frontline Managers","kSum":"SHRM 인도판은 인력의 기대 변화와 디지털화, 조직 전환으로 현장 관리자에게 지시형 관리만으로는 부족해졌고, 코칭이 문제가 커지기 전에 대응하는 선제적 역량이 됐다고 정리했다. 실천법으로 정답을 주기보다 직원이 문제를 풀고 선택지를 따져 보게 하기, 강점과 개선점을 짚는 정기 성장 대화, 적극적 경청과 건설적 피드백, 멘토링·동료 코칭·역할극 훈련, 연간 평가에만 기대지 않는 상시 코칭 대화를 제시했다. 리더 평가에 사업 성과뿐 아니라 직원 육성과 팀 역량 구축을 넣고, 디지털 학습 플랫폼과 대시보드는 코칭 대화를 돕되 대신하지 않게 하라고 권했다.","eSum":"SHRM India argues that changing workforce expectations, digitization and organizational transformation mean directive management alone is no longer enough for frontline managers, and that coaching is a proactive skill for tackling issues before they escalate. Recommended practices include asking employees to work through problems and weigh options instead of handing out instructions, regular development conversations, active listening with constructive feedback, and building coaching skill through mentoring, peer coaching and role-play, with coaching held regularly rather than only at annual reviews. It also advises adding employee development and team capability to leaders' appraisals and using digital platforms and dashboards to support, not replace, coaching conversations.","kImp":"팀장이 팀원의 질문에 답을 바로 주기보다 '어떻게 해 보면 좋겠나'를 먼저 묻고, 연말 평가 면담에만 기대지 말고 월 1회 짧은 성장 대화를 갖는 것부터 시작해 볼 만하다. 관리자 평가 항목에 팀원 육성 활동을 넣고, 팀장 교육에서 코칭 대화를 역할극으로 연습하는 것도 방법이다.","eImp":"Team leaders can start by asking 'how would you approach it?' before handing out answers, and by holding a short monthly development conversation instead of relying on the year-end review. Adding staff development to managers' appraisal criteria and practising coaching conversations through role-play in manager training also help.","url":"https://www.shrm.org/in/topics-tools/news/blogs/coaching-leadership-skill-frontline-managers","prio":1,"kor":false,"tags":["COACH","LDR","TRN"],"tool":""}]},{"code":"COMM","kTitle":"커뮤니케이션 — 회의·보고·메일·어려운 대화","eTitle":"Communication - meetings, reports, email and difficult conversations","items":[{"code":"COMM","date":"2026-10-28","src":"지디넷코리아","title":"딥엘 \"외국어 회의에서 질문 망설이고 동료에게 대신 말해 달라 해\"…한국 직장인 연구 공개, 회의용 실시간 번역 데스크톱 앱 출시","eTitle":"DeepL Study of Korean Office Workers Finds Staff Hesitate to Ask Questions in Foreign-Language Meetings, as It Launches a Desktop App With Live Translated Captions for Zoom, Teams and Meet","kSum":"딥엘은 28일 한국 직장인 16명(4개 그룹)이 모의 외국어 회의에서 실시간 번역 자막을 써 본 심층 연구 결과를 공개했다. 참가자들은 외국어 회의에서 질문을 망설이거나 동료에게 대신 말해 달라고 했고, 회의 뒤 녹음·이메일을 다시 확인하는 후속 작업이 늘었다고 답했으며, 업계 용어·숫자의 정확한 번역, 사내 데이터 보안, 여러 명이 동시에 말할 때의 화자 구분을 요구했다. 앞서 3월 직장인 500명 조사에서는 89.8%가 업무용 AI 음성 통역이 필요하다고 했지만 실제 사용은 35.8%였다. 딥엘은 줌·팀즈·구글 미트와 연동해 회의를 자동 감지하고 번역 자막·음성을 제공하는 데스크톱 앱을 새로 내놨으며, 16명 연구는 대표성이 없다고 밝혔다.","eSum":"DeepL on 28 October published an in-depth study in which 16 Korean office workers in four groups used live translated captions in simulated foreign-language meetings. Participants said they hesitated to ask questions or asked colleagues to speak for them, and spent more time afterwards rechecking recordings and emails; they wanted accurate handling of jargon and numbers, secure treatment of company data and speaker separation. An earlier March survey of 500 workers found 89.8% saw a need for AI voice translation at work but only 35.8% used it. DeepL also launched a desktop app that detects Zoom, Teams and Google Meet calls and shows translated captions and audio, and said the 16-person study is not representative.","kImp":"해외 본사·현지 법인과의 영어 회의에서는 발언 기회가 영어 실력에 좌우되지 않도록 안건과 핵심 용어집을 미리 돌리고 질문은 채팅으로도 받으며, 실시간 번역 도구를 쓸 때는 회의 내용이 외부 서버로 넘어가는지 먼저 확인해야 한다.","eImp":"For English meetings with overseas head offices or partners, circulating the agenda and a glossary of key terms in advance and accepting questions in the chat helps keep speaking time from depending on language skill, and before using live translation tools teams should check whether meeting content leaves for external servers.","url":"https://zdnet.co.kr/view/?no=20261028113722","prio":2,"kor":true,"tags":["XC","MTG","TOOL"],"tool":"DeepL Voice"},{"code":"COMM","date":"2026-10-20","src":"세계일보","title":"엠브레인 조사 \"퇴근 후 업무 연락 부담\" 52.2%로 2년 전보다 4.4%p↓…77.7%는 '근무시간 외엔 연락 안 하는 게 당연하다'는 인식 확대돼야","eTitle":"Embrain Survey: 52.2% of Korean Workers Find After-Hours Work Messages a Burden, Down 4.4 Points in Two Years, While 77.7% Say the Expectation of No Contact Outside Working Hours Should Spread","kSum":"엠브레인 트렌드모니터가 전국 19~69세 직장인 1,000명을 대상으로 한 '2026 직장 업무 환경 및 연결되지 않을 권리 관련 인식 조사'에서 퇴근 후·휴일 업무 연락이 부담된다는 응답은 52.2%로 2024년보다 4.4%p 줄었고, 그런 연락을 하는 사람이 잘못이라는 응답도 55.7%로 7.1%p 낮아졌다. 그럼에도 77.7%는 근무시간 외 업무 연락을 하지 않는 것이 당연하다는 인식이 확대돼야 한다고 답했다. '연결되지 않을 권리'를 법으로 보장해야 한다는 응답은 48.8%(2024년 53.5%)로 줄었고, 시행 방식으로는 '법제화보다 사내 규칙으로'(46.6%)가 '법으로 강력히 규제'(25.5%)보다 많았다. 직장에서 워라밸이 실현되고 있다는 응답은 68.0%로 5.3%p 올랐다.","eSum":"Embrain Trend Monitor's 2026 survey of 1,000 employed adults aged 19-69 found 52.2% consider after-hours or holiday work contact a burden, down 4.4 points from 2024, and 55.7% blame colleagues who make such contact, down 7.1 points. Even so, 77.7% said the view that work contact should not happen outside working hours needs to spread. Support for guaranteeing a 'right to disconnect' in law fell to 48.8% from 53.5%, and 46.6% preferred implementing it through company rules rather than legislation, against 25.5% who wanted strong legal regulation. The share saying work-life balance is achieved at their workplace rose 5.3 points to 68.0%.","kImp":"법 제정을 기다리기보다 팀 안에서 '퇴근 후 메신저는 긴급 건만, 나머지는 예약 발송' 같은 규칙을 정하고, 긴급의 기준(사고·선박 비상 등)과 연락 순서를 미리 합의해 두면 부담을 줄일 수 있다.","eImp":"Rather than waiting for legislation, a team can agree its own rule such as after-hours messages for emergencies only and scheduled sending for everything else, with a shared definition of what counts as urgent, such as an incident or a vessel emergency, and a contact order.","url":"https://www.segye.com/newsView/20261020507204","prio":2,"kor":true,"tags":["WR","WELL","POL"],"tool":""},{"code":"COMM","date":"2026-10-09","src":"SHRM","title":"어려운 대화일수록 감정지능이 승부를 가른다: SHRM, 성과 피드백·갈등·민감한 고충 대화별 실천법과 역할극 연습을 권고","eTitle":"SHRM: Emotional Intelligence Matters Most in Difficult Workplace Conversations, With Practical Steps for Feedback, Conflict and Sensitive Issues and Role-Play Practice","kSum":"SHRM 인도판 블로그가 2026년 10월 9일 실은 글은 성과 면담, 의견 충돌, 민감한 고충 처리처럼 어려운 대화에서는 양쪽 모두 감정과 기대를 안고 들어오기 때문에 이를 인정하지 않으면 대화가 본래 쟁점에서 벗어난다고 짚었다. 관리자는 자기 인식·자기 관리로 충동적 반응을 피하고 직원이 방어적으로 나오는 이유(기대치 혼란, 결과에 대한 걱정, 전달 방식에 대한 반응)를 읽어야 하지만, 공감은 편을 들거나 특정 결과를 약속하는 것이 아니며 규정·기록·비밀 유지 같은 HR 절차를 대신하지도 않는다고 했다. 실천법으로는 피드백 때 구체적 사례와 그 중요성을 설명하고 상대 관점을 물은 뒤 바뀌어야 할 점을 분명히 하기, 갈등 때 감정은 인정하되 사람이 아닌 쟁점에 집중하기, 민감한 사안은 다음 절차부터 설명하기, 역할극·시뮬레이션으로 미리 연습하기를 제시했다.","eSum":"A SHRM India blog post published on 9 October 2026 argues that in difficult conversations such as performance discussions, disagreements and sensitive complaints, both sides bring emotions and expectations that, if unacknowledged, pull the discussion away from the real issue. Managers need self-awareness and self-management to avoid reacting on impulse and social awareness to understand why an employee becomes defensive, but empathy does not mean taking sides or promising an outcome, nor does it replace HR procedures on policy, documentation and confidentiality. It recommends giving specific examples and explaining why an issue matters before asking for the employee's view and stating what must change, acknowledging frustration in conflicts while keeping the focus on the issue rather than personalities, explaining next steps clearly in sensitive matters, and rehearsing through role-play and simulations.","kImp":"평가 면담 전에 팀장이 '구체적 사례→왜 중요한가→상대 의견 듣기→다음에 바뀌어야 할 점' 순서로 메모를 준비하고, 동료 팀장과 반론이 나오는 상황을 5분씩 역할극으로 연습해 보면 실제 면담에서 감정적 충돌을 줄일 수 있다.","eImp":"Before appraisal meetings, team leaders can prepare notes in the order of specific example, why it matters, the employee's view and what must change next, and rehearse a five-minute role-play with a fellow manager in which the employee pushes back, reducing emotional clashes in the real conversation.","url":"https://www.shrm.org/in/topics-tools/news/blogs/emotional-intelligence-matters-most-when-workplace-conversations","prio":1,"kor":false,"tags":["COACH","LDR","TRN"],"tool":""},{"code":"COMM","date":"2026-10-07","src":"Harvard Business Review","title":"HBR: 리더십 팀의 문제는 갈등 과잉이 아니라 '수동적 평화'… 서로의 영역을 건드리지 않는 침묵이 결정을 약하게 만든다","eTitle":"HBR: Executive Teams Suffer More From 'Passive Peace' Than From Conflict, as Leaders Avoid Challenging Each Other Outside Their Own Silos","kSum":"HBR이 2026년 10월 7일 실은 레베카 뉴턴(25년간 경영진 팀 자문)의 글은 많은 리더십 팀이 갈등이 너무 많아서가 아니라 너무 적어서 문제라고 지적했다. 임원들이 존중을 이유로 서로의 사일로를 각자에게 맡기고, 자기 영역 밖을 질문하면 비협조적이거나 일을 늦춘다고 보일까 봐 반대 의견을 내지 않는 '수동적 평화'에 빠진다는 것이다. 글은 생산적 갈등이 다양한 관점을 드러내고 결정의 질을 높인다며 공동의 목적을 분명히 하고, 회의를 현황 보고가 아닌 질문 중심으로 짜고, 대인 신뢰를 쌓고, 동료끼리 긴장을 직접 다루도록 하라고 권했다. (구독 기사, 공개된 앞부분 기준)","eSum":"In a Harvard Business Review article published on 7 October 2026, Rebecca Newton, who has advised senior teams for 25 years, argues that many leadership teams have too little conflict rather than too much. Executives settle into a 'passive peace', leaving peers to run their own silos and holding back dissent for fear that questioning outside their area will seem unhelpful or slow things down. Arguing that productive conflict surfaces different perspectives and improves decisions, she recommends clarifying the team's shared purpose, structuring meetings around questions rather than updates, building interpersonal trust and encouraging peers to address tensions directly. (Subscription article; based on the publicly visible opening section.)","kImp":"부서장 회의에서 각 부서 보고는 미리 서면으로 받고, 회의 시간에는 '이 안건에서 가장 걱정되는 점은?' 같은 질문을 돌아가며 던져 다른 부서 안건에도 의견을 내는 것을 당연한 일로 만들어 볼 만하다.","eImp":"Managers' meetings can take departmental reports in writing beforehand and use the meeting to go round the table with questions such as 'what worries you most about this item?', making it normal to comment on other departments' business.","url":"https://hbr.org/2026/10/your-executive-team-needs-more-productive-conflict","prio":2,"kor":false,"tags":["MTG","LDR","PS"],"tool":""},{"code":"COMM","date":"2026-09-30","src":"충청시사신문","title":"대전도시공사 직원 설문 \"상사에게 가장 듣기 싫은 말은 '네가 알아서 해'\", 듣고 싶은 말은 '문제가 생기면 같이 해결하자'…후배의 '제 업무 아닌데요'도 꼽혀","eTitle":"Daejeon Urban Corporation Staff Survey Finds the Phrase Employees Least Want From Bosses Is 'Figure It Out Yourself', the Most Wanted Is 'Let's Solve It Together if Problems Arise', and the Least Wanted From Juniors Is 'That's Not My Job'","kSum":"대전도시공사가 9월 15~17일 직원 323명을 대상으로 한 '2026 PLUS & SWITCH 존중소통 설문'(203명 참여)에서 선배·상사에게 가장 듣기 싫은 말은 일을 맡긴 뒤 결과를 비판하는 '네가 알아서 해'였고, 가장 듣고 싶은 말은 '문제가 생기면 같이 해결하자'였다. 후배에게 가장 듣고 싶은 말은 '제가 한번 해 보겠습니다', 가장 듣기 싫은 말은 '그건 제 업무가 아닌데요'였다. 공사는 지난 3년간 비슷한 설문에서 일방적 지시, 과거 경험과의 비교, 업무 범위 다툼이 반복됐다며 업무의 목적과 기준을 먼저 공유한 뒤 역할과 협업을 확인하고, 질책을 '어디서 막혔는지 같이 보자'는 질문으로 바꾸는 '존중대화 10선'을 사내외에 공개하고 괴롭힘 예방 교육에 활용하기로 했다. 결과는 비율 없이 순위로만 공개됐다.","eSum":"In Daejeon Urban Corporation's respectful-communication survey of its 323 staff on 15-17 September (203 responses), the phrase employees least wanted to hear from seniors was 'figure it out yourself', said when handing over work and then criticising the result, and the most wanted was 'let's solve it together if problems arise'. From juniors, staff most wanted 'I'll give it a try' and least wanted 'that's not my job'. Noting that one-way instructions, comparisons with seniors' past experience and disputes over task scope had recurred in three years of similar surveys, the corporation published ten respectful-conversation examples, such as sharing a task's purpose and standards first and turning criticism into a question about where someone got stuck, for use in harassment-prevention training. Results were released as rankings only.","kImp":"업무를 넘길 때 '알아서 해' 대신 목적·마감·완료 기준을 한 줄로 적어 주고, 결과가 기대와 다를 때는 '어디서 막혔는지 같이 보자'로 대화를 시작하는 연습을 팀 규칙으로 정해 볼 만하다.","eImp":"When handing over work, a team can replace 'figure it out yourself' with a one-line note of purpose, deadline and definition of done, and agree as a team norm to open conversations about disappointing results with 'let's look at where you got stuck'.","url":"https://www.csnnews.co.kr/news/articleView.html?idxno=32589","prio":1,"kor":true,"tags":["SPEAK","PS","LDR"],"tool":""},{"code":"COMM","date":"2026-09-24","src":"Harvard Business Review","title":"HBR IdeaCast: AI는 초안·요약·리허설에, 피드백·갈등 같은 감정적 대화는 사람이… 매트 에이브러햄스·웨이드 포스터가 말하는 AI 시대 소통 원칙","eTitle":"HBR IdeaCast: Use AI for Drafting, Summaries and Rehearsal but Keep Feedback and Conflict Human, Say Matt Abrahams and Zapier's Wade Foster","kSum":"HBR IdeaCast가 2026년 9월 24일 내보낸 AI와 리더십 시리즈 2편에서 스탠퍼드대 매트 에이브러햄스 교수와 재피어의 웨이드 포스터 CEO는 AI를 빈 페이지 극복, 슬랙·이메일·회의록 요약, 회의적인 청중 역할극 같은 준비·종합·리허설에 쓰되, 부정적 평가·건설적 피드백·팀 갈등처럼 감정이 큰 대화는 리더가 직접 하라고 조언했다(어려운 대화를 맡기면 '공감 능력이 퇴화한다'). 포스터는 '일은 위임해도 책임은 위임할 수 없다'며 AI 결과물을 반드시 검토하고 요약에서 발언자가 뒤바뀌지 않았는지 확인하라고 했고, 재피어는 문서에 AI 관여 정도를 표시한다고 소개했다. 두 사람은 쓰는 사람이 읽는 사람보다 더 많은 노력을 들여야 하며, AI에 지나치게 기대면 후속 질문에 답하지 못하고 주니어 직원은 자기 목소리를 잃을 수 있다고 경고했다.","eSum":"In an HBR IdeaCast bonus episode released on 24 September 2026, the second in a series on AI and leadership, Stanford's Matt Abrahams and Zapier CEO Wade Foster advised using AI to get past the blank page, summarise Slack, email and meeting notes, and rehearse with sceptical personas, while keeping emotionally charged conversations such as negative reviews, constructive feedback and team conflict personal to avoid 'empathy atrophy'. Foster's rule is that you can delegate the work but not the accountability, so leaders must review AI output and check summaries for misattributed speakers, and Zapier labels how much AI was involved in a piece of work. Both stressed that writers should put in more effort than readers, warning that over-delegating leaves people unable to answer follow-up questions and that junior staff may lose their own voice.","kImp":"팀 안에 'AI로 초안·요약은 해도 되지만 평가 피드백과 갈등 조정은 직접 한다', '외부·고객 문서는 사람이 최종 검토하고 AI 사용 여부를 밝힌다' 같은 간단한 소통 규칙을 정해 두면 품질과 신뢰를 함께 지킬 수 있다.","eImp":"Simple team rules, such as allowing AI for drafts and summaries but delivering appraisal feedback and resolving conflicts personally, and having a person give external or customer documents a final review with AI use disclosed, protect both quality and trust.","url":"https://hbr.org/podcast/2026/09/how-ai-is-changing-communication-weighing-efficiency-with-efficacy","prio":2,"kor":false,"tags":["WRT","AI","COACH"],"tool":""},{"code":"COMM","date":"2026-09-22","src":"HR Insight","title":"회의가 15분 일찍 끝나는 팀이 위험하다 — 이모지 동의 뒤에 숨은 ‘가짜 조화’, 솔직해도 괜찮다는 신뢰가 없으면 리스크가 묻힌다","eTitle":"Beware the Meeting That Ends 15 Minutes Early: How 'Artificial Harmony' Buries Risk When Teams Lack Vulnerability-Based Trust","kSum":"유준희 조직문화 공작소 대표는 팀장이 이견을 물어도 정적 뒤에 동의 이모지만 남고 회의가 예정보다 15분 일찍 끝나는 장면을 들어, 반대하면 '까칠한 사람'으로 찍힐까 넘기는 '친절함의 함정'이 생기고 슬랙·노션·생성형 AI 같은 도구가 갈등 회피를 더 정교하게 만든다고 진단했다. 패트릭 렌치오니의 '가짜 조화(Artificial Harmony)' 개념을 빌려, 이는 솔직하게 말해도 비난이나 불이익이 없다는 취약성 기반 신뢰가 없을 때 나타나는 방어기제이며 그 결과 프로젝트의 결함과 리스크가 테이블에 오르지 못한다고 지적했다. 억눌린 불만은 뒷담화로 '발효'되고 문제를 감지한 구성원은 자기 판단을 의심하며 입을 닫거나 가장 먼저 지쳐 떠난다며 '아홉 번의 불편함을 삼킨 조직은 열 번째에 가장 치명적인 방식으로 갈등을 터뜨릴 수 있다'고 경고했다(구독 기사로 진단 신호 목록 등 후반부 비공개).","eSum":"Yoo Jun-hee, head of an organisational culture consultancy, describes a team that answers the leader's call for objections with silence and approving emojis and finishes its meeting 15 minutes early, arguing that a 'niceness trap', in which people let things pass for fear of being seen as difficult, is made more sophisticated by tools such as Slack, Notion and generative AI. Drawing on Patrick Lencioni's concept of artificial harmony, he calls it a defence mechanism that appears when there is no vulnerability-based trust that candour will not be punished, so project flaws and risks never reach the table. Suppressed doubts ferment into gossip, people who sense problems start doubting their own judgement and fall silent or burn out and leave first, and an organisation that swallows discomfort nine times may let conflict erupt in the most damaging way the tenth time (subscriber article; the list of warning signs and later sections are not public).","kImp":"회의에서 이견이 하나도 나오지 않거나 메신저에 동의 이모지만 달리면 바로 마무리하지 말고, '이 계획이 실패한다면 이유는 무엇일까'를 한 사람씩 묻는 순서를 넣어 볼 만하다. 반대 의견을 낸 사람에게 팀장이 먼저 고맙다고 말하는 장면이 쌓여야 솔직해도 괜찮다는 신뢰가 생긴다.","eImp":"When a meeting produces no objections or a chat thread fills with approving emojis, don't close it straight away; ask each person in turn how the plan might fail. Trust that candour is safe builds when people repeatedly see the team leader thank whoever raised a concern.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39593","prio":2,"kor":true,"tags":["MTG","PS","SPEAK"],"tool":""},{"code":"COMM","date":"2026-09-22","src":"The HR Digest","title":"관리자 42% '할 말은 아는데 어떻게 말할지가 어렵다'… PI 조사, CEO 74%는 관리자의 어려운 대화 역량을 과신하고 관리자 44%는 직원 이름·성과를 공개 AI에 입력","eTitle":"Predictive Index Survey: 42% of Managers Know What to Say but Struggle With How, While 74% of CEOs Overrate Their Readiness and 44% of Managers Have Entered Employee Details Into Public AI","kSum":"The HR Digest가 2026년 9월 22일 정리한 프리딕티브 인덱스(PI)의 '2026 AI and People Leadership' 조사(7월 초, 관리자 399명·CEO 및 경영진 208명)에서 CEO·경영진의 74%는 관리자가 직무와 어려운 대화를 '매우 자신 있게' 다룬다고 봤지만, 관리자들은 더 많은 지침과 구조가 필요하다고 답했고 리더·HR의 개입 없이 혼자 하길 원한 관리자는 20%뿐이었다. 관리자의 42%는 무엇을 말할지는 알지만 어떻게 말할지가 어렵다고 했고, 건설적 비판 전달(22.8%), 상대 반응 예상(19.5%), 객관성 유지(14.3%)가 난제로 꼽혔다. 72% 이상은 공개 AI 도구가 면담 준비에 도움이 된다고 했지만 44%는 직원 이름과 성과 정보를 입력한 적이 있었고, 관리자의 AI 사용에 관한 서면 정책을 둔 조직은 45%였다.","eSum":"The HR Digest on 22 September 2026 summarised The Predictive Index's 2026 AI and People Leadership Survey, conducted in early July among 399 managers and 208 CEOs and business leaders. While 74% of CEOs and leaders said managers were very confident handling difficult conversations, managers said they wanted more guidance and structure, and only 20% preferred a hands-off approach. Some 42% of managers knew what they wanted to say but struggled with how to say it, citing delivering criticism constructively (22.8%), anticipating reactions (19.5%) and staying objective (14.3%). Over 72% found public AI tools helpful for preparing, but 44% had entered employee names and performance details into them, and only 45% of organisations had a formal written policy on managers' AI use for people matters.","kImp":"성과 면담·어려운 대화를 앞둔 팀장에게 HR이 대화 틀과 예상 반응 대처법을 미리 제공하고, 직원 실명·평가 정보를 외부 AI 서비스에 넣지 않도록 사내 지침부터 정해 두는 것이 안전하다.","eImp":"HR should give team leaders a conversation framework and tips on likely reactions before appraisal meetings or difficult conversations, and first set an internal rule against entering employees' names or appraisal details into external AI services.","url":"https://www.thehrdigest.com/ceos-often-overestimate-managers-readiness-to-navigate-difficult-conversations/","prio":2,"kor":false,"tags":["COACH","AI","SEC"],"tool":""},{"code":"COMM","date":"2026-09-15","src":"Knowledge at Wharton","title":"와튼 셸 교수의 설득 팁: 새 아이디어에 주어지는 시간은 약 5분… '문제의 정당성→경위→해법→대안보다 나은 이유' 4단 구조로 말하고, 결정 전에 선택지를 들고 상의하라","eTitle":"Wharton's Richard Shell on Persuasion: Listeners Give a New Idea About Five Minutes, So Use a Four-Part Pitch and Consult on Several Options Before the Decision Is Made","kSum":"Knowledge at Wharton이 2026년 9월 15일 실은 G. 리처드 셸 교수의 'Nano Tools for Leaders' 글은 설득이 좋은 논리보다 준비에 달려 있다며 누구를 어떤 순서로 만날지 정하고 대화마다 목표와 예상 저항을 정리하라고 조언했다. 그는 듣는 사람이 새 아이디어에 시간을 더 쓸지 약 5분 안에 판단한다며, 문제가 실재한다는 점, 문제가 생긴 경위, 해법, 뻔한 대안보다 나은 이유의 4단 구조로 말하고 중간에 끼어들어도 흔들리지 않을 만큼 연습하라고 권했다. 또 공로를 넉넉히 나누고, 호의·소개·일정 조정에서 주고받음을 지키며, 해법을 2~3개 만들어 결정이 아직 바뀔 수 있을 때 영향을 받는 사람들과 먼저 상의하라고 했다(결정 뒤 의견을 묻는 것은 상의가 아니라 통보).","eSum":"In a Nano Tools for Leaders article published by Knowledge at Wharton on 15 September 2026, professor G. Richard Shell argues that persuasion depends on preparation, including mapping whom to approach and in what order, setting a goal for each conversation and anticipating resistance. Because listeners give a new idea about five minutes before deciding whether it deserves more time, he recommends a four-part structure, establishing that the problem is real, explaining how it arose, stating the solution plainly and showing why it beats the obvious alternatives, rehearsed until it survives interruption. He also urges sharing credit generously, keeping working relationships reciprocal and developing two or three options to share with those affected while their input can still change the decision, since asking after the choice is made is notification, not consultation.","kImp":"부서 간 협조가 필요한 제안을 올릴 때는 결재 전에 관련 부서 담당자에게 2~3개 선택지를 먼저 보여 의견을 반영하고, 보고 첫머리는 '왜 지금 문제인가→원인→제안→다른 안보다 나은 이유' 순서로 짜 보면 좋다.","eImp":"Before submitting a proposal that needs other departments' cooperation, show their staff two or three options and fold in their views, and open the report with why the problem matters now, its cause, the proposal and why it beats the alternatives.","url":"https://knowledge.wharton.upenn.edu/article/top-tips-for-persuading-others/","prio":1,"kor":false,"tags":["WRT","LDR"],"tool":""},{"code":"COMM","date":"2026-09-14","src":"Harvard Business Review","title":"HBR 연구: 리더의 유머는 '놀라움+즉각적 이해'가 있을 때 통한다… 6개 실험·약 1,300명, 알아듣기 쉬운 농담이 더 웃기지만 공격적 농담은 쉬워도 불쾌","eTitle":"HBR Research: Leaders' Humour Works When Surprise Meets Instant Clarity, as Six Experiments With Nearly 1,300 People Find Easy-to-Process Jokes Funnier but Aggressive Ones Still Offensive","kSum":"HBR이 2026년 9월 14일 실은 드루 고렌즈·노버트 슈워츠(USC)의 연구는 농담·밈·장난스러운 별명을 다룬 6개 실험(참가자 약 1,300명)에서 청중이 쉽게 처리할 수 있는 유머일수록 더 재미있게 평가된다는 결과를 보고했다. 또렷한 소리·화면과 운율·두운은 펀치라인을 더 그럴듯하게 만들었지만, 공격적인 유머는 이해하기 쉬워도 불쾌감이 줄지 않았다. 저자들은 실패한 유머가 리더에 대한 존중·호감·유능성 인식을 떨어뜨린다는 기존 연구를 들며, 공유된 경험과 익숙한 소재로 짧고 리듬감 있게 말하라고 권했다. (구독 기사, 공개된 앞부분 기준)","eSum":"In a Harvard Business Review article published on 14 September 2026, Drew Gorenz and Norbert Schwarz of USC report six experiments with nearly 1,300 participants testing jokes, memes and playful nicknames, finding humour was rated funnier when it was easy to process. Clear audio and visuals helped, and rhyme and alliteration made punchlines feel more fitting, but ease of processing did not reduce the offence caused by aggressive humour. Citing research linking failed humour to lower respect, likability and perceived competence for leaders, they advise keeping humour easy to hear and recognise, concise and built on shared experiences and familiar references. (Subscription article; based on the publicly visible opening section.)","kImp":"회의나 발표에서 분위기를 풀 때는 팀이 함께 겪은 일처럼 누구나 바로 알아듣는 소재를 짧게 쓰고, 특정인이나 집단을 겨냥한 농담은 다국적 팀일수록 더 위험하므로 피하는 것이 안전하다.","eImp":"To lighten a meeting or presentation, use brief references everyone recognises instantly, such as shared team experiences, and avoid jokes aimed at any person or group, which carry even more risk in multinational teams.","url":"https://hbr.org/2026/09/leaders-dont-let-your-jokes-fall-flat","prio":1,"kor":false,"tags":["LDR"],"tool":""},{"code":"COMM","date":"2026-09-08","src":"DBR","title":"DBR '재택근무자는 상사 요청에 더 빨리 답한다' — 노력이 보이지 않을까 하는 '비가시성 불안' 때문, 협업 기록 175만여 건 자연실험(AMJ 2026)","eTitle":"DBR: Remote Workers Answer the Boss Faster - 'Invisibility Anxiety' Drives Responsiveness, Shows a Natural Experiment With 1.76 Million Collaboration Records (AMJ 2026)","kSum":"DBR 9월 2호(9월 8일 발행)는 메릴랜드대·애리조나주립대·베이징대 등 공동 연구진(Liao 외)의 2026년 『Academy of Management Journal』 논문 'Visible from Afar'를 소개했다. 연구진은 재택근무 명령 전후 실제 직장의 협업 기록 175만8,540건을 분석한 자연실험에 직장인 설문, 사전 등록한 상황 실험 2건과 2단계 행동 실험을 더해, 재택근무가 자신의 노력이 관리자에게 보이지 않거나 인정받지 못할지 모른다는 '비가시성 불안'을 키우고 그 때문에 상사의 협업 요청에 더 적극적으로 반응하게 만든다는 점을 일관되게 확인했다(구독 기사, 공개된 앞부분 기준).","eSum":"DBR's 2nd September issue (published 8 September) reviews 'Visible from Afar', a 2026 Academy of Management Journal paper by Hui Liao and colleagues at the University of Maryland, Arizona State University and Peking University. Combining a natural experiment on 1,758,540 collaboration records from before and after work-from-home orders with an employee survey, two preregistered scenario experiments and a two-stage preregistered behavioural experiment, the researchers consistently found that remote work raises 'invisibility anxiety', the fear that one's effort will go unseen or unrecognised by managers, and makes employees respond more eagerly to managers' collaboration requests (subscriber article; summary based on the free opening section).","kImp":"재택·외근 직원에게 '메신저에 바로 답해야 한다'는 암묵적 압박이 생기지 않도록 팀 안에서 응답 기대 시간(긴급은 전화, 일반 요청은 반나절 안 등)을 정하고, 성과는 즉답 속도가 아니라 결과로 본다는 점을 팀장이 분명히 해 둘 만하다.","eImp":"To avoid an unspoken pressure on remote or field staff to reply instantly, teams could agree response expectations, such as a phone call for urgent matters and half a day for ordinary requests, and leaders could make clear that performance is judged on results, not reply speed.","url":"https://dbr.donga.com/article/view/1201/article_no/12260","prio":2,"kor":true,"tags":["REMOTE","COLLAB","WELL"],"tool":""},{"code":"COMM","date":"2026-08-25","src":"SHRM","title":"SHRM \"신입의 소통 격차는 지식이 아니라 실전 준비의 문제\" — 8주 역할극·성찰 프로그램 사례","eTitle":"Bridging the Communication Gap for the Early-Career Workforce","kSum":"HR·교육 전문가 차나 소이퍼트(교육학 박사)는 SHRM 기고에서, 초기 경력 직원의 소통 문제는 소통이 중요하다는 걸 몰라서가 아니라 실제 상황에서 쓸 준비가 안 된 데서 온다고 진단했다. 교육은 갈등 해결·발표 같은 고급 기술에 치우치지만 신입은 명확한 업무 글쓰기, 회의 참여, 상대에 맞춘 메시지 같은 기본기에서 더 어려움을 겪는다. 그가 기업 현장에서 운영한 8주 프로그램(10주로 연장 권고)은 시나리오 활동·역할극·성찰·동료 피드백을 평가가 아닌 심리적으로 안전한 학습 환경에서 진행했고, 참가자들은 자신감이 늘고 응답 전에 멈추고 더 경청하게 됐다고 보고했다.","eSum":"Writing for SHRM, HR and learning leader Charna Soifert, EdD, argues that early-career communication gaps stem less from a lack of awareness than from not being ready to communicate in real workplace situations. Training tends to target advanced skills such as conflict resolution and presentations, while new hires struggle more with basics like clear professional writing, meeting participation and audience-centered messaging. Her eight-week workplace program, which she suggests extending to ten, used scenarios, role-play, guided reflection and peer feedback in a psychologically safe, non-evaluative setting, and participants reported more confidence, more active listening and pausing before responding.","kImp":"신입·저연차 직원은 소통이 중요하다는 걸 알아도 업무 메일을 간결하게 쓰거나 회의에서 의견을 말하는 기본기에서 막히기 쉽다. 온보딩 기간에 보고 메일 쓰기·회의 발언·상사에게 문제 알리기를 실제 상황으로 연습하는 짧은 세션을 몇 주에 걸쳐 넣되, 평가와는 분리해 운영해 볼 만하다.","eImp":"New and junior staff may know communication matters yet still struggle with basics such as writing a concise work email or speaking up in meetings. Add a few weeks of short practice sessions to onboarding, covering report emails, meeting contributions and raising problems with a manager, and keep them separate from performance evaluation.","url":"https://www.shrm.org/topics-tools/news/bridging-communication-gap-early-career-workforce","prio":1,"kor":false,"tags":["TRN","WRT","MTG"],"tool":""},{"code":"COMM","date":"2026-08-03","src":"Harvard Business Review","title":"HBR \"좋은 조언의 기준은 문화마다 다르다\" — 미국은 자율, 인도는 분명한 지시, 중국은 여러 갈래 검토","eTitle":"What to Consider Before Giving Advice on a Global Team","kSum":"나므라타 고얄(에사데 경영대학원)과 크리슈나 사바니(홍콩이공대) 교수는 문화마다 어떤 조언이 도움이 되고 존중받으며 지지적인지에 대한 기대가 다르다는 새 연구를 소개했다. 미국인은 받는 사람의 자율성을 지켜 주는 조언을, 인도인은 조언자의 헌신을 보여 주는 분명하고 지시적인 권고를, 중국인은 여러 가능한 경로를 탐색하고 복잡성을 인정하는 조언을 더 높이 평가하는 경향이 있었다. 필자들은 이런 기대 차이를 아는 리더가 신뢰를 쌓고 멘토링과 글로벌 팀 협업을 강화할 수 있다며, 한 가지 방식이 모두에게 통한다고 가정하지 말고 조언의 의도를 분명히 밝히라고 권한다.","eSum":"Namrata Goyal of Esade Business School and Krishna Savani of Hong Kong Polytechnic University describe new research showing that people from different cultures hold different assumptions about what makes advice helpful, respectful and supportive. Americans tended to value advice that preserves the recipient's autonomy, Indians preferred clear, directive recommendations that signal the adviser's commitment, and Chinese respondents favored advice that explores multiple possible paths and acknowledges complexity. The authors say leaders who recognize these expectations can build trust, strengthen mentoring and improve global team collaboration, and urge them to make the intent behind their advice explicit rather than assume one style fits everyone.","kImp":"해외 본사·지사 동료나 외국인 팀원에게 조언할 때 같은 말도 상대 문화에 따라 '간섭'이나 '무책임'으로 들릴 수 있다. 메일이나 화상회의에서 조언할 때 '꼭 이렇게 해 달라는 요청입니다' 또는 '참고할 선택지입니다'처럼 의도를 먼저 밝히는 습관을 들여 볼 만하다.","eImp":"When advising overseas head-office colleagues or international team members, the same words can sound like interference to one person and a lack of commitment to another. In emails and video calls, say up front whether you are making a firm request or offering options to consider.","url":"https://hbr.org/2026/08/what-to-consider-before-giving-advice-on-a-global-team","prio":2,"kor":false,"tags":["XC","COACH"],"tool":""}]},{"code":"COLLAB","kTitle":"협업·팀워크 — 부서 간 협업·하이브리드 팀","eTitle":"Collaboration and teamwork - across departments and hybrid teams","items":[{"code":"COLLAB","date":"2026-10-27","src":"DBR","title":"DBR 'AI 위한 데이터 확보에 치중하다간 집단지성 잃는다' — AI 채용 도입 뒤 면접관들이 함께 의견을 나누던 평가 회의가 사라진 글로벌 소비재 기업 사례(ASQ 2026)","eTitle":"DBR: Chasing Data for AI Can Cost Collective Judgement - A Global Consumer-Goods Firm Dropped Interviewers' Joint Review Meetings After Adopting AI Hiring (ASQ 2026)","kSum":"DBR 11월 1호(10월 27일 발행)는 van den Broek·Levina의 2026년 『Administrative Science Quarterly』 논문을 소개했다. 스톡홀름경제대·뉴욕대 연구진은 직원 약 20만 명의 글로벌 소비재 기업이 경영관리직 연수생 채용(매년 약 1만 명 지원, 100명 선발)에 게임 기반 AI 평가를 도입한 과정을 2018~2021년 현장 관찰 1,277시간·인터뷰 83건·문서 359건으로 추적했다. AI 학습용 데이터를 얻으려면 면접관이 서로 영향을 받지 않고 점수를 기록해야 한다는 이유로 면접 뒤 면접관들이 모여 의견을 나누던 회의가 사라졌고, 그 결과 서로 다른 관점을 비교하고 자기 판단을 되짚을 기회가 없어졌다(구독 기사, 공개된 앞부분 기준).","eSum":"DBR's 1st November issue (published 27 October) reviews a 2026 Administrative Science Quarterly paper by Elmira van den Broek and Natalia Levina. Researchers from the Stockholm School of Economics and NYU Stern followed how a global consumer-goods company with about 200,000 employees introduced game-based AI assessment for its management trainee programme (about 10,000 applicants a year for 100 places), using 1,277 hours of field observation, 83 interviews and 359 documents from 2018 to 2021. Because AI training data required interviewers to record scores without influencing one another, the post-interview meetings where interviewers compared views disappeared, removing the chance to weigh different perspectives and revisit their own judgements (subscriber article; summary based on the free opening section).","kImp":"AI나 새 시스템을 들이면서 데이터 입력 방식을 바꿀 때 그 과정에서 사라지는 회의·검토 자리(평가 조정 회의, 보고서 공동 검토 등)가 없는지 먼저 짚어 보고, 꼭 필요한 토론은 별도 단계로 남겨 둘 만하다.","eImp":"When AI or a new system changes how data is entered, check first which meetings or reviews quietly disappear in the process, such as calibration meetings or joint reviews of reports, and keep the discussions that matter as a separate step.","url":"https://dbr.donga.com/article/view/1904/article_no/12310","prio":2,"kor":true,"tags":["COLLAB","AI","MTG"],"tool":""},{"code":"COLLAB","date":"2026-10-23","src":"HR Insight","title":"롯데홈쇼핑 HR부문장 \"일 잘하는 것은 맞는 사람과 지식을 제때 잇는 것\"…강한 유대로 신뢰, 약한 유대로 정보를 넓히라","eTitle":"Lotte Home Shopping's HR Head Argues Good Work Means Connecting the Right People and Knowledge at the Right Time, Using Strong Ties for Trust and Weak Ties for Wider Information","kSum":"조윤주 롯데홈쇼핑 HR부문장(상무)은 HR Insight 11월호 칼럼에서 부서·업종을 넘는 협업이 늘면서 개인 지식만으로는 일이 풀리지 않는다며, 네트워킹은 인맥의 수가 아니라 정보와 기회의 흐름이라고 정의했다. 그는 마크 그라노베터(1973)의 '약한 유대의 힘'을 들어 깊은 신뢰를 주는 강한 유대는 비슷한 정보를 공유하기 쉽고, 가끔 연락하는 약한 유대가 집단 밖의 정보와 기회를 가져온다고 설명했다. 세미나에서 잠깐 만난 인연이 사내 재배치 문제를 푼 경험 등을 소개하며, 가벼운 안부·감사 인사 유지, 작은 도움 주고받기, 부서 이동 뒤에도 관계 유지, 그리고 HR이 부서 간 교류·멘토링·사내 커뮤니티로 약한 유대를 만들어 줄 것을 제안했다.","eSum":"In an HR Insight column, Lotte Home Shopping HR head Cho Yoon-joo says that as collaboration across departments and industries grows, individual knowledge is often not enough, and defines networking as the flow of information and opportunity rather than the number of contacts. Citing Mark Granovetter's 1973 'strength of weak ties', she explains that strong ties build trust but tend to share similar information, while occasional contacts bring in information and opportunities from outside one's group. Drawing on her own experience, including a brief seminar contact who helped solve an internal redeployment problem, she recommends light regular contact, small reciprocal favours, keeping relationships after job moves, and HR programmes such as cross-department exchanges, mentoring and internal communities that create new weak ties.","kImp":"부서 간 업무가 얽힌 육상 조직이라면 분기마다 다른 팀과 짧은 업무 공유 시간을 잡거나 신입·전입자에게 타 부서 멘토를 붙여, 급할 때 바로 물어볼 수 있는 '약한 연결'을 미리 만들어 두는 것이 협업 속도를 높인다.","eImp":"In shore organisations where departments' work is intertwined, a short quarterly work-sharing session with another team or a mentor from a different department for new joiners builds the weak ties that speed up collaboration when something urgent comes up.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=112&bi_pidx=39671","prio":1,"kor":true,"tags":["COLLAB","WR"],"tool":""},{"code":"COLLAB","date":"2026-10-21","src":"HRZone","title":"협업을 무너뜨리는 5가지 숨은 방해 요인: 사일로·우선순위 밀림·공로 독식·개인 보상·목적 부재… 리더 1,000여 명 조사서 '사일로가 일상' 응답 절반 넘어","eTitle":"Five Hidden Collaboration Saboteurs, From Silos and Credit-Taking to Individual Rewards and Missing Purpose, as Over Half of 1,000-Plus Leaders Say Silo Working Dominates","kSum":"헐트 국제경영대학원의 가이 루비시 교수는 2026년 10월 21일 HRZone 기고에서 전 세계 리더 1,000명 이상 조사 결과 90%가 협업이 성과·혁신에 필수라고 답했지만, 절반 이상은 사일로 방식이 일상을 지배한다고, 40%는 협업할 시간이 부족하다고 답했다고 소개했다. 그는 압박 속에 자기 영역으로 숨는 사일로, 일정에서 밀려나는 협업, 기여와 무관하게 윗사람에게 가는 공로, 개인 성과에만 걸린 보상, 공유된 목적의 부재를 5대 방해 요인으로 꼽고, 일정 점검·영역 다툼 말투 듣기·보상 구조 그려 보기·팀원에게 목적을 자기 말로 설명하게 하기 같은 진단법을 제시했다. 처방으로는 함께 만든 목적, 경청·공로 공유 같은 관계 기술, 공동 목표와 팀 성과 인정, 협업 시간 보호를 들었다.","eSum":"In an HRZone article on 21 October 2026, Hult International Business School professor Guy Lubitsh cites a study of more than 1,000 global leaders in which 90% called collaboration essential to performance and innovation, yet more than half said silo working dominates daily practice and 40% said they lack time to collaborate. He identifies five saboteurs: retreating into silos under pressure, deprioritising collaboration in calendars, credit flowing to senior people regardless of contribution, individual incentives, and the absence of a shared purpose, each with diagnostics such as auditing calendars, listening for territorial language, mapping incentives and asking people to state the purpose in their own words. His remedies include a co-created purpose, relational skills such as listening and sharing credit, shared objectives and team recognition, and protected time for collaboration.","kImp":"부서 간 프로젝트에는 개인 KPI만 두지 말고 공동 목표를 하나 이상 넣고, 성과를 보고할 때 실제로 기여한 다른 부서 담당자의 이름을 밝히는 습관부터 들이면 사일로를 줄이는 데 도움이 된다.","eImp":"Cross-departmental projects should carry at least one shared objective alongside individual KPIs, and simply naming the people from other departments who contributed when reporting results is a good first habit for reducing silos.","url":"https://hrzone.com/the-five-hidden-saboteurs-of-collaboration-how-to-spot-and-stop-them/","prio":1,"kor":false,"tags":["COLLAB","PERF","LDR"],"tool":""},{"code":"COLLAB","date":"2026-10-20","src":"요즘IT","title":"\"AI로 기획서만 빨리 쓰면 달라지는 게 없다\"…기획·개발·아트가 순서대로 넘기던 일을 병렬로 바꾸자 5일 작업이 3일로","eTitle":"Writing Specs Faster With AI Changed Nothing Until a Team Replaced Sequential Hand-Offs Between Planning, Development and Art With Parallel Work, Cutting a Five-Day Job to Three","kSum":"게임 개발팀에서 일하는 필자는 요즘IT 기고에서 경영진 지시로 기획서를 AI로 쓰게 했더니 문서가 장황해지고 동료 검토 단계가 사라졌으며, 바이브 코딩 목업으로 바꾸자 개발자는 AI 코드 정리에, 아티스트는 목업 재해석에 시간을 썼다며 '단계별 속도만 높여서는 일하는 방식이 바뀌지 않았다'고 했다. 10명 미만 새 프로젝트에서는 순차적 넘기기를 없애고 기획자가 직접 동작하는 기능을 만들며 기획·프로그래밍·아트가 병렬로 일하고 충돌은 의도를 공유해 합의하는 방식으로 바꿨고, 피드백은 '어떻게 하라'가 아니라 '무엇이 더 나은가'로 하자는 원칙을 세웠다. 그 결과 약 5일로 잡던 마일리지·멤버십 기능 작업을 약 3일로 줄였지만, 토큰 비용·유지 부담·병합 충돌이 늘었고 단일 사례라고 덧붙였다.","eSum":"In a Yozm IT essay, a game-development team member writes that when management had the team write specs with AI, documents became bloated and peer review disappeared, and when they switched to vibe-coded mock-ups developers spent time cleaning AI code while artists reinterpreted the mock-ups, so speeding up individual steps did not change how work flowed. On a new project of under ten people they dropped sequential hand-offs: planners built working features directly, planning, programming and art ran in parallel, conflicts were settled by sharing intent, and feedback focused on what would be better rather than how to do it. A mileage and membership feature estimated at about five days took about three, though token costs, maintenance and merge conflicts rose and the author stresses it is a single case.","kImp":"부서 간 '문서 넘기기'가 많은 업무(예: 기술·구매·운항 간 요청)라면 AI로 문서를 빨리 쓰는 데서 멈추지 말고, 관련 담당자가 처음부터 같은 화면에서 목적을 공유하고 동시에 검토하는 방식으로 한 건만 시험해 보며 소요 시간을 비교해 볼 만하다.","eImp":"Where cross-department work runs on passing documents along, for example requests between technical, purchasing and operations teams, teams can go beyond drafting faster with AI and trial one case in which everyone involved shares the purpose from the start and reviews in parallel, comparing the time taken.","url":"https://yozm.wishket.com/magazine/detail/3997/","prio":1,"kor":true,"tags":["COLLAB","AI","WR"],"tool":""},{"code":"COLLAB","date":"2026-10-19","src":"Becker's Hospital Review","title":"출근해도 '함께' 일하지 못한다: 미국 대졸 직장인 1,835명 조사서 70% 이상 '최근 출근일에 팀원 누군가는 다른 곳에'… 약 절반은 대면 회의가 한 번도 없어","eTitle":"Study: Return-to-Office Days Rarely Reunite Teams, as Over 70% of 1,835 US Workers Had a Teammate Elsewhere on Their Last Office Day and About Half Had No Fully In-Person Meetings","kSum":"경제학자 나탈리아 이매뉴얼과 에마 해링턴이 9월 미국 대졸 직장인 1,835명을 조사해 The Atlantic(10월 14일)에 쓴 연구를 Becker's Hospital Review가 10월 19일 정리했다. 응답자 70% 이상은 가장 최근 출근일에 팀원 중 최소 1명이 다른 곳에서 일했고, 약 절반은 완전 대면 회의가 하나도 없었으며, 3명 중 1명 이상은 누군가 사무실 밖에 있으면 팀 회의가 통째로 온라인으로 바뀌어 온라인 회의만 했다. 전원이 출근한 날에도 회의가 있던 직장인의 52%는 최소 1건을 온라인으로 했고, 관리자가 재택하면 팀도 따라 하는 경향이 원인으로 꼽혔다. 연구진은 팀 거점 중심 채용, 정기 오프사이트, 멘토링 같은 대면 기여를 성과 평가에 반영하는 방안 등을 제안했다.","eSum":"Becker's Hospital Review on 19 October 2026 summarised research by economists Natalia Emanuel and Emma Harrington, published in The Atlantic on 14 October, based on a September survey of 1,835 college-educated US workers. More than 70% said at least one teammate was working elsewhere on their most recent office day, about half had no fully in-person meetings, and more than one in three had only online meetings because their team went fully virtual whenever anyone was off-site. Even when everyone was on-site, 52% of those with meetings had at least one held online, and managers who stay home were cited as a reason teams follow suit. The authors suggest hiring around each team's hub, regular off-sites and rewarding in-person contributions such as mentoring in performance reviews.","kImp":"출근일을 정해 두는 것만으로는 협업이 늘지 않으므로 팀장은 팀원이 같은 요일에 모이도록 맞추고 본인부터 그날 출근하며, 모이는 날에는 신입 지도·브레인스토밍·어려운 논의처럼 대면 효과가 큰 일을 몰아 배치해 볼 만하다.","eImp":"Fixed office days alone do not create collaboration, so team leaders should align the days their team comes in, show up themselves on those days, and schedule work that benefits most from being together, such as coaching new staff, brainstorming and difficult discussions, for those days.","url":"https://www.beckershospitalreview.com/workforce/study-why-rto-mandates-arent-bringing-teams-back-together/","prio":2,"kor":false,"tags":["REMOTE","COLLAB","MTG"],"tool":""},{"code":"COLLAB","date":"2026-10-15","src":"Harvard Business Review","title":"HBR \"동료 대신 AI에 물으면 팀 신뢰·조정력 약해진다\" — 'relationslipping' 연구","eTitle":"Team Dynamics Weaken When Employees Turn to AI Instead of Colleagues","kSum":"코칭 플랫폼 BetterUp 연구진과 제프리 핸콕 스탠퍼드대 교수는 AI 사용이 동료가 고유한 전문지식을 가졌다는 인식은 높였지만, AI를 '팀원'처럼 대하면 팀원 사이의 신뢰와 조정 능력이 떨어졌다고 보고했다. 연구진은 구성원이 서로 대신 AI를 쓰면서 업무 관계가 서서히 약해지는 현상을 'relationslipping'이라 불렀다. 원인은 두 가지로, 빠른 AI 답을 얻느라 대화를 건너뛰면 '누가 무엇을 아는지'에 대한 팀의 지도가 갱신되지 않고, 동료가 일을 AI에 넘기면 그 사람의 판단 과정이 보이지 않게 된다. HBR 편집자 뉴스레터(10월 20일)는 이 연구가 미국 근로자 1,000명 이상 설문에 기반한다고 소개했다.","eSum":"Researchers from coaching platform BetterUp and Stanford professor Jeffrey Hancock report that AI use raised teammates' sense that colleagues hold unique expertise, but treating AI as a teammate eroded trust and coordination among team members. They call this 'relationslipping', the gradual weakening of a team's working relationships as members substitute AI for each other. Two mechanisms drive it: skipping conversations for quick AI answers stops people updating their map of who knows what, and offloading work to AI makes colleagues' reasoning harder to see. An HBR editor's newsletter on October 20 said the work draws on a survey of more than 1,000 U.S. workers.","kImp":"모르는 것을 동료 대신 AI에 먼저 묻는 습관이 늘수록 '이 일은 누가 잘 아는지'에 대한 팀의 지도가 낡고 서로의 판단 과정도 보이지 않게 된다. 주간 회의에 AI로 낸 결론의 근거를 담당자가 직접 설명하는 짧은 순서를 넣고, 팀 메신저에 업무별 담당자·전문가 목록을 고정해 두어 사람에게 묻는 길을 열어 둘 만하다.","eImp":"The more people ask AI before colleagues, the faster a team's map of who knows what goes stale and the less visible each other's reasoning becomes. Add a short slot to weekly meetings where owners explain the reasoning behind AI-assisted conclusions, and pin a list of go-to experts by topic in the team chat so asking a colleague stays easy.","url":"https://hbr.org/2026/10/team-dynamics-weaken-when-employees-turn-to-ai-instead-of-colleagues","prio":2,"kor":false,"tags":["AI","COLLAB"],"tool":""},{"code":"COLLAB","date":"2026-10-13","src":"Harvard Business Review","title":"애덤 그랜트 'HBR IdeaCast': 강한 팀은 서로 좋아하는 팀이 아니라 목표를 공유하는 팀… 무작위 짝 점심 30분으로 영업 매출 24%↑, 핵심 가치는 4개 이내로","eTitle":"Adam Grant on HBR IdeaCast: Great Teams Need Shared Goals More Than Friendship, and Weekly Random Lunch Pairings Lifted Salespeople's Revenue by 24%","kSum":"HBR IdeaCast가 2026년 10월 13일 방송한 애덤 그랜트 와튼스쿨 교수(신간 'Vibe') 인터뷰에서 그는 업무·스포츠 팀 연구를 근거로 서로 좋아하는 '사회적 응집'보다 목표를 공유하는 '과업 응집'이 성과를 더 잘 예측한다고 말했다. 무작위로 짝지은 영업사원이 매주 30분 점심을 함께하자 4개월 뒤 개인 매출이 24% 늘었다는 연구와, 문화 적합성으로 사람을 뽑은 바이오 스타트업이 실패율은 낮았지만 상장 뒤 동질화로 성장이 느려졌다는 15년 연구도 소개했다. 그는 과업·절차 갈등은 팀에 도움이 되고 관계 갈등은 해롭다며 '이걸 토론해 볼까요?'처럼 이견을 예정된 절차로 만들고, 핵심 가치는 4개 이내로 두며, 입사 전 '프리보딩'과 신입이 자기 강점을 드러내게 하는 온보딩을 권했다.","eSum":"On an HBR IdeaCast episode released on 13 October 2026, Wharton organisational psychologist Adam Grant, discussing his book Vibe, said research on work and sports teams shows task cohesion around shared goals predicts performance better than social cohesion. He cited a study in which randomly paired salespeople who lunched together for 30 minutes each week raised their individual revenue by 24% after four months, and a 15-year study of biotech start-ups in which hiring for culture fit cut failure rates but slowed growth after going public as firms grew homogeneous. He argued task and process conflict help teams while relationship conflict hurts, recommended framing disagreement as debate, keeping core values to a maximum of four, and starting pre-boarding before day one while letting new hires showcase their strengths.","kImp":"팀 분위기를 위한 회식보다 공동 목표를 분명히 하는 데 먼저 투자하고, 회의에서 '반대 의견을 들어 보는 순서'를 정례화하며, 다른 팀과의 무작위 점심 짝을 정해 부서 간 관계를 넓혀 볼 만하다.","eImp":"Teams should invest first in clarifying shared goals rather than social events, build a regular slot for hearing dissenting views into meetings, and try random lunch pairings with other teams to widen cross-departmental relationships.","url":"https://hbr.org/podcast/2026/10/why-great-teams-dont-need-to-like-each-other","prio":2,"kor":false,"tags":["COLLAB","LDR"],"tool":""},{"code":"COLLAB","date":"2026-10-13","src":"전자신문","title":"시스코 보고서 \"한국 보안·네트워크·IT 부서가 정보 공유하고 함께 대응하는 곳 24%, 세계 평균 41%\"…최상위 대비 수준 기업은 1%(세계 8%)","eTitle":"Cisco Report Finds Only 24% of Korean Organisations Have Security, Network and IT Teams Sharing Information and Responding Together, Against 41% Globally, and Just 1% Reach Its Top Readiness Tier Against 8%","kSum":"시스코코리아가 13일 공개한 '릴렌트리스 디펜스 보고서'(4~5월 30개국 보안 실무자 8,000명 조사)에 따르면 한국의 사이버 방어 점수는 100점 만점에 58점으로 세계 평균(64점)보다 6점 낮았고, 최상위 대비 수준 조직은 1%로 세계(8%)에 크게 못 미쳤다. 보안·네트워크·IT 부서가 정보를 공유하고 공동 대응하는 조직은 한국 24%로 세계 평균(41%)에 크게 못 미쳤으며, 보고서는 보안 조직 간 협업 부족과 여러 시스템에 흩어진 데이터를 가장 큰 걸림돌로 꼽았다. 시스코는 사고 전에 부서별 의사결정 권한과 책임을 정하고, 흩어진 보안 정보를 통합하며, 실제 공격 시나리오로 대응 훈련을 하라고 권했다. 한국 응답자 수는 기사에 나오지 않는다.","eSum":"Cisco Korea's Relentless Defense report, released on 13 October and based on an April-May survey of 8,000 security professionals in 30 countries, gave Korea a cyber-defence score of 58 out of 100, six points below the global average of 64, with only 1% of organisations in its top readiness tier against 8% globally. Just 24% of Korean organisations have security, network and IT teams that share information and respond jointly, against a 41% global average, and the report names weak collaboration between security functions and data scattered across systems as the biggest obstacles. Cisco recommends defining each department's decision rights and responsibilities before an incident, integrating scattered security information and running drills based on realistic attack scenarios. The article does not give the number of Korean respondents.","kImp":"사이버 사고는 IT 담당만의 일이 아니므로, 육상 조직에서도 IT·운항·안전 등 관련 부서가 사고 시 누가 무엇을 결정하고 누구에게 알리는지 연락 체계를 미리 한 장으로 정리하고, 연 1회 이상 함께 모의 훈련을 해 보는 것이 좋다.","eImp":"Cyber incidents are not just an IT matter, so shore organisations can set out on one page who decides what and who notifies whom across IT, operations and safety teams during an incident, and run a joint drill at least once a year.","url":"https://www.etnews.com/20261013000283","prio":1,"kor":true,"tags":["COLLAB","SEC"],"tool":""},{"code":"COLLAB","date":"2026-10-06","src":"Edelman","title":"에델만 'Trust at Work 2026': 10개 시장 직원 1만여 명 조사서 동료 신뢰 82%→73%로 가장 크게 하락… 조직 변화 경험이 부정적이면 '가치관 다른 동료' 신뢰 77%→50%","eTitle":"Edelman's Trust at Work 2026: Trust in Co-Workers Falls Furthest, From 82% to 73%, and a Bad Experience of Organisational Change Cuts Trust in Colleagues With Different Values to 50%","kSum":"에델만이 2026년 10월 6일 공개한 Trust at Work 조사(10개 시장 직원 1만여 명)에서 동료에 대한 신뢰는 82%에서 73%로 떨어져 직속 상사(79%→72%)·CEO(70%→66%)보다 하락 폭이 컸고, 세 지표 모두 조사 이래 최저였다. 응답자 76%가 지난 1년간 AI 도입(53%)·전략 변경(47%) 같은 조직 변화를 겪었는데, 그 경험이 부정적이었던 직원은 가치관이 다른 동료를 신뢰하는 비율이 50%로 긍정적 경험자(77%)보다 27%p 낮았고, 기대 이상으로 노력하겠다는 응답도 57% 대 83%였다. 변화 경험이 좋지 않았다는 응답은 일반 직원(49%)이 임원(17%)의 약 3배였다.","eSum":"Edelman's Trust at Work study, published on 6 October 2026 and covering more than 10,000 employees in ten markets, found trust in co-workers fell from 82% to 73%, a steeper drop than for direct managers (79% to 72%) or CEOs (70% to 66%), with all three at record lows. Some 76% had been through at least one transformation in the past year, most often AI implementation (53%) or a strategy shift (47%); those with a negative experience were far less likely to trust co-workers with different values (50% vs 77%) or to go above what is expected (57% vs 83%). Associates were about three times as likely as executives to report a less than positive experience (49% vs 17%).","kImp":"새 시스템이나 조직 개편을 추진할 때 팀장은 결정 사항만 공지하지 말고 영향을 받는 부서 담당자를 한자리에 모아 역할과 인수인계 지점을 함께 정하고, 도입 뒤 몇 주간 짧은 점검 회의로 막힌 곳을 비난 없이 드러내게 하는 것이 동료 간 신뢰를 지키는 방법이다.","eImp":"When rolling out a new system or reorganisation, team leaders should not just announce decisions but bring the affected staff from each department together to agree roles and handover points, then hold short check-ins for a few weeks afterwards so problems can surface without blame.","url":"https://www.edelman.com/newsroom/richard-edelmans-6am-blog/trust-at-work-2026","prio":3,"kor":false,"tags":["COLLAB","CHG","ENG"],"tool":""},{"code":"COLLAB","date":"2026-09-22","src":"Owl Labs","title":"아울랩스 '2026 하이브리드 근무 현황': 미국 지식노동자 2,000명 중 76% '출근 의무화는 리더의 가시성 때문'… 하이브리드 회의는 시작에만 평균 6분, 74%는 일요일에도 일해","eTitle":"Owl Labs' State of Hybrid Work 2026: 76% of 2,000 US Knowledge Workers See Office Mandates as About Leadership Visibility, Hybrid Meetings Lose Six Minutes to Start, and 74% Work on Sundays","kSum":"회의 장비 기업 아울랩스가 2026년 9월 22일 발표한 10번째 State of Hybrid Work 보고서(미국 풀타임 지식노동자 2,000명)에서 사무실 출근 비율은 65%(전년 63%)로 늘었지만, 76%는 출근 의무화가 주로 리더의 감독·가시성 때문이라고 봤고 하이브리드 근무자의 40%는 눈도장만 찍고 몇 시간 만에 나가는 '커피 배지'를 한다고 답했다. 회의 피로를 느낀다는 응답은 38%였고, 하이브리드 회의는 시작하는 데 평균 6분이 걸리며(18%는 10분 이상) 66%가 기술 문제로 시간을 잃는다고 했다. 74%는 일요일에도 어느 정도 일하고 21%는 거의 하루를 일했으며, 62%는 AI 때문에 하루 처리 기대량이 늘었다고, 33%는 회사가 승인하지 않은 AI 도구를 쓴다고 답했다.","eSum":"Owl Labs' tenth State of Hybrid Work report, released on 22 September 2026 and based on 2,000 full-time US knowledge workers, found in-office attendance rose to 65% from 63%, yet 76% believe return-to-office mandates are mainly about leadership oversight and visibility, and 40% of hybrid workers 'coffee badge', coming in for a few hours to be seen. Some 38% report meeting fatigue, hybrid meetings take an average of six minutes to start (18% lose 10 minutes or more) and 66% lose time to technical difficulties. Nearly three-quarters (74%) do some work on Sundays, 21% a full or near-full day, while 62% say AI has raised expectations of how much they should get done and 33% use AI tools their employer has not approved.","kImp":"출근일에 화상 회의만 하다 돌아가는 일이 없도록 하이브리드 회의는 회의실 장비를 미리 점검해 정시에 시작하고, 주말 메시지는 긴급 건만 보내는 팀 규칙을 정하며, 쓰고 싶은 AI 도구가 있으면 먼저 승인 절차를 밟도록 안내하는 것이 좋다.","eImp":"Teams should check meeting-room equipment in advance so hybrid meetings start on time, agree that weekend messages are for urgent matters only, and steer staff who want to use a new AI tool through the approval process first.","url":"https://owllabs.com/state-of-hybrid-work/2026","prio":2,"kor":false,"tags":["REMOTE","MTG","WELL"],"tool":""},{"code":"COLLAB","date":"2026-09-22","src":"DBR","title":"DBR 스페셜 리포트 '개인의 AI 생산성, 집단지성으로 바꾸려면' — 부서마다 AI로 최적화하면 '지능의 파편화', 답만이 아니라 판단의 흔적을 쌓아야","eTitle":"DBR Special Report: Turning Individual AI Productivity Into Collective Intelligence - Department-Level AI Optimisation Fragments Judgement, So Firms Should Keep a Trail of How Decisions Were Made","kSum":"성균관대 서아영 교수는 DBR 10월 1호(9월 22일 발행)에서 AI가 개인 생산성을 높여도 각 개인·부서가 자기 목표를 AI로 최적화할수록 판단이 서로 충돌하는 '지능의 파편화'가 심해질 수 있다고 짚었다. PwC 2025년 조사에서 직원 54%가 최근 1년간 AI를 썼지만 2026년 조사에서 CEO 56%는 AI 도입 뒤에도 매출 증가나 비용 절감 효과를 못 봤다고 답했고, HBR이 소개한 한 유통기업은 재고 부족 15% 감소·고객 응대 시간 40% 단축·메일 오픈율 25% 상승에도 전체 고객만족도는 그대로이고 시장점유율은 떨어졌다. 그는 흩어진 지식을 팀의 집단지성으로 연결하고, 최종 답뿐 아니라 어떤 근거와 가정으로 판단했고 사람이 AI 제안을 왜 고쳤는지 '판단의 흔적'을 축적하며, 개인 산출량보다 사람과 AI의 공동 성과를 재라고 제안했다(구독 기사, 공개된 앞부분 기준).","eSum":"In DBR's 1st October issue (published 22 September), Sungkyunkwan University professor Seo A-young argues that while AI raises individual productivity, the more each person and department optimises its own goals with AI, the more their judgements can clash, a 'fragmentation of intelligence'. PwC's 2025 survey found 54% of employees had used AI in the past year, yet in its 2026 survey 56% of CEOs said AI had brought neither revenue growth nor cost savings; a retailer cited by HBR cut stockouts by 15%, customer-service response times by 40% and lifted email open rates by 25%, but overall customer satisfaction did not improve and market share fell. She proposes linking scattered knowledge into team collective intelligence, recording not just final answers but the evidence, assumptions and reasons people changed AI suggestions, and measuring joint human-AI results rather than individual output (subscriber article; summary based on the free opening section).","kImp":"부서마다 AI로 각자 효율을 올리는 데서 그치지 말고, 부서 사이로 넘어가는 업무(보고서 → 검토 → 고객 대응 등)의 최종 결과를 함께 보는 지표를 정하고, 중요한 판단의 근거와 수정 이유를 공유 문서에 남겨 다른 팀이 다시 쓰게 할 만하다.","eImp":"Rather than letting each department use AI to raise its own efficiency, agree shared measures for work that passes between teams, such as report, review and customer response, and record the reasoning behind key decisions in shared documents so other teams can reuse it.","url":"https://dbr.donga.com/article/view/1101/article_no/12282","prio":2,"kor":true,"tags":["COLLAB","AI","DATA"],"tool":""},{"code":"COLLAB","date":"2026-04-27","src":"Atlassian","title":"아틀라시안 'State of Teams 2026': 지식노동자 1만2,035명 중 87% '모두 실행에만 몰두해 조율할 시간·여력이 없다'… 업무의 80%는 팀 단위에서 일어나","eTitle":"Atlassian's State of Teams 2026: 87% of 12,035 Knowledge Workers Say Everyone Is in Execution Mode With No Time or Capacity to Coordinate, Though 80% of Work Happens at Team Level","kSum":"아틀라시안 팀워크랩이 2026년 4월 27일 공개한 State of Teams 2026(1~2월 지식노동자 1만2,035명·포춘 1000 임원 173명 설문, 포춘 500 임원 25명 인터뷰)은 업무의 80%가 팀 단위에서 일어나지만 지식노동자의 87%가 모두 실행 모드에 있어 조율할 시간이나 여력이 없다고 답했다고 밝혔다. AI를 쓰는 직원은 85%였지만 업무 흐름에 녹여 낸 경우는 29%였고, AI로 팀워크를 개선하는 데 집중하는 리더는 24%였다. 아틀라시안은 이런 '분절 비용'이 포춘 500 기업에 연 1,610억 달러에 이른다고 추산했고, AI 성과를 낸 상위 14% 팀은 AI가 협업을 늘린다고 답할 가능성이 최대 9.4배 높았다.","eSum":"Atlassian's Teamwork Lab published State of Teams 2026 on 27 April 2026, based on a January-February survey of 12,035 knowledge workers and 173 Fortune 1000 executives plus interviews with 25 Fortune 500 executives. It finds that 80% of work happens at team level, yet 87% of knowledge workers say that with everyone in execution mode they lack the time or capacity to coordinate. While 85% use AI at work, only 29% have embedded it in their workflows, and only 24% of leaders focus on using AI to improve teamwork; Atlassian puts the resulting fragmentation cost at $161 billion a year for the Fortune 500. The top 14% of teams that have achieved AI returns were up to 9.4 times more likely to say AI increases collaboration.","kImp":"팀장은 각자 실행에 바빠 조율이 빠지지 않도록 주 1회 15분 '의존 관계 점검'(누가 누구의 산출물을 기다리는지)을 두고, AI 도구를 들일 때도 개인 생산성보다 팀 간 정보 공유·인수인계에 먼저 써 보는 것이 좋다.","eImp":"To stop coordination falling away while everyone is busy executing, team leaders can hold a weekly 15-minute dependency check on who is waiting for whose output, and when introducing AI tools try them first on information sharing and handovers between teams rather than individual productivity.","url":"https://www.atlassian.com/blog/state-of-teams-2026","prio":2,"kor":false,"tags":["COLLAB","AI","WR"],"tool":""}]},{"code":"CULT","kTitle":"조직문화·몰입·웰빙","eTitle":"Culture, engagement and wellbeing","items":[{"code":"CULT","date":"2026-10-27","src":"DBR","title":"DBR '데이터로 팀을 읽는 리더의 기술' — 소진은 협업망을 타고 번진다(직원 1,541명 연구), 리더는 업무가 누구에게 몰리고 어디서 병목이 생기는지 봐야","eTitle":"DBR: Reading Teams Through Data - Burnout Spreads Through Collaboration Networks (a 1,541-Employee Study), So Leaders Should Track Where Work Concentrates and Where Bottlenecks Form","kSum":"피플즈 대표 김문경은 DBR 칼럼에서 목표를 초과 달성한 팀이라도 일부 구성원에게 업무가 몰리거나 과부하로 소진되고 있을 수 있다며, 성과를 받치는 여건이 어디서 흔들리는지 감이 아니라 체계적 진단으로 파악하라고 했다. 근거로 든 네덜란드 흐로닝언대 연구(『Work & Stress』 2026)는 한 조직 직원 1,541명을 두 차례 조사해, 소진된 동료와 함께 일하는 직원일수록 역할이 불분명해지고 업무 갈등이 늘었다고 인식했고 이것이 본인의 소진으로 이어졌으며, 이런 관계는 개별 팀보다 여러 팀이 프로젝트로 연결된 협업망 전체에서 더 뚜렷했다고 밝혔다. 그는 평균 업무시간이 줄어도 여러 부서의 문의를 혼자 처리하는 직원의 부담은 커질 수 있다며, 누가 바쁜지가 아니라 업무가 누구에게 집중되고 어느 단계에서 병목이 생기는지를 데이터로 봐야 한다고 강조했다(구독 기사, 공개된 앞부분 기준).","eSum":"In a DBR column, Peoplez CEO Kim Moon-kyung warns that even a team that beats its targets may have work piled on a few people who are burning out, and urges leaders to find where the conditions behind performance are weakening through systematic diagnosis rather than instinct. He cites a University of Groningen study in Work & Stress (2026) that surveyed 1,541 employees in one organisation twice: staff who worked with burnt-out colleagues reported more role ambiguity and work conflict, which was linked to their own burnout, and the effect was clearer across the whole network of teams linked by projects than within single teams. Average working hours can fall while one person fielding queries from several departments carries more load, he notes, so leaders should look at where work concentrates and where bottlenecks form, not just at who is busy (subscriber article; summary based on the free opening section).","kImp":"팀 평균 근무시간만 보지 말고 여러 부서의 문의·결재·자료 요청이 한 사람에게 몰리는지, 어느 단계에서 일이 멈추는지를 업무 요청 기록이나 메일·메신저 문의량으로 살펴, 한 사람의 과부하가 함께 일하는 동료의 지연과 소진으로 번지기 전에 일을 나눌 만하다.","eImp":"Rather than relying on average hours, check whether queries, approvals and data requests from several departments are piling up on one person and where work stalls, using request logs or email and chat volumes, and rebalance tasks before one person's overload spreads into delays and burnout for colleagues.","url":"https://dbr.donga.com/article/view/1801/article_no/12307","prio":2,"kor":true,"tags":["WELL","DATA","COLLAB"],"tool":""},{"code":"CULT","date":"2026-10-27","src":"이코노미스트","title":"서울대병원 \"우울 증상 직장인, 35세 미만은 결근 5.42배·35세 이상은 '출근 후 멍하니' 4.78배\"…연령별 맞춤 지원 필요","eTitle":"Seoul National University Hospital Study Finds Depressed Workers Under 35 Are 5.42 Times More Likely to Be Absent, While Those 35 and Over Are 4.78 Times More Likely to Show Up but Underperform","kSum":"서울대병원 가정의학과 윤영호 교수와 한국외대 정주연 교수 연구팀이 2024년 1월 20~49세 직장인 1,000명(35세 미만 489명, 35세 이상 511명)을 조사해 국제학술지 JOEM에 실은 연구에 따르면, 우울 증상(PHQ-9 10점 이상)이 있는 35세 미만은 결근 위험이 5.42배, 35세 이상은 출근은 하되 업무 효율이 떨어지는 '프리젠티즘' 위험이 4.78배 높았다. 우울 증상 비율은 35세 미만 33.1%, 35세 이상 27.0%였고 건강 때문에 잃은 업무시간 비율도 6.8%와 3.3%로 두 배 차이가 났다. 연구팀은 직장 내 우울 선별검사·조기 개입·낙인 해소와 함께 연령별 맞춤 프로그램이 필요하다고 제안했다.","eSum":"A study by Professor Yoon Young-ho of Seoul National University Hospital and Professor Jung Ju-yeon of Hankuk University of Foreign Studies, published in the Journal of Occupational and Environmental Medicine, surveyed 1,000 Korean workers aged 20-49 in January 2024. Among those with depressive symptoms, workers under 35 were 5.42 times more likely to be absent, while those 35 and over were 4.78 times more likely to attend but work below capacity. Depressive symptoms were reported by 33.1% of under-35s and 27.0% of older workers, and health-related lost work time was 6.8% against 3.3%. The authors call for workplace depression screening, early intervention, less stigma and age-specific programmes.","kImp":"팀장은 젊은 직원의 잦은 결근과 중견 직원의 '자리는 지키지만 일이 안 되는' 모습을 모두 정신건강 신호로 보고, 1:1 면담에서 업무 부하를 묻고 회사의 상담 프로그램(EAP 등)을 부담 없이 안내하는 습관을 들일 만하다.","eImp":"Team leaders can treat both frequent absence among younger staff and 'present but stuck' behaviour among mid-career staff as possible mental-health signals, asking about workload in one-to-ones and pointing people to counselling support without stigma.","url":"https://economist.co.kr/article/view/ecn202610270014","prio":2,"kor":true,"tags":["WELL","ENG"],"tool":""},{"code":"CULT","date":"2026-10-21","src":"HRreview","title":"영국 관리자 500명 조사: 85%는 관리 업무가 좋다지만 25%는 '사람 관리 스트레스로 늘 그만둘 생각'… 25~34세 관리자 74%가 지난 1년 번아웃","eTitle":"Ciphr Survey of 500 UK Managers: 85% Enjoy Managing People, Yet 25% Constantly Think About Quitting Over the Pressure and 74% of Those Aged 25-34 Felt Burnt Out","kSum":"HRreview가 2026년 10월 21일 보도한 HR 소프트웨어 기업 시퍼(Ciphr)의 영국 관리자 500명 조사에서 85%는 사람을 관리하는 일이 좋다고 했지만, 25%는 그 스트레스·압박 때문에 늘 또는 자주 퇴사를 생각하고 31%는 업무량이 감당할 수 없는 수준이라고 답했다. 지난 1년 번아웃을 겪었다는 응답은 25~34세 관리자가 74%로 55세 초과(45%)보다 훨씬 높았고, 60%는 최근 6개월간 저녁·주말에도 일했다. 가장 싫은 일로는 어려운 대화(32%), 고충·징계·감원(25%), 문제 행동 관리(24%)가 꼽혔고, 원하는 개선책은 관료주의 축소(24%), 급여 인상(22%), 관리 교육 확대와 상급 리더의 효과적 지원(각 20%), 회의 축소(19%) 순이었다.","eSum":"HRreview reported on 21 October 2026 that in a Ciphr survey of 500 UK people managers, 85% said they like managing people, yet 25% think about leaving all or most of the time because of the stress or pressure and 31% describe their workload as unmanageable that often. Some 74% of managers aged 25 to 34 felt burnt out in the past year, against 45% of those over 55, and 60% had worked evenings or weekends in the previous six months. The least liked tasks were difficult conversations (32%), grievances, disciplinaries and redundancies (25%) and managing problematic behaviour (24%), while the most wanted improvements were less bureaucracy (24%), higher pay (22%), more management training and better support from senior leaders (20% each) and fewer or shorter meetings (19%).","kImp":"신임·젊은 팀장일수록 번아웃 위험이 크므로 상위 관리자는 팀장의 실무 부담과 회의 수를 정기적으로 점검하고, 어려운 면담이나 징계 대응을 앞두고는 HR이 사전 코칭과 절차 안내를 해 주는 지원 체계를 마련하는 것이 좋다.","eImp":"Because newer and younger team leaders face the highest burnout risk, senior managers should regularly review their hands-on workload and meeting load, and HR should offer coaching and procedural guidance ahead of difficult conversations or disciplinary cases.","url":"https://hrreview.co.uk/hr-news/strategy-news/managers-face-pressure-to-quit-despite-enjoying-their-jobs/391856","prio":2,"kor":false,"tags":["WELL","LDR","RET"],"tool":""},{"code":"CULT","date":"2026-10-20","src":"HRD America","title":"직원 의견 수렴의 함정: 메신저·이메일 감성 분석은 '분위기 하락'은 잡아도 '이유'는 모른다… 피드백 뒤 변화를 본 실무자 48%뿐","eTitle":"Employee Listening: Sentiment Analysis of Slack and Email Can Spot a Mood Drop but Not Its Cause, and Only 48% of Individual Contributors See Change After Giving Feedback","kSum":"HRD America가 2026년 10월 20일 가트너·뉴욕대·콘퍼런스보드 전문가 인터뷰를 바탕으로 정리한 기사에 따르면, 슬랙·이메일 감성 분석은 팀 분위기 하락을 감지할 수 있지만 업무량·관리자·조직 개편 중 무엇이 원인인지는 알려 주지 못한다. 기사가 인용한 퀄트릭스 2026 조사에서 자신의 피드백 뒤 긍정적 변화를 봤다는 실무자는 48%로 전년보다 4%p 낮았고, 퍼셉틱스 2026 조사에서는 결과가 공유됐다 71%, 실행 계획이 만들어졌다 59%, 실제 개선됐다 51%로 단계마다 줄었다. 전문가들은 바꿀 의지가 없는 것은 묻지 말고, 결과와 후속 조치를 끝까지 알리며, 부서를 넘나드는 문제에는 책임 리더를 한 명 지정하고, 무엇을 수집하는지 투명하게 밝히라고 권했다.","eSum":"HRD America on 20 October 2026, drawing on interviews with experts from Gartner, NYU and The Conference Board, reported that sentiment analysis of Slack and email can detect a drop in team mood but not whether workload, a manager or a reorganisation is behind it. Citing Qualtrics' 2026 research, it notes only 48% of individual contributors have seen positive changes from their feedback, four points lower than in 2025, while Perceptyx's 2026 data show the share falling at each step from results shared (71%) to action plans created (59%) to improvements made (51%). The experts advise not asking about anything leaders are unwilling to change, closing the loop on results, naming one accountable leader for cross-functional issues and being transparent about what data is collected.","kImp":"팀 설문이나 면담 뒤 2~3주 안에 '들은 것·바꿀 것·바꾸지 못하는 것과 그 이유'를 팀에 다시 공유하는 것만으로도 신뢰가 쌓이므로, 의견 수렴은 실제로 실행할 수 있는 범위만큼만 하는 것이 낫다.","eImp":"Simply reporting back to the team within two to three weeks of a survey or listening session on what was heard, what will change and what cannot change and why builds trust, so teams should only ask about what they can actually act on.","url":"https://www.hcamag.com/us/specialization/transformation/employee-listening-ai-reads-your-slack-but-cant-say-why/594299","prio":1,"kor":false,"tags":["ENG","DATA","SPEAK"],"tool":""},{"code":"CULT","date":"2026-10-13","src":"오마이뉴스","title":"직원 상담 프로그램 들여놓고도 안 쓰이는 이유…\"알려지면 경력 불이익\" 우려 49%, 관리자에게 안내 못 받았다 45%","eTitle":"Why Employee Counselling Programmes Go Unused: 49% Fear Career Harm if Mental-Health Problems Become Known and 45% Say Their Manager Never Told Them Support Was Available","kSum":"오마이뉴스 '프리미엄 ESG 세상' 기획은 기업들이 근로자지원프로그램(EAP)을 도입해도 이용으로 이어지지 않는 원인으로 낙인과 경력 불이익 우려, 비밀보장에 대한 불신, 신청 절차·상담 시간 같은 접근성, 제도 안내와 관리자 교육 부족, 스트레스를 만드는 업무 구조를 꼽았다. 한국EAP협회가 2025년 HR 커뮤니티 가입 기업 144곳을 조사한 결과 EAP 도입 기업은 32.1%였고 도입 기업의 만족도는 92.4%였으며, 성평등가족부 2025년 가족친화수준 조사에서 건강·가족 상담을 운영하는 비율은 100인 미만 5.5%, 1,000인 이상 25.5%로 규모 격차가 컸다. TELUS Health 2025년 6월 지수에서는 49%가 정신건강 문제가 알려지면 경력상 불이익을 걱정했고 45%는 관리자에게 이용 가능 여부를 안내받은 적이 없었다. 필자들은 비밀보장 범위 명확화, 업무 여건에 맞춘 신청 절차, 관리자 교육, 업무량·역할·평가 공정성 점검을 함께 하라고 권했다.","eSum":"An OhmyNews ESG series feature argues that employee assistance programmes go unused because of stigma and fear of career harm, distrust about confidentiality, access barriers such as application steps and session times, poor communication and untrained managers, and work structures that create stress in the first place. In a 2025 Korea EAP Association survey of 144 companies in an HR community, 32.1% had an EAP and adopters reported 92.4% satisfaction, while the 2025 government family-friendliness survey found health or family counselling at 5.5% of firms under 100 staff against 25.5% at firms with 1,000 or more. In TELUS Health's June 2025 index, 49% feared career harm if a mental-health problem became known and 45% said their manager had never told them support was available. The authors recommend clarifying confidentiality, fitting procedures to work schedules, training managers and reviewing workload, roles and the fairness of appraisals.","kImp":"회사에 상담 지원 제도가 있다면 팀장이 면담 때 '이용 사실은 회사에 전달되지 않는다'는 비밀보장 범위와 신청 방법을 직접 안내하는 것만으로도 이용 문턱을 낮출 수 있고, 제도가 없는 중소 규모 조직은 근로복지넷의 무료 EAP를 알려 줄 수 있다.","eImp":"Where a counselling scheme exists, a team leader simply explaining in one-to-ones that use is not reported to the company and how to apply can lower the barrier, and smaller organisations without a scheme can point staff to free public EAP services.","url":"https://www.ohmynews.com/NWS_Web/View/at_pg.aspx?CNTN_CD=A0003272885","prio":2,"kor":true,"tags":["WELL","PS","LDR"],"tool":""},{"code":"CULT","date":"2026-10-06","src":"Harvard Business Review","title":"HBR \"수면 부족은 개인 습관 아닌 리더십 문제\" — 미국 관리자·임원 1,009명 조사","eTitle":"Research: Sleep Deprivation Is a Leadership Problem","kSum":"수면 신경과학자 엘스 반데르헬름(IE 대학 겸임교수)이 미국 관리자·임원 1,009명을 조사한 결과, 리더의 수면 부족은 널리 퍼져 있고 많은 리더가 피로가 자기 성과에 미치는 영향을 과소평가했다. 필자는 문제의 핵심이 개인 습관보다 조직 문화, 즉 리더가 무엇을 용인하고 칭찬하는지에 있으며 이것이 수면을 지키게도 하고 피로를 숨기게도 만든다고 본다. 미 육군과 한 포춘 500 기업 연구에서는 수면을 직접 다루지 않고 리더의 기대와 근무 조건을 바꿔 직원 수면이 개선됐다고 소개하며, 리더 자신의 습관·팀의 피로 징후·조직의 지원 여부를 점검하는 '회복 점검(recovery check)'을 제안한다.","eSum":"Sleep neuroscientist Els van der Helm, an adjunct professor at IE University, surveyed 1,009 U.S. managers and executives and found sleep deprivation widespread, with many leaders underestimating how much fatigue affects their performance. She argues the problem is less about individual habits than workplace culture: what leaders tolerate and praise either protects sleep or teaches people to hide tiredness. Citing work with the U.S. Army and a Fortune 500 company, where changing leadership expectations and working conditions improved sleep without targeting it directly, she proposes a 'recovery check' covering leaders' own habits, fatigue signs in their teams and whether the organization supports rest.","kImp":"밤늦게 메일·메신저에 바로 답하는 직원을 칭찬하거나 팀장 스스로 늦은 시간에 업무 지시를 보내는 습관은 팀에 '피로를 숨기라'는 신호가 된다. 팀장은 퇴근 후 메시지를 예약 발송으로 돌리고, 주간 1:1 면담에 업무량과 회복 상태를 묻는 '회복 점검' 질문을 한두 개 넣어 볼 만하다.","eImp":"Praising staff who answer late-night emails and chats, or leaders who send instructions after hours, tells a team to hide fatigue. Team leaders could schedule after-hours messages for the next morning and add one or two recovery-check questions on workload and rest to weekly one-on-ones.","url":"https://hbr.org/2026/10/research-sleep-deprivation-is-a-leadership-problem","prio":2,"kor":false,"tags":["WELL","LDR"],"tool":""},{"code":"CULT","date":"2026-10-05","src":"INSEAD Knowledge","title":"INSEAD 연구: 조직 개편은 때로 사업 문제가 아니라 리더의 불안을 달래는 '방어적 조직화'… 4년 추적한 전문서비스 기업, 연 17% 성장 중에도 개편 반복하다 피인수","eTitle":"INSEAD Research: Restructuring Can Be 'Defensive Organising' That Soothes Leaders' Anxiety, as a Four-Year Study Follows a Firm Growing 17% a Year Into Repeated Overhauls and Acquisition","kSum":"INSEAD Knowledge가 2026년 10월 5일 소개한 데클런 피츠시먼스, 잔피에로·제니퍼 페트리리에리의 Academy of Management Journal 논문은 한 전문서비스 기업('Recco')의 변혁 프로그램을 4년간 추적(관찰 약 760시간, 인터뷰 300건 이상)해, 조직 변화가 합리적 대응이 아니라 리더 자신의 불안을 피하려는 방어적 반응일 수 있음을 보여 줬다. 회사는 연 17% 성장 중이었지만 경쟁사보다 뒤처질까 걱정한 경영진이 통제감을 주는 개편을 밀어붙였고, 사기는 잠시 올랐으나 이익은 계속 줄었으며 '위안을 주는 비전→희생양 찾기→공허한 재참여 의식→청산'의 순환이 갈수록 거세게 반복됐다. 결국 경영진은 CEO를 희생양으로 삼았고 협업이 무너진 회사는 인수됐다. 연구진은 변화를 추진하기 전에 그것이 실제 성과 문제를 푸는지 자기 불편을 덜려는 것인지 묻고, 조직의 감정을 정보로 다루며, 이런 순환이 시작됐다면 외부 개입을 활용하라고 권했다.","eSum":"INSEAD Knowledge on 5 October 2026 featured an Academy of Management Journal study by Declan Fitzsimons, Gianpiero Petriglieri and Jennifer Petriglieri, who followed a transformation programme at a professional services firm they call Recco for four years, with nearly 760 hours of observation and more than 300 interviews. Although the firm was still growing about 17% a year, senior managers' anxiety about falling behind competitors drove restructuring that restored their sense of control; morale briefly lifted but profits kept falling, and a cycle of comforting vision, blame, empty re-engagement rituals and reckoning repeated with growing intensity until the leadership team scapegoated the CEO, collaboration collapsed and the firm was acquired. The authors urge leaders to ask whether a change addresses a real performance problem or mainly relieves their own discomfort, to treat emotion as information and to bring in outside intervention once a defensive cycle is under way.","kImp":"부서 개편이나 새 제도를 밀어붙이기 전에 팀장은 '어떤 성과 문제를 푸는가', '측정할 수 있는 근거가 있는가'를 문서로 정리해 보고, 개편 뒤 책임 추궁이 특정인에게 쏠리는 조짐이 보이면 다른 부서나 HR의 시각을 들여 점검하는 것이 좋다.","eImp":"Before pushing through a reorganisation or new policy, team leaders should write down which performance problem it solves and what measurable evidence supports it, and if blame starts to concentrate on one person afterwards, bring in a view from another department or HR.","url":"https://knowledge.insead.edu/leadership-organisations/perils-defensive-organising","prio":1,"kor":false,"tags":["CHG","LDR"],"tool":""},{"code":"CULT","date":"2026-09-24","src":"Gallup","title":"갤럽: 미국 직장인 20%만 '회사가 직원 데이터를 책임 있게 쓴다'고 깊이 신뢰… 자기 업무 데이터에 대해 대화해 본 직원은 19%뿐","eTitle":"Gallup: Only 20% of US Workers Trust Leaders a Great Deal to Use Employee Data Responsibly, and Just 19% Have Had Anyone Discuss Their Work Data With Them","kSum":"갤럽이 2026년 9월 24일 공개한 조사(미국 직장인 2만2,573명, 5월 6~20일)에서 리더가 직원 데이터를 책임 있게 쓸 것이라고 '매우 신뢰'한다는 응답은 20%였고, 몰입 직원 40%, 비몰입 13%, 적극적 비몰입 4%로 차이가 컸다. 59%는 회사가 근무시간·출입 기록·이메일 건수 같은 활동 데이터를, 46%는 이메일·회의 내용 같은 내용 데이터를 수집한다고 여겼지만, 누군가 자기 업무 데이터나 지표를 함께 이야기해 준 적이 있다는 응답은 19%에 그쳤다. 활동 데이터 활용에 대한 편안함은 팀 효과성 지원(62%)이 성과평가(53%)보다 높았다. 갤럽은 수집 목적·용도와 하지 않는 일까지 투명하게 알리고, 관리자가 직원 질문에 답할 수 있게 데이터 관행을 공유하라고 권했다.","eSum":"Gallup, publishing on 24 September 2026 a survey of 22,573 employed US adults conducted on 6-20 May, found that 20% trust leaders a great deal to use employee data responsibly, ranging from 40% of engaged employees to 13% of not-engaged and 4% of actively disengaged employees. While 59% believe their employer collects activity data such as hours, badge swipes or email counts and 46% believe it collects content data such as emails or meeting content, only 19% say someone at work has discussed data or metrics about their work with them. Comfort with using activity data was higher for supporting team effectiveness (62%) than for performance reviews (53%). Gallup urges leaders to be transparent about the purpose and limits of data use and to give managers enough visibility to answer employees' questions.","kImp":"업무 시스템·협업 도구 기록을 관리에 쓰기 전에 팀장은 '무엇을 수집하고 어디에 쓰며 무엇에는 쓰지 않는지'를 팀원에게 먼저 설명하고, 평가보다 업무 개선용으로 쓰는 것부터 시작하는 것이 신뢰를 지키는 순서다.","eImp":"Before using records from work systems or collaboration tools for management purposes, team leaders should first tell staff what is collected, what it is used for and what it will not be used for, and start with process improvement rather than appraisal.","url":"https://www.gallup.com/workplace/714932/employee-data-one-five-trust-leaders-great-deal.aspx","prio":2,"kor":false,"tags":["DATA","ENG","SEC"],"tool":""},{"code":"CULT","date":"2026-09-22","src":"American Psychological Association","title":"미국심리학회 2026 Work in America: 직장인 48% '근무 중 긴장·스트레스', 건강한 직장 응답 85%→80%… '심리적 자본' 높은 직원 이직 의향 19% vs 낮은 직원 51%","eTitle":"APA's 2026 Work in America Survey: 48% of Workers Feel Tense or Stressed at Work, and Those With High Psychological Capital Are Far Less Likely to Plan to Leave (19% vs 51%)","kSum":"미국심리학회(APA)가 2026년 9월 22일 발표한 Work in America 조사(해리스폴, 미국 직장인 2,009명, 5월 21일~6월 1일)에서 근무 중 대체로 긴장·스트레스를 느낀다는 응답은 48%, 업무 환경이 정신건강에 해롭다는 응답은 37%(전년 32%)였고, 직장이 건강하다는 응답은 85%에서 80%로, 직장에서 가치 있게 대우받는다고 느낀다는 응답은 84%에서 80%로 내려갔다. 몇 주~몇 달 안에 일자리를 잃을까 걱정한다는 응답도 26%에서 32%로 늘었다. 희망·효능감·회복탄력성·낙관으로 이뤄진 '심리적 자본(PsyCap)'이 높은 직원은 스트레스 38%(낮은 직원 55%), 1년 내 이직 의향 19%(낮은 직원 51%)로 차이가 컸다. APA는 성과 결과만이 아니라 적응 역량까지 넓게 보고, 기술 투자와 함께 사람의 적응 역량에도 투자하라고 권했다.","eSum":"The American Psychological Association's 2026 Work in America survey, released on 22 September 2026 (The Harris Poll, 2,009 employed US adults, 21 May to 1 June), found 48% of workers typically feel tense or stressed during the workday and 37% say their work environment harms their mental health (up from 32%), while the shares calling their workplace healthy and feeling valued both fell to 80% (from 85% and 84%). Worry about losing one's job within weeks or months rose from 26% to 32%. Workers with high psychological capital (hope, efficacy, resilience and optimism) reported far less stress (38% vs 55%) and were much less likely to plan to leave within a year (19% vs 51%). APA urges employers to measure performance more broadly and to build workers' capacity to adapt alongside investment in new technology.","kImp":"변화가 잦은 시기일수록 팀장은 성과 수치만 보지 말고 1:1 면담에서 '요즘 일이 감당되는지', '무엇이 막히는지'를 정기적으로 묻고, 새 시스템을 들일 때는 교육·질문 시간을 일정에 함께 넣어 직원의 적응 부담을 덜어 주는 것이 좋다.","eImp":"In periods of frequent change, team leaders should look beyond output metrics, regularly ask in one-to-ones whether workloads feel manageable and what is getting in the way, and build training and Q&A time into the schedule whenever a new system is introduced.","url":"https://www.apa.org/news/press/releases/2026/09/psychological-capital-work-stress","prio":3,"kor":false,"tags":["WELL","ENG","AI"],"tool":""},{"code":"CULT","date":"2026-09-22","src":"HR Insight","title":"Korea Workplace Index ② — 몰입층 53.4%→38.5% 급감, 떠나지 않고 ‘침전’한 직원 32.6%… 주니어는 가라앉고 부장급은 떠난다","eTitle":"Korea Workplace Index (2): The Engaged Share Fell From 53.4% to 38.5% as Juniors Withdrew in Place and Senior Managers Moved Toward the Exit","kSum":"H2C 추한규 연구소장이 10년 조직건강 진단 데이터를 시기별로 나눠 보니 몰입권은 2019년까지와 팬데믹기(2020~2021년) 모두 53.4%였다가 2022년 이후 38.5%로 14.9%p 줄었고, 남아 있지만 에너지를 거둔 침전권은 22.3%에서 32.6%로, 떠날 준비를 하는 이탈권은 24.2%에서 28.9%로 늘어 '억눌린 것은 이탈이었지 침전이 아니었다'고 분석했다. 직급별로 대리 이하는 침전권이 12.5%p 늘었고 부장 이상은 이탈권이 7.4%p로 가장 많이 늘었으며, 세 직급 모두 '몰입 소진형'이 10~15%p 줄었다. 저자는 이를 투입(시간·노력·책임)과 보상(인정·성장·다음 자리)의 균형이 깨진 심리적 계약 문제로 보고, '가족 같은 회사'·'주인의식' 같은 호소 대신 주니어에게는 무엇이 몰입하게 하는지 묻고, 중간관리자에게는 성장 경로와 인정을, 시니어에게는 경력 후반 역할을 설계해 주라고 권했다.","eSum":"Splitting ten years of H2C organisational health data by period, research director Choo Han-kyu finds the engaged zone held at 53.4% up to 2019 and through the 2020-2021 pandemic but fell 14.9 points to 38.5% from 2022, while the 'sinking' zone of people who stay but withdraw effort rose from 22.3% to 32.6% and the exit-ready zone from 24.2% to 28.9%. Staff at assistant-manager level and below saw sinking rise by 12.5 points, senior managers saw the largest rise in exit readiness at 7.4 points, and the 'engaged but exhausted' group shrank by 10-15 points at every level. He frames this as a broken psychological contract between input and reward and urges organisations to drop appeals to 'family' and 'ownership' in favour of asking juniors what keeps them engaged, giving mid-level staff clear growth paths and recognition, and designing late-career roles for seniors.","kImp":"직원 유지 상태를 퇴사율만으로 보지 말고 저연차·중간관리자·부장급으로 나눠 몰입 상태를 살펴볼 만하다. 경력 면담에서 '가족 같은 회사' 같은 호소 대신 저연차에게는 무엇이 일에 몰입하게 하는지 묻고, 중간관리자에게는 성장 경로와 인정을, 고참 관리자에게는 경력 후반 역할을 구체적으로 보여 주는 것이 좋다.","eImp":"Track engagement separately for junior staff, mid-level managers and senior managers instead of relying on turnover alone. In career conversations, skip appeals to 'family' and instead ask juniors what keeps them engaged, show mid-level staff a clear growth path and recognition, and design concrete late-career roles for senior managers.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39592","prio":2,"kor":true,"tags":["ENG","RET"],"tool":""},{"code":"CULT","date":"2026-09-22","src":"HR Insight","title":"HD현대마린솔루션, 협업 점수 낮게 나오자 연 1회 진단 대신 격월 ‘펄스 서베이’ — 결과는 전사 공개, 체인지 리더가 현장 면담으로 원인 확인","eTitle":"HD Hyundai Marine Solution Swaps Annual Culture Surveys for Bimonthly Pulse Surveys, Shares Results Company-Wide and Sends Change Leaders to Ask Why","kSum":"선박 인도 후 기술보증·부품·개조와 친환경·디지털 솔루션을 제공하는 HD현대마린솔루션(국내외 약 1,000명, MZ세대 85% 이상)은 지난해 자체 조직문화 서베이에서 협업 항목 점수가 상대적으로 낮고 부서 간 사일로를 줄여야 한다는 의견이 나오자, 지난해 11월 부임한 대표이사가 '원팀'을 핵심 운영 방향으로 제시했다. 연 단위 진단으로는 인식 변화를 제때 알 수 없어 올해부터 10분 안에 답하는 격월 펄스 서베이(회사생활 자부심, 몰입 방해 요소, 개선 방안을 묻는 주관식 포함)를 운영하며, 결과는 익명 처리해 사내 게시판으로 전사에 공유하고 부문별 결과는 부문장과 체인지 리더(CL)에게 전달해 이전 조사와 비교한다. 점수가 낮아도 숫자만으로 해법을 정하지 않고 CL이 현업 구성원을 직접 만나 이유와 맥락을 확인하며, 3차 조사를 마친 뒤 4차부터는 해외법인 구성원까지 참여를 넓힐 계획이다(구독 기사로 후반부 비공개).","eSum":"HD Hyundai Marine Solution, which provides post-delivery warranty, parts, retrofit, green and digital services and has about 1,000 staff at home and abroad, more than 85% of them millennials or Gen Z, made 'one team' a core operating priority under a chief executive appointed last November after its own culture survey showed relatively low collaboration scores and calls to break down silos. Because annual diagnostics could not track shifts in sentiment in time, it now runs a ten-minute pulse survey every two months, including open questions on pride, obstacles to engagement and improvements, posts anonymised results company-wide and gives divisional results to division heads and change leaders for comparison with earlier rounds. Low scores are not acted on from numbers alone: change leaders meet staff to learn the reasons and context, and after three rounds the survey is being extended to overseas subsidiaries from the fourth (subscriber article; later part not public).","kImp":"연 1회 조직문화 진단만으로는 인식 변화를 제때 알기 어렵다. 10분 안에 답하는 격월 펄스 설문을 돌려 익명 결과를 전 직원에게 공유하고, 점수가 낮은 부서는 숫자만으로 해법을 정하지 말고 담당자가 직원을 직접 만나 이유와 맥락을 확인하는 방식을 시험해 볼 만하다.","eImp":"A once-a-year culture survey is too slow to catch shifts in sentiment. Try a ten-minute bimonthly pulse survey with anonymised results shared with all staff, and for low-scoring departments have a designated change lead talk with employees to understand the reasons before deciding on fixes.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39588","prio":1,"kor":true,"tags":["ENG","COLLAB","CHG"],"tool":""},{"code":"CULT","date":"2026-09-14","src":"SHRM","title":"SHRM \"심리적 안전은 '편안함'이 아니라 어려운 일을 안전하게 하는 조건\" — '산만한 근무' 경고","eTitle":"Why Workplaces Need to Think Differently About Psychological Safety","kSum":"SHRM의 캐서린 메이어 기자가 인터뷰한 리더십 컨설턴트 스티브 로빈스(S.L. Robbins & Associates 창업자)는 심리적 안전이 효과가 눈에 잘 띄지 않아 과소평가되지만 참여·연결·존중감처럼 조직이 중시하는 가치의 바탕에 있다고 말한다. 그는 비난을 피하고 무엇을 말해도 안전한지 살피느라 주의를 쓰는 상태를 '산만한 운전'에 빗대 '산만한 근무(distracted working)'라 부르며, 심리적 안전은 어려운 대화를 피하거나 기준을 낮추거나 책임을 없애는 것이 아니라고 강조한다. 그는 HR이 심리적 안전을 소프트 스킬이 아닌 인간 성과의 조건으로 다루고, 리더가 '이 환경은 사람들에게 정신적·감정적 에너지를 어디에 쓰게 만드는가'를 물어야 한다고 제안한다.","eSum":"In a SHRM interview by Kathryn Mayer, leadership consultant Steve Robbins, founder of S.L. Robbins & Associates, argues that psychological safety is underrated because its effects are hard to see, yet it underpins the participation, connection and sense of value organizations say they care about. He likens the attention people spend avoiding blame and judging what is safe to say to distracted driving, calling it 'distracted working', and stresses that psychological safety does not mean avoiding hard conversations, lowering standards or removing accountability. He urges HR to treat it as a condition for human performance rather than a soft-culture issue and to ask what the environment requires people to spend their mental and emotional energy on.","kImp":"질책을 피하려 눈치 보는 데 쓰는 주의만큼 실제 업무 집중력이 줄어든다는 논리는 팀장이 심리적 안전을 '복지'가 아닌 '성과 조건'으로 설명하는 언어가 된다. 1:1 면담에서 '보고나 질문을 하기 전에 가장 신경 쓰이는 것이 무엇인가'를 물어 팀원이 에너지를 어디에 쓰고 있는지 확인해 볼 만하다.","eImp":"The idea that attention spent dodging blame is attention taken from the work itself lets team leaders explain psychological safety as a condition for performance rather than a perk. In one-on-ones, ask what worries people most before they raise a question or report a problem, to see where their energy is going.","url":"https://www.shrm.org/topics-tools/news/inclusion-diversity/workplaces-psychological-safety","prio":2,"kor":false,"tags":["PS","SPEAK"],"tool":""},{"code":"CULT","date":"2026-08-24","src":"HR Insight","title":"Korea Workplace Index ① — 1만 1,869명 10년 데이터: 정서적 몰입 66.1%→44.6%, 이직률·번아웃 지표에 안 잡히는 ‘조용한 침전형’ 28.0%","eTitle":"Korea Workplace Index (1): Ten Years of Data on 11,869 Employees Show Emotional Commitment Falling From 66.1% to 44.6% and a 28% 'Quiet Sinking' Group Invisible to Turnover Metrics","kSum":"HR Insight와 H2C가 2016년부터 10년간 국내 기업 임직원 1만 1,869명의 조직건강 진단(140여 문항)을 분석한 결과 조직만족 긍정률은 2016년 39.6%에서 2025년 38.6%로 제자리였지만 정서적 몰입은 66.1%에서 44.6%로 21.5%p 떨어져 다섯 지표 중 가장 크게 하락했고, '회사의 성공이 곧 나의 성공' 문항은 85.6%에서 48.6%로 낮아졌다. 군집분석으로 나눈 다섯 유형 가운데 만족·몰입·열의는 평균보다 낮지만 탈진과 이직 의도는 강하지 않은 '조용한 침전형'이 28.0%로 이직률이나 번아웃 지표에 잡히지 않는 사각지대로 제시됐고, '완전 이탈형'(7.8%)은 89.3%가 떠나고 싶다고 답했다. 같은 '지친' 집단이라도 몰입 소진형의 이직 의도는 16.1%, 소진된 이탈 대기형은 70.7%로 갈렸는데, 둘을 가른 것은 탈진 정도가 아니라 조직에 대한 만족과 연결감이었다.","eSum":"HR Insight and H2C analysed organisational health diagnostics of 11,869 Korean company employees answering some 140 items since 2016: satisfaction was flat at 39.6% in 2016 and 38.6% in 2025, but emotional commitment fell 21.5 points from 66.1% to 44.6%, the steepest drop of five indicators, and agreement that 'the company's success is my success' fell from 85.6% to 48.6%. Cluster analysis identified a 'quiet sinking' type of 28.0% with below-average satisfaction, commitment and engagement but no strong burnout or intention to quit, a blind spot for turnover and burnout metrics, while 89.3% of the fully disengaged type (7.8%) wanted to leave. Among exhausted employees, turnover intention was 16.1% for the engaged-but-exhausted and 70.7% for the exhausted exit-ready, separated not by the level of burnout but by satisfaction with and connection to the organisation.","kImp":"직원 상태를 퇴사율·번아웃 지표로만 보면 떠나지도 지치지도 않았지만 조용히 의욕을 거둔 '침전형' 직원을 놓치기 쉽다. 조직문화 설문이나 정기 면담에 회사와의 연결감, '회사의 성공이 곧 나의 성공'처럼 몰입을 묻는 짧은 문항을 넣어 이런 직원을 찾아볼 만하다.","eImp":"Looking only at turnover and burnout metrics misses employees who are neither leaving nor exhausted but have quietly withdrawn. Add short questions on connection to the company and commitment, such as whether the company's success feels like their own, to culture surveys or regular check-ins to find them.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39498","prio":2,"kor":true,"tags":["ENG","RET","WELL"],"tool":""},{"code":"CULT","date":"2026-08-12","src":"뉴시스","title":"블라인드 지수 2026 \"행복도 떨어진 회사 370곳 넘는데 이직 시도는 줄어\"…50점 이상 회사 47%→33%, 교수 \"만족 아닌 관망\"","eTitle":"Blind Index 2026: Happiness Fell at More Than 370 Companies While Job-Change Attempts Declined, and the Share of Firms Scoring 50 or Above Dropped From 47% to 33% in What a Professor Calls Wait-and-See, Not Satisfaction","kSum":"직장인 커뮤니티 블라인드가 한국노동연구원과 함께 만든 15개 지표(일·관계·문화)로 2025년 7~12월 재직 인증 직장인 3만4,372명을 조사한 '블라인드 지수 2026'에서 행복도가 전년보다 오른 회사는 100여 곳, 떨어진 회사는 370곳을 넘었고 50점 이상 회사 비중은 47%에서 33%로 줄었다. 그럼에도 최근 1년간 이직을 시도한 직장인 비율은 오히려 전년보다 줄었고, 직군별로는 기획자(36점)·직업군인(37점)·고객서비스(40점)가 가장 낮았다. 블라인드가 상·하위 기업 직원 글 21만8,000건을 AI로 분석한 결과 상위 기업군에서는 조직 개선을 전제로 한 질문이 퇴사·이직을 전제로 한 질문보다 1.8배 많았다. 신재용 서울대 교수는 이직 감소가 만족이 아니라 위축된 노동시장 속 관망의 결과라고 해석했다.","eSum":"Blind Index 2026, built by workplace platform Blind with the Korea Labor Institute on 15 indicators covering work, relationships and culture and based on 34,372 verified employees surveyed from July to December 2025, found happiness rose at about 100 companies but fell at more than 370, and the share of companies scoring 50 or above dropped from 47% to 33%. Yet the share of employees who tried to change jobs in the past year actually fell, and planners (36), career soldiers (37) and customer-service staff (40) were the lowest-scoring roles. Blind's AI analysis of 218,000 posts found that at top-scoring firms, questions premised on improving the organisation outnumbered those premised on leaving by 1.8 to 1. Seoul National University professor Shin Jae-yong read the fall in job changes as wait-and-see behaviour in a shrinking labour market rather than satisfaction.","kImp":"이직이 줄었다고 직원이 만족한다고 보면 안 되므로, 팀장은 퇴사율 대신 회의·면담에서 '조직을 어떻게 바꾸면 좋을지' 같은 개선 제안이 나오는지, 아니면 말이 사라졌는지를 몰입의 신호로 살펴볼 만하다.","eImp":"Lower turnover should not be read as satisfaction, so team leaders can watch whether people still raise ideas for improving the organisation in meetings and one-to-ones, or have gone quiet, as a sign of engagement rather than relying on resignation figures.","url":"https://www.newsis.com/view/NISX20260812_0003746762","prio":2,"kor":true,"tags":["ENG","RET","DATA"],"tool":""},{"code":"CULT","date":"2026-04-07","src":"Gallup","title":"갤럽 '2026 세계 직장 현황': 전 세계 직원 몰입도 20%로 2년 연속 하락(2022년 23%)… 관리자 몰입도 27%→22%로 급락, 생산성 손실 약 10조 달러","eTitle":"Gallup's State of the Global Workplace 2026: Global Engagement Falls for a Second Year to 20%, Manager Engagement Drops From 27% to 22%, and Lost Productivity Costs About $10 Trillion","kSum":"갤럽이 2026년 4월 7일 공개한 State of the Global Workplace 2026(140여 개국·지역, 2025년 취업자 14만1,444명 응답)에서 전 세계 직원 몰입도는 20%로 2년 연속 떨어져 2022년 정점(23%) 이후 내리막을 이어 갔고 2020년 이후 최저였다. 관리자 몰입도는 2024년 27%에서 22%로 5%p 떨어져 팀원 수준(19%)에 가까워졌으며, 갤럽은 조직 슬림화와 관리 범위 확대를 원인의 하나로 짚었다. 몰입도가 오른 지역은 한 곳도 없었고(남아시아 -5%p로 최대 하락), 낮은 몰입으로 인한 생산성 손실은 세계 GDP의 약 9%인 10조 달러로 추산됐다. 갤럽은 관리자의 선발·교육·지원을 최우선에 두고, 조직을 납작하게 만들 때는 비용만 보지 말고 관리자의 업무 범위와 팀 몰입을 함께 고려하라고 권했다.","eSum":"Gallup's State of the Global Workplace 2026, released on 7 April 2026 and covering more than 140 countries and territories with 141,444 employed respondents in 2025, found global employee engagement fell for a second straight year to 20%, down from a 2022 peak of 23% and the lowest since 2020. Manager engagement dropped five points, from 27% in 2024 to 22%, converging with individual contributors (19%), which Gallup links partly to organisational flattening and wider spans of control. No region improved, South Asia fell most (five points), and low engagement cost an estimated $10 trillion in lost productivity, about 9% of global GDP. Gallup urges organisations to prioritise manager selection, training and support and to weigh managers' workloads and team engagement, not just cost, when flattening structures.","kImp":"팀장에게 실무와 관리를 함께 떠안기는 구조는 팀장 본인의 몰입부터 떨어뜨리므로, 관리 인원과 실무 비중을 함께 점검하고 신임 팀장에게는 1:1 면담·피드백 같은 관리 업무 시간을 공식적으로 확보해 주는 것이 좋다.","eImp":"Loading team leaders with both hands-on work and people management erodes their own engagement first, so organisations should review spans of control alongside individual workloads and formally protect time for one-to-ones and feedback for new team leaders.","url":"https://www.gallup.com/workplace/708071/global-employee-engagement-continues-decline.aspx","prio":3,"kor":false,"tags":["ENG","LDR","WELL"],"tool":""}]},{"code":"INNOV","kTitle":"업무 혁신·AI·변화관리","eTitle":"Work innovation, AI and change management","items":[{"code":"INNOV","date":"2026-10-28","src":"뉴시스","title":"KRG \"매출 2,000억 원 이상 기업 내년 AI 예산 평균 18억 원, 23.8%↑\"…PoC 건수 대신 업무시간·운영비 절감으로 성과 평가","eTitle":"KRG Survey of About 220 Korean Firms Puts Next Year's Average AI Budget at 1.82 Billion Won, Up 23.8%, With Results to Be Judged on Hours and Costs Saved Rather Than Pilot Counts","kSum":"시장조사업체 KRG의 '2027년 국내외 AI·디지털 시장전망'(매출 2,000억 원 이상 국내 주요 기업 약 220곳 조사)에 따르면 내년 기업당 평균 AI 예산은 18억1,800만 원으로 올해(14억6,800만 원)보다 23.8%, 지난해(11억2,500만 원)보다는 약 62% 늘어난다. 업종별 평균은 금융 68억2,700만 원, 도소매·유통 29억400만 원, 정보통신·미디어 5억1,300만 원, 제조 3억9,400만 원이며 증가율은 제조(27.5%)가 가장 높다. 기업들은 문서·검색 보조를 넘어 사내 데이터·시스템과 연결해 여러 단계 업무를 처리하는 AI 에이전트에 투자를 늘리고, 성과는 도입 여부나 개념검증(PoC) 건수가 아니라 생산성 향상과 업무시간·운영비 절감으로 평가하겠다고 답했다.","eSum":"KRG's 2027 AI and digital market outlook, based on about 220 Korean companies with annual sales above 200 billion won, puts next year's average AI budget per company at 1.818 billion won, up 23.8% from 1.468 billion won this year and about 62% above last year's 1.125 billion won. Average budgets are 6.83 billion won in finance, 2.90 billion in wholesale and retail, 513 million in information, communications and media and 394 million in manufacturing, which is growing fastest (27.5%). Firms plan to move beyond document and search assistance towards AI agents connected to internal data and systems, and say they will judge results by productivity, hours and operating costs saved rather than by adoption or pilot counts.","kImp":"사무실 AI 도입을 '써 봤다'로 끝내지 말고 보고서 작성·자료 취합처럼 시간을 잴 수 있는 업무 하나를 정해 도입 전후 소요 시간을 기록해 두면, 예산 심사나 확대 결정 때 근거로 쓸 수 있다.","eImp":"Rather than stopping at trying AI, an office team can pick one measurable task such as compiling reports or collating data and record the time it takes before and after, which gives evidence for budget reviews and decisions on wider rollout.","url":"https://www.newsis.com/view/NISX20261027_0003843339","prio":2,"kor":true,"tags":["AI","DATA"],"tool":""},{"code":"INNOV","date":"2026-10-28","src":"파이낸셜뉴스","title":"파수 AI \"생성형 AI 막은 조직에서도 개인 계정 사용률 77%\"…개인 계정 사용 파악·통제하는 곳은 19%뿐","eTitle":"Fasoo AI Survey Finds Personal-Account Use of Generative AI Reaches 77% Even Among Respondents Whose Organisations Ban It, While Only 19% of Organisations Monitor Such Use","kSum":"파수 AI가 28일 낸 보고서 '통제 밖의 지능-국내 조직의 섀도우 AI 사용 실태와 대응 현황'(국내 주요 기업·기관 AI·IT·보안 담당자 151명 조사)에 따르면 응답 조직의 15%가 생성형 AI 사용을 원칙적으로 막고 있었지만, 이 응답 그룹에서도 개인 계정 생성형 AI 사용률이 77%에 달했다. 전체 응답자의 89%가 업무에 개인 계정 AI를 쓴다고 답한 반면 개인 계정 사용을 파악·통제하는 조직은 19%에 그쳤다. 원인 1위는 명확한 사용 정책·가이드라인 부재(29%)였고, 대응책으로는 보안이 갖춰진 사내 AI 도구 제공(26%)이 가장 많이 꼽혔다.","eSum":"Fasoo AI's report on shadow AI in Korean organisations, released on 28 October and based on 151 AI, IT and security managers at major companies and institutions, found that 15% of respondents said their organisation broadly blocks generative AI, yet personal-account use of generative AI reached 77% even within that group. Overall, 89% of respondents said personal-account AI is used for work, while only 19% of organisations track or control it. The lack of clear usage policies or guidelines was the leading cause (29%), and providing a secure in-house AI tool was the most cited remedy (26%).","kImp":"AI 사용을 막기만 하면 직원들이 개인 계정으로 옮겨 가 기록조차 남지 않으므로, 회사가 승인한 AI 도구와 '올려서는 안 되는 자료'(선원 개인정보·계약·고객 자료 등) 목록을 짧은 지침으로 함께 내놓는 편이 안전하다.","eImp":"Simply banning AI pushes staff onto personal accounts that leave no record, so it is safer to offer an approved AI tool together with a short guideline listing what must never be uploaded, such as personal data, contracts and client files.","url":"https://www.fnnews.com/news/202610281410459347","prio":2,"kor":true,"tags":["AI","SEC","POL"],"tool":""},{"code":"INNOV","date":"2026-10-27","src":"DBR","title":"DBR '직원이 AI를 더 신뢰하게 하려면 리더가 걱정을 겸손히 들어야' — 우려를 말할 기회와 리더의 겸손이 리더 신뢰를 거쳐 AI 신뢰로 옮겨간다(미국 직장인 487명 연구)","eTitle":"DBR: To Make Staff Trust AI, Leaders Must Listen Humbly to Their Concerns - Voice and Leader Humility Build Trust in the Leader That Transfers to AI (a Study of 487 US Employees)","kSum":"DBR 11월 1호(10월 27일 발행)는 McGuire·De Cremer·Narayanan의 2026년 『Journal of Business Research』(217권) 논문을 소개했다. 싱가포르경영대·킹파드석유광물대·스탠퍼드대 연구진은 일반 직원이 AI의 성능이나 판단 과정을 직접 평가하기 어렵다는 점에 주목해, 직원이 AI에 대한 우려를 말할 기회를 얻고 리더가 자기 판단이 틀릴 수 있음을 인정하며 겸손하게 들을 때 부정적 감정이 줄고 리더 신뢰가 높아지며 그 신뢰가 리더가 도입한 AI로 옮겨간다는 가설을 두 차례 연구로 검증했고, DBR은 이를 '리더가 직원의 걱정을 겸손히 들어야 AI 신뢰가 높아진다'로 정리했다. 첫 연구는 주 2회 이상 AI를 쓰는 미국 정규직 직장인을 1주 간격으로 네 차례 설문해 487명의 자료를 분석했고, 응답자의 73.3%는 추천 시스템형 AI를 쓰고 있었다(구독 기사, 공개된 앞부분 기준).","eSum":"DBR's 1st November issue (published 27 October) reviews a 2026 Journal of Business Research paper (vol. 217) by Jack McGuire, David De Cremer and Devesh Narayanan. Noting that ordinary employees struggle to judge an AI system's accuracy or reasoning, the researchers from Singapore Management University, King Fahd University of Petroleum and Minerals and Stanford tested in two studies whether giving staff a chance to voice concerns about AI, with leaders listening humbly and admitting they could be wrong, reduces negative feelings and raises trust in the leader that then transfers to the AI the leader introduced; DBR sums up the finding as leaders needing to hear staff worries humbly. The first study surveyed US full-time employees who use AI at least twice a week four times at one-week intervals and analysed 487 complete responses; 73.3% were using recommendation-type AI (subscriber article; summary based on the free opening section).","kImp":"사내에 새 AI 도구를 들일 때 사용법 교육만 하지 말고 직원이 걱정과 불편을 말하는 시간을 따로 두고, 도입을 맡은 팀장이 '우리 판단이 틀릴 수 있다'며 받은 의견을 실제로 반영하는 모습을 보여야 정착이 빨라진다.","eImp":"When introducing a new AI tool at work, set aside time for staff to voice worries and frustrations, not just learn how to use it, and have the leaders driving adoption visibly act on that feedback while acknowledging they could be wrong; adoption tends to stick faster that way.","url":"https://dbr.donga.com/article/view/1904/article_no/12308","prio":2,"kor":true,"tags":["AI","CHG","SPEAK"],"tool":""},{"code":"INNOV","date":"2026-10-27","src":"Anthropic","title":"앤트로픽 실험: 전문 분석가들, AI 에이전트가 몰래 기운 쪽을 86% 따라가…77%는 AI 논리를 그대로 옮겨","eTitle":"Anthropic trial: analysts went with their AI agent's hidden lean 86% of the time, and 77% repeated its arguments","kSum":"앤트로픽은 2026년 10월 27일, 인과분석 경험이 있는 전문 분석가 61명(에이전트를 쓰지 않은 11명 제외 50명)이 AI 에이전트(Claude Code)와 함께 가상의 농업협동조합 사업 존폐를 판단하게 한 무작위 대조 실험 결과를 발표했다. 연구진이 네 가지 분석 선택마다 에이전트가 한쪽을 몰래 선호하도록 설정하자 분석가들은 86%(우연 기준 50%) 에이전트 쪽을 택했고, 먼저 의견을 밝힌 경우에도 에이전트가 반대하면 60%가 입장을 바꿨다(동의할 때는 6%, 38건 기준). 77%는 답변에서 에이전트 논리를 되풀이했지만 AI를 출처로 밝힌 비율은 15%에 그쳤다. AI 없이 작업한 11명 중 6명(55%)이 결과를 무효로 만드는 심각한 오류를 낸 반면 에이전트 사용자는 50명 중 3명(6%)이었으나, 연구진은 두 집단이 스스로 선택돼 직접 비교할 수 없다고 밝혔다.","eSum":"On October 27, 2026, Anthropic published a randomized controlled trial in which 61 professional analysts with causal-analysis experience (50 after excluding 11 who chose not to use the agent) worked with an AI agent, Claude Code, to advise a fictional farming cooperative on whether to keep a program. When the researchers secretly set the agent to favor one option on each of four analytical choices, analysts went with the agent's lean 86% of the time against a 50% chance baseline, and those who had stated a view first switched away 60% of the time when the agent disagreed versus 6% when it agreed, based on 38 cases. 77% repeated the agent's arguments in their justifications, but only 15% credited the agent. Six of the 11 analysts who worked without AI (55%) made serious result-invalidating errors versus 3 of 50 agent users (6%), though the authors caution that the groups self-selected and are not directly comparable.","kImp":"AI로 보고서·분석 초안을 만드는 팀이라면 결론을 좌우하는 기준(비교 방법·평가 지표 등)은 담당자가 AI에 묻기 전에 먼저 정해 적어 두고, AI에 반대 선택지의 근거도 함께 내놓게 하는 검토 습관을 들일 만하다.","eImp":"Teams that draft reports and analyses with AI should have the person in charge decide and write down the criteria that drive the conclusion, such as comparison methods and metrics, before asking the AI, and routinely ask the AI to argue the opposite option as well.","url":"https://www.anthropic.com/research/agents-judgment-calls","prio":2,"kor":false,"tags":["AI","DATA"],"tool":""},{"code":"INNOV","date":"2026-10-27","src":"DBR","title":"DBR 인터뷰: 마이리얼트립 'AI 네이티브' 전환 — 보안·법적 위험·일정 예산 이상이 아니면 결재 없이 실행, 사내 지식 저장소 '세컨드 브레인'으로 개인 노하우를 조직 자산으로","eTitle":"DBR Interview: MyRealTrip's 'AI-Native' Shift - Staff Act Without Sign-Off Unless Security, Legal Risk or a Budget Threshold Is Involved, and a 'Second Brain' Knowledge Base Turns Individual Know-How Into Company Assets","kSum":"DBR 11월 1호(10월 27일 발행)에 실린 허원진 마이리얼트립 CTO 인터뷰에 따르면, 이 회사는 올해 초 'AI 네이티브 조직' 전환을 선언하고 전 구성원의 AI 활용 역량을 높이는 데서 출발해 개발·기획·디자인의 경계를 허물고 업무 권한과 평가 기준을 다시 설계했다. 보안 사고나 법적 위험이 있거나 일정 수준 이상의 예산이 드는 일이 아니면 누구나 별도 결재 없이 스스로 판단해 실행할 수 있게 했고, AI가 과거 의사결정·자료·코드 같은 회사의 업무 맥락을 이해하도록 사내 지식 저장소 '세컨드 브레인'을 구축해 개인에게 흩어진 정보와 노하우를 조직 자산으로 쌓았다. DBR은 이를 AI가 잘하는 일은 AI에 맡기고, AI로 할 수 있는 일이 늘어난 구성원에게는 그만큼의 판단·실행 권한을 넘기는 '두 가지 위임'으로 정리했다(구독 기사, 공개된 앞부분 기준).","eSum":"In an interview in DBR's 1st November issue (published 27 October), MyRealTrip CTO Heo Won-jin explains that the travel platform declared an 'AI-native organisation' shift early this year: it started by raising every employee's AI skills, then dissolved boundaries between development, planning and design and redesigned work authority and evaluation criteria. Unless a task involves security incidents, legal risk or spending above a set budget, anyone can decide and act without separate approval, and the company built an internal knowledge base, the 'Second Brain', so AI can understand past decisions, documents and code, turning information and know-how scattered across individuals into organisational assets. DBR frames this as two delegations: handing AI what it does well, and giving people whose capacity AI has expanded matching authority to decide and act (subscriber article; summary based on the free opening section).","kImp":"AI 도구 보급과 함께 '결재 없이 담당자가 처리해도 되는 일'의 범위와 예외(보안·법적 위험·일정 금액 이상)를 문서로 정해 두고, 과거 결정과 처리 사례를 한곳에 모아 AI와 신규 직원이 함께 참고하게 하는 것부터 시작해 볼 만하다.","eImp":"Alongside rolling out AI tools, teams could document which tasks staff may complete without approval and the exceptions, such as security, legal risk or spending above a limit, and start by gathering past decisions and handled cases in one place that both AI and new staff can consult.","url":"https://dbr.donga.com/article/view/1101/article_no/12314","prio":2,"kor":true,"tags":["AI","WR","LDR"],"tool":""},{"code":"INNOV","date":"2026-10-26","src":"Fast Company","title":"미국 공공부문 25만 명 AI 교육 데이터: 수강생 51%는 생성형 AI 첫 경험…비사용자 19%는 '써도 되는지 몰라서'","eTitle":"Lessons from 250,000 public workers: 51% had never tried generative AI, and 19% of non-users did not know if they were allowed","kSum":"패스트컴퍼니는 2026년 10월 26일, 미국 주·지방정부 공무원 25만 명 이상에게 AI·디지털 교육을 해 온 비영리 InnovateUS의 첫 보고서 내용을 연구진 기고(POV)로 실었다. 2024년 6월~2026년 5월 입문 과정 사전 설문 106,300건·사후 설문 67,002건을 분석한 결과 수강생의 51%는 생성형 AI를 써 본 적이 없었고, 쓰지 않은 이유로 '업무와 무관'(28%), '사용법을 모름'(23%), '써도 되는지 모름'(19%)을 꼽았다(비사용 관리자도 22%가 허용 여부를 몰랐다). 주된 사용처는 보고서 초안, 발표자료 작성, 문서 요약이었고, 교육 뒤 자신감이 높은 사람은 평균 3.8개, 낮은 사람은 1.5개 업무에 AI를 쓰겠다고 했다. 연구진은 도구·정책만으로는 부족하고 업무에 맞는 예시·연습 기회·준비된 관리자가 필요하다고 했으며, 비교군이 없고 자기 보고 기반이라는 한계도 밝혔다.","eSum":"In an October 26, 2026 POV article in Fast Company, researchers presented the first report from InnovateUS, a nonprofit that has trained more than 250,000 US state and local government workers in AI and digital skills. Based on 106,300 pre-course and 67,002 post-course survey responses from an introductory generative AI course collected between June 2024 and May 2026, 51% of entering learners had never tried generative AI, and non-users cited the tools not applying to their work (28%), not knowing how to use them (23%) and not knowing whether they were allowed (19%); 22% of non-using managers also did not know whether it was permitted. The most common uses were drafting reports, creating presentations and summarizing documents, and after training, highly confident respondents planned to use AI for 3.8 tasks on average versus 1.5 for low-confidence ones. The authors say access to tools and policies is not enough without relevant examples, practice and prepared managers, and note that the data lack a comparison group and rely on self-reports.","kImp":"비사용자 다섯 명 중 한 명꼴이 '써도 되는지 몰라서' AI를 안 쓴다는 점에서, 육상 조직도 허용 도구와 입력 금지 정보(개인정보·계약 자료 등)를 한 장짜리 지침으로 먼저 알리고, 보고서·요약처럼 바로 쓸 수 있는 업무 예시로 실습하는 교육을 여는 것이 효과적이다.","eImp":"Since about one in five non-users held back because they did not know whether AI was allowed, shore organizations should first issue a one-page guide on approved tools and information that must not be entered, such as personal data and contract documents, and run hands-on sessions built around ready examples like reports and summaries.","url":"https://www.fastcompany.com/91628634/how-the-public-sector-is-using-ai","prio":2,"kor":false,"tags":["AI","TRN","CHG"],"tool":""},{"code":"INNOV","date":"2026-10-24","src":"이투데이","title":"직능연 \"AI로 효율 오른 업무, 정보 검색 33.4% vs 기획 1.4%\"…회사가 일방적으로 도입하면 만족도 87.9%로 뚝","eTitle":"Korea's Vocational Research Institute Finds AI Gains Concentrated in Information Search (33.4%) Rather Than Planning (1.4%), With Satisfaction Dropping to 87.9% When Firms Impose AI Top-Down","kSum":"한국직업능력연구원이 2026년 7월 4~17일 생성형 AI를 써 본 국내 기업 직원 1,090명을 조사하고 대기업 7곳 HR·AX 담당자를 면담한 보고서 '생성형 AI 시대의 직무재설계와 혁신 방안'에 따르면, AI로 효율이 가장 오른 업무는 정보 검색·수집(33.4%), 긴 글 요약(22.4%), 자료 정리·기초 분석(15.1%) 순이었고 새 아이디어·기획 제안은 1.4%, 일정 계획은 1.0%에 그쳤다. 개인이 주도해 도입한 경우 만족도는 96.3%, 노사 협의를 거친 경우 95.9%였지만 회사 주도로 일방 도입한 경우 87.9%였고, 불만 사유 1위도 '일방적·하향식 도입'(51.3%)이었다. 개인 성과가 올랐다는 응답(76.0%)에 비해 조직 성과 기여 응답(72.6%)은 낮았다.","eSum":"A report by the Korea Research Institute for Vocational Education and Training, based on a 4-17 July 2026 survey of 1,090 employees who had used generative AI and interviews with HR and AI-transformation staff at seven large firms, found the biggest efficiency gains in information search (33.4%), summarising long texts (22.4%) and organising data (15.1%), against 1.4% for new ideas or planning and 1.0% for scheduling. Satisfaction was 96.3% where individuals led adoption and 95.9% where it was agreed with staff, but 87.9% where the company imposed it, and top-down rollout was the leading complaint (51.3%). Perceived personal gains (76.0%) outran perceived contribution to organisational results (72.6%).","kImp":"AI는 자료 찾기·요약·정리 업무부터 맡기고 기획·대외 소통·최종 판단은 사람이 맡는다는 역할 분담을 팀에서 먼저 정하며, 도입은 위에서 지시하기보다 직원 의견을 듣고 시범 팀부터 시작하는 편이 정착에 유리하다.","eImp":"Teams can agree a split in which AI handles searching, summarising and organising material while people keep planning, external communication and final judgement, and rollouts tend to stick better when staff are consulted and a pilot team goes first rather than by top-down instruction.","url":"https://www.etoday.co.kr/news/view/2639400","prio":3,"kor":true,"tags":["AI","WR","CHG"],"tool":""},{"code":"INNOV","date":"2026-10-23","src":"HR Insight","title":"AI가 만든 ‘워크슬롭’이 동료 시간을 빼앗는다 — “30분 만에 끝낸 일이 남의 한두 시간을 쓰면 업무 전가”, 완료 기준 4가지와 위험도별 차등 검토 제시","eTitle":"AI 'Workslop' Steals Colleagues' Time: Four Completion Criteria and Risk-Tiered Review for AI-Assisted Work","kSum":"송영선 건국대 교수는 생성형 AI 결과물을 충분히 검토하지 않고 넘겨 받는 사람이 사실 확인과 수정을 떠안는 '워크슬롭'이 개인 작업시간은 줄이지만 조직 전체 작업시간은 늘린다며, 30분 만에 끝낸 일이 동료의 한두 시간을 빼앗는다면 효율화가 아니라 업무 전가라고 지적했다. 완료 기준으로 핵심 사실·수치·인용을 사람이 확인했는지, 조직 상황에 맞게 고쳤는지, 받는 사람이 추가 작업 없이 쓸 수 있는지, 최종 검토자·책임자가 명확한지의 4가지를 제시했다. 내부 메모는 자기 검토로 충분하지만 경영진 보고·인사 결정·고객 자료는 엄격히 검증하는 위험도별 차등 검토를 권하고, 리더가 'AI를 얼마나 썼나' 대신 '바로 쓸 수 있나'를 물어야 하며 'AI 작성 참고용' 문구를 면책 수단으로 쓰지 말라고 강조했다.","eSum":"Konkuk University professor Song Young-sun warns that unchecked generative-AI output ('workslop') shifts fact-checking and rework onto recipients, cutting individual time while raising total organisational time; a task finished in 30 minutes that costs a colleague one or two hours is a transfer of work, not efficiency. He proposes four completion criteria: people have verified key facts, figures and citations, the output has been adapted to the organisation's context, the recipient can use it without extra work, and a final reviewer and owner are named. Review should be tiered by risk, light for internal memos but rigorous for executive reports, HR decisions and client material, leaders should ask whether work is usable rather than how much AI was used, and an 'AI-generated, for reference only' label should never excuse poor work.","kImp":"AI로 초안을 쓴 보고서·회의자료·메일을 넘길 때 '받는 사람이 추가 작업 없이 쓸 수 있는가'와 최종 검토 책임자를 밝히는 팀 규칙을 두고, 경영진 보고·인사 관련 문서·외부 발송 자료는 사실·수치 검증을 필수로 해 볼 만하다. 팀장도 'AI를 얼마나 썼나' 대신 '바로 쓸 수 있나'를 물어야 한다.","eImp":"Teams could adopt a rule that any AI-drafted report, meeting pack or email handed on must be usable without rework and must name a final reviewer, with mandatory fact and figure checks for executive reports, HR documents and anything sent outside the company. Team leaders should ask whether work is ready to use, not how much AI went into it.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=112&bi_pidx=39672","prio":2,"kor":true,"tags":["AI","WRT","WR"],"tool":""},{"code":"INNOV","date":"2026-10-23","src":"HR Dive","title":"가트너 CIO 2,002명 조사: '사람+AI 에이전트' 조직에 맞춘 역할 재설계 계획 4%뿐…AI 투자로 큰 가치 얻었다는 CIO 13%","eTitle":"Gartner survey of 2,002 CIOs: only 4% have plans to redesign roles for a human-agent workforce, and 13% report significant AI value","kSum":"HR 다이브는 2026년 10월 23일(CIO 다이브 원문), 가트너가 10월 19일 발표한 '2027 CIO·기술 임원 어젠다' 조사(CIO·기술 임원 2,002명)를 보도했다. 사람과 AI 에이전트가 함께 일하는 조직에 맞춰 역할을 재설계할 계획을 세운 CIO는 4%뿐이었지만, 그런 계획이 있는 기업은 AI 상위 성과 기업이 되고 CEO가 AI 가치를 인정할 가능성이 2.4배 높았다. AI 투자에서 상당하거나 변혁적인 가치를 얻었다는 CIO는 13%에 그쳤고, 58%는 회사가 이전 AI 투자에서 비용 개선을 요구하고 있다고 답했다. 가트너 애널리스트 앨리샤 멀러리는 비용 압박이 인력 문제를 가리고 있다며, 에이전트를 다룰 인력과 거버넌스를 준비하지 않으면 팀이 성과를 내지 못해 결국 비용이 생긴다고 경고했다.","eSum":"HR Dive reported on October 23, 2026, in a story first published by CIO Dive, on Gartner's 2027 CIO and Technology Executive Agenda survey of 2,002 CIOs and technology executives, announced October 19. Only 4% of CIOs have plans in place to revamp roles for a human-agent workforce, yet enterprises with such plans are 2.4 times more likely to be AI top performers and to have CEOs report AI value. Only 13% of CIOs report significant or transformational value from their AI investments, and 58% say their companies are demanding cost improvements from earlier AI investments. Gartner analyst Alicia Mullery said cost pressures can overshadow talent concerns and warned that companies without a workforce and governance prepared for AI agents will face costs because teams cannot deliver effectively.","kImp":"AI 도구 도입 계획에는 '어떤 일을 사람이 맡고 어떤 일을 AI에 넘길지, 그에 따라 직무 설명을 어떻게 고칠지'가 함께 들어가야 효과가 나므로, 부서별 업무 목록을 놓고 사람·AI 역할 분담표를 만들어 보는 것부터 시작할 만하다.","eImp":"Since results depend on pairing AI tool plans with decisions on which work stays with people, which goes to AI and how job descriptions change, a practical start is to draw up a people-and-AI task split for each department's task list.","url":"https://www.hrdive.com/news/gartner-survey-CIOs-workforce-revamp/833823/","prio":1,"kor":false,"tags":["AI","CHG"],"tool":""},{"code":"INNOV","date":"2026-10-22","src":"HR Insight","title":"“조직의 기록이 AI의 신뢰를 결정한다” — 사내 문서 RAG의 환각은 맥락 빠진 기록 탓, 작성률 점검 대신 심리적 안전에 기반한 기록 문화 필요","eTitle":"Organisational Records Determine Whether AI Can Be Trusted: Hallucinations Trace Back to Context-Poor Records, and Record Quality Rests on Psychological Safety","kSum":"미디어젠 AI전략기획팀 안영규 매니저는 사내 원문을 상용 모델에 RAG로 연결한 HR AX 사례에서 환각이 적지 않았던 원인이 '적극 참여해 좋은 성과를 냄'처럼 구체 과업이 없는 피드백, 누가 왜 결정을 미뤘는지 빠진 회의록 같은 기록의 결함이라고 짚었다. 구글 리서치의 AI 실무자 53명 인터뷰에서 92%가 기록 단계의 작은 결함이 최종 단계의 큰 오류로 번지는 '데이터 캐스케이드'를 겪었다며, 무슨 일이 있었는지·무엇을 결정했는지·근거·남은 과제를 나누고 작성자 해석을 사실과 분리해 적자고 제안했다. 작성률 점검 같은 강제는 기록 피로와 의도적 누락을 부르고, 에이미 에드먼슨의 간호팀 연구에서 관계와 리더십이 좋은 팀일수록 투약 오류가 더 많이 보고된 것은 실수를 드러내도 괜찮다는 신뢰 때문이라고 설명했다(구독 기사로 후반부는 비공개).","eSum":"Ahn Young-kyu of Mediazen's AI strategy team traces frequent hallucinations in an HR AI project that linked internal documents to a commercial model via RAG to defective records, such as feedback with no concrete tasks and meeting minutes that omit who deferred a decision and why. Citing a Google Research study in which 92% of 53 AI practitioners had seen small recording flaws cascade into large downstream errors, he urges records that separate what happened, what was decided, the rationale, what remains open and the writer's own interpretation. He warns that policing completion rates breeds record fatigue and deliberate omissions, and cites Amy Edmondson's finding that nursing teams with better relationships and leadership reported more medication errors because people felt safe to disclose them (subscriber article; the later part is not public).","kImp":"사내 문서를 AI 검색에 연결하기 전에 회의록과 업무 기록 양식부터 '사실·결정·근거·미결 사항·작성자 의견'을 나눠 적게 바꾸고, 작성 건수 점검보다 내용의 구체성을 피드백하는 방식으로 운영해 볼 만하다. 실수나 지연 이유를 솔직히 적어도 불이익이 없다는 신뢰가 있어야 기록의 질이 올라간다.","eImp":"Before connecting internal documents to AI search, revise meeting-minute and work-record templates so writers separate facts, decisions, rationale, open items and their own opinions, and give feedback on specificity rather than policing completion counts. Record quality rises only when people trust that honestly noting mistakes or reasons for delay will not be held against them.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39677","prio":2,"kor":true,"tags":["AI","WRT","PS"],"tool":""},{"code":"INNOV","date":"2026-10-22","src":"TechCrunch","title":"우버, 전 직원 3만 명에 'ChatGPT Work' 도입…1천 명 시범 사용자 80%가 비개발자","eTitle":"Uber puts all 30,000 employees on ChatGPT Work after a 1,000-person pilot led by non-engineers","kSum":"테크크런치는 2026년 10월 22일, 우버가 오픈AI와 협력을 넓혀 전 세계 약 3만 명의 전 직원에게 기업용 AI 에이전트 'ChatGPT Work'(7월 출시)를 쓰게 한다고 보도했다. 우버는 올해 초 재무·운영·제품 등 여러 부서 직원 1,000명으로 시범 운영했고 초기 사용자의 약 80%가 비개발자였으며, 운영 데이터 분석과 추세·권고안 도출, 시장·언어별 교육 자료 현지화, 개인 맞춤 대시보드 제작 등에 썼다. 앞서 AI 엔지니어 30명을 2주간 현업 팀에 붙여 업무 일부를 자동화하는 'AI 포드'도 운영했다. 비용은 공개하지 않았고 구체적 사용 지침도 아직 정하지 않았으며, 사용 현황과 성과를 추적해 이후 배치에 반영하겠다고 밝혔다.","eSum":"TechCrunch reported on October 22, 2026, that Uber is expanding its partnership with OpenAI and giving its entire global workforce of some 30,000 people access to ChatGPT Work, the enterprise AI agent OpenAI introduced in July. Uber piloted it earlier in the year with 1,000 employees from finance, operations, product and other departments, about 80% of them non-engineers, who used it to analyze operational data, localize training materials and build personalized dashboards. Uber also ran 'AI pods' that paired 30 AI engineers with teams for two weeks to automate parts of their jobs. It did not disclose the cost, has not settled on usage guidelines, and plans to track usage and outcomes to guide further deployment.","kImp":"AI 도구를 전사에 들이기 전 여러 부서의 비개발자 위주 시범 그룹이 실제 업무(데이터 분석·교육 자료·보고 대시보드)에 써 보게 하고, 사용 현황과 성과를 측정한 뒤 확대 범위와 지침을 정하는 단계적 방식을 참고할 만하다.","eImp":"Before a company-wide AI rollout, consider this staged approach: let a cross-department pilot group made up mostly of non-engineers use the tool on real work such as data analysis, training materials and reporting dashboards, measure usage and outcomes, then set the scope and guidelines for expansion.","url":"https://techcrunch.com/2026/10/22/uber-puts-all-30000-employees-on-chatgpt-work/","prio":2,"kor":false,"tags":["AI","CHG"],"tool":"ChatGPT Work"},{"code":"INNOV","date":"2026-10-22","src":"HR Insight","title":"\"AI 도구만 깔면 성과 안 난다\"…맥킨지 조사서 고성과 기업과 일반 기업 격차 가장 큰 건 '워크플로 재설계'(48%p), MS는 업무 흐름 다시 짜 거래 체결률 20%↑","eTitle":"Work Redesign 2.0: McKinsey Data Show Workflow Redesign Is the Widest Gap Between AI High Performers and Others (48 Points), and Microsoft Raised Sales Close Rates 20% After Redesigning Work Around Goals","kSum":"동국대 이중학 교수는 HR Insight 11월호 기고에서 AI가 개인 생산성은 높였지만 기업 재무 성과로 이어지지 않는 이유를 업무 흐름 전체를 다시 짜지 않았기 때문이라고 짚었다. 그가 인용한 맥킨지 조사(97개국 1,719명)에서 AI가 영업이익에 조금이라도 기여했다는 응답은 37%로 작년과 거의 같았고, 11개 AI 실천 항목 중 고성과 기업과 나머지의 격차가 가장 큰 것은 워크플로 재설계(48%p)였다. 마이크로소프트는 20만 명 넘는 직원에게 AI 도구를 줬지만 사용이 정체되자 영업 담당자의 한 주 업무를 먼저 분석해 영향이 큰 지점에 에이전트를 배치했고, 영업 현장의 AI 에이전트 활용 사례 채택률은 3배, 거래 체결률은 20% 올랐다고 소개했다. 필자는 도구 선택 전 실제 업무 흐름 분석, 기존 절차 단순화, 데이터 통일, 목적별 에이전트 배치, 접근 범위·승인 기준·사람 개입 지점 정의를 순서로 제시했다. (구독 기사, 공개된 앞부분 기준)","eSum":"In HR Insight's November issue, Dongguk University professor Lee Joong-hak argues that AI has lifted individual productivity without improving company financial results because firms have not redesigned whole workflows. He cites a McKinsey survey of 1,719 respondents in 97 countries in which 37% said AI contributed at least somewhat to operating profit, about the same as last year, and workflow redesign showed the widest gap (48 points) between high performers and others among 11 practices. Microsoft gave AI tools to more than 200,000 staff but saw usage plateau, then analysed what account managers did in a typical week and placed agents at high-impact points, tripling adoption of AI-agent use cases in sales and lifting deal closure rates by 20%. He proposes analysing real workflows before choosing tools, simplifying processes, aligning data, deploying purpose-built agents and defining access, approval and human checkpoints.","kImp":"팀에서 AI 활용을 늘리려면 도구부터 고르기보다 '보고서 취합→검토→승인'처럼 반복되는 업무 하나의 흐름을 먼저 그려 보고, 불필요한 단계를 줄인 뒤 AI를 넣을 지점과 사람이 꼭 확인할 지점을 함께 정하는 것이 좋다.","eImp":"To get more from AI, a team can map one recurring workflow such as collating, reviewing and approving a report before choosing any tool, cut unnecessary steps, then decide both where AI goes in and where a person must check.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=112&bi_pidx=39670","prio":2,"kor":true,"tags":["AI","WR","CHG"],"tool":""},{"code":"INNOV","date":"2026-10-22","src":"Harvard Business Review","title":"HBR: 직원들의 AI 양가감정을 다뤄야…우려를 인정하고 실험 공간을 만들며, AI로 얻은 여유를 어디에 쓸지 투명하게","eTitle":"HBR: Leaders need to grapple with employee ambivalence on AI by acknowledging concerns and being transparent about reinvesting gains","kSum":"하버드비즈니스리뷰는 2026년 10월 22일, 『No Hard Feelings』 공저자 리즈 포슬리언(아틀라시안)·몰리 웨스트 더피와 『Radical Candor』 저자 킴 스콧의 글을 실었다. 필자들은 갤럽 연구 등을 인용해 AI를 걱정하는 직원은 몰입도가 낮고 번아웃에 취약하며 직무 만족이 떨어지고, AI 도구를 피하거나 우회해 조직의 투자 효과를 깎는다고 지적했다. 리더에게는 직원의 우려를 먼저 인정하고, 안전하게 실험하고 배울 공간을 만들며, AI로 생긴 성과를 어디에 다시 투자할지 투명하게 밝히고, 새 기술을 익히고 실험하며 더 의미 있는 일에 집중할 시간을 주라고 권했다. (구독 기사, 공개된 앞부분 기준)","eSum":"In an October 22, 2026 Harvard Business Review article, Liz Fosslien of Atlassian and Mollie West Duffy, coauthors of No Hard Feelings, and Kim Scott, author of Radical Candor, argue that leaders must address employees' mixed feelings about AI. Citing Gallup and other research, they note that workers who worry about AI tend to be less engaged, more prone to burnout and less satisfied, and may avoid or work around AI tools, reducing the value of the investment. They recommend acknowledging employees' concerns, creating a safe space for experimentation and learning, being transparent about how AI-driven gains will be reinvested, and giving people time to build new skills, experiment and focus on more meaningful work. (Subscription article; based on the publicly visible opening.)","kImp":"AI 도입을 알릴 때 '무엇이 자동화되는가'만이 아니라 '줄어든 시간을 무엇에 쓰게 될지'를 팀에 함께 설명하고, 팀 회의에 AI에 대한 걱정을 터놓는 시간을 따로 두는 것이 저항을 줄이는 데 도움이 된다.","eImp":"When introducing AI, explain to the team not only what will be automated but also what the freed-up time will be used for, and set aside time in team meetings for people to voice their concerns about AI.","url":"https://hbr.org/2026/10/leaders-need-to-grapple-with-employee-ambivalence-on-ai","prio":1,"kor":false,"tags":["AI","CHG","PS"],"tool":""},{"code":"INNOV","date":"2026-10-21","src":"Harvard Business Review","title":"HBR \"막기만 하는 보안 규정은 역효과\" — 6개 실험·2,800명 \"강요된 통제가 위험 인식을 낮춘다\"","eTitle":"When Restrictive Cybersecurity Policies Backfire","kSum":"듀크대 푸쿠아 경영대학원의 애런 케이 교수와 보안업체 Nudge Security 공동창업자 등은 2,800명 이상이 참여한 6개 실험에서, 강요된 사이버보안 통제가 반발심을 불러 직원들이 디지털 위협을 덜 심각하게 여기게 만든다는 결과를 얻었다. 제한을 풀면 원래 위험이 과장됐다는 신호로 읽히는 문제도 확인됐다. 필자들은 생성형 AI 같은 유용한 앱은 금지해도 사용이 멈추지 않고 눈에 덜 띄게 계속된다고 지적한다. 이들은 보안 요건 안에서 의미 있는 선택권을 남기고, 쓸 만한 승인 도구를 제공하며, 위험과 정책 변경 이유를 설명하고, 준수율과 함께 직원의 위험 인식도 측정하라고 권한다.","eSum":"In six experiments with more than 2,800 participants, Duke Fuqua professor Aaron Kay and co-authors including the co-founder of security firm Nudge Security found that imposed cybersecurity controls can provoke resistance that leads employees to downplay digital threats. Lifting restrictions can also signal that the original danger was exaggerated. The authors note that useful tools such as generative AI apps are not abandoned when banned; employees often keep using them less visibly. They recommend preserving meaningful choice within security requirements, providing useful approved tools, explaining risks and the reasons for policy changes, and measuring employees' beliefs alongside compliance.","kImp":"생성형 AI·외부 파일 공유·개인 메신저 사용을 일괄 금지만 하면 직원들이 위험을 가볍게 여기고 눈에 띄지 않게 우회하기 쉽다. 사내 보안 규정을 고칠 때 금지 이유와 승인된 대체 도구를 함께 안내하고, 준수율 점검과 별도로 직원이 위험을 어떻게 인식하는지 짧은 설문으로 확인해 볼 만하다.","eImp":"Blanket bans on generative AI, external file sharing or personal messaging apps tend to make staff downplay the risk and work around the rules out of sight. When revising office security rules, explain each restriction alongside an approved alternative tool, and run a short survey on how staff perceive the risk in addition to compliance checks.","url":"https://hbr.org/2026/10/when-restrictive-cybersecurity-policies-backfire","prio":2,"kor":false,"tags":["SEC","CHG","AI"],"tool":""},{"code":"INNOV","date":"2026-10-21","src":"TechCrunch","title":"관리자 1,700명 조사: 절반 이상 'AI 도입 뒤 직원 업무 평가 더 어려워'…58% '1년 안에 사람보다 AI 에이전트를 더 많이 관리'","eTitle":"Survey of 1,700 managers: more than half find employee work harder to evaluate after AI, and 58% expect to oversee more agents than people within a year","kSum":"테크크런치는 2026년 10월 21일, 업무관리 기업 먼데이닷컴(Monday.com)이 닐슨에 의뢰해 7개국 이사·고위 관리자 1,700명을 조사한 결과를 보도했다. 응답자 절반 이상이 AI 도입 뒤 직원 업무를 평가하기 더 어려워졌다고 했고, 절반 가까이는 팀 결과물을 검토·지도하는 시간이 늘었다고 답했다. 78%는 평가 기준을 바꿔 프롬프트 작성 능력·위임 판단·새 업무 방식 실험에 더 비중을 두고 있으며, 46%는 의사결정에, 39%는 인사평가 초안 작성에 AI를 쓴다고 했다. 57%는 쓰는 도구가 늘었다고 했고 AI 인프라가 완전히 최적화·중앙화됐다는 응답은 29%에 그쳤으며, 58%는 1년 안에 사람보다 AI 에이전트를 더 많이 관리하게 될 것으로 봤고 35%는 AI가 내린 결정의 책임을 지게 될까 우려했다.","eSum":"TechCrunch reported on October 21, 2026, on a survey of 1,700 directors and senior managers in seven countries, conducted by Nielsen for work-management company Monday.com. More than half said it has become harder to evaluate employees' work since adopting AI, and nearly half said they spend more time reviewing and guiding team output. 78% have changed how they evaluate employees, giving more weight to prompting skill, delegation decisions and experimenting with new ways of working, while 46% use AI to inform decisions and 39% use it to draft performance reviews. 57% say more tools are in circulation, only 29% call their AI infrastructure fully optimized and centralized, 58% expect to oversee more AI agents than people within a year, and 35% fear being held responsible for decisions made by AI.","kImp":"팀원들이 AI로 문서·분석을 만들기 시작했다면 팀장은 결과물과 함께 '무엇을 AI에 맡기고 무엇을 직접 확인했는지'를 보고하게 하고, 팀에서 쓰는 AI 도구 목록과 검토 책임자를 정리해 두는 것이 좋다.","eImp":"Once team members produce documents and analyses with AI, managers should ask them to report what they delegated to AI and what they checked themselves along with the output, and keep a list of the AI tools the team uses and who is accountable for reviewing their results.","url":"https://techcrunch.com/2026/10/21/ai-promises-productivity-but-for-managers-its-mostly-a-headache-for-now-says-new-survey/","prio":2,"kor":false,"tags":["AI","PERF","LDR"],"tool":""},{"code":"INNOV","date":"2026-10-16","src":"Anthropic","title":"앤트로픽 사내 데이터 보고서: 에이전트 작업시간이 사람을 추월…'사람의 주의력이 병목', 회의 시간은 20% 늘어","eTitle":"Anthropic's internal data report: agent work hours overtook human hours, human attention became the bottleneck and meeting time rose 20%","kSum":"앤트로픽 경제연구팀은 2026년 10월 16일 사내 고용·AI 사용·산출물·설문·슬랙·일정 데이터로 AI 에이전트가 회사 안의 일을 어떻게 바꿨는지 분석한 보고서를 냈다. 2026년 3월 에이전트의 작업시간 합계가 처음으로 사람의 근무시간을 넘었고 8월에는 직원 한 명의 에이전트들이 사람보다 약 6배 긴 시간을 일했지만, 대화형 세션 시간의 약 80%는 사람의 입력을 기다리는 시간이었고 비기술 부서가 에이전트 결과물을 모두 읽으려면 주 근무시간의 절반 이상이 필요한 것으로 나타났다. 스킬·지침·검토 같은 '일을 위한 일'의 비중은 대화 세션의 10%에서 22%로 늘었고, 직원 중위 회의 시간은 1년 새 20% 증가했으며 부서 간 내부 이동은 50% 늘었다. 연구진은 사람의 판단을 공개 채널에 기록해 에이전트가 맥락을 갖게 하라고 했지만, 도입이 무작위가 아니어서 생산성 추정에 선택 편향이 섞였을 수 있고 다른 조직에 그대로 적용되지 않을 수 있다고 밝혔다.","eSum":"On October 16, 2026, Anthropic's economics team published a report using internal data on employment, AI use, output, surveys, Slack and calendars to show how AI agents changed work inside the company. In March 2026 combined agent work hours surpassed human work hours for the first time, and by August each employee's agents worked about six times as many hours as their human handlers, yet about 80% of interactive session time was spent idle waiting for human input, and reading all agent output would take non-technical groups over half their work week. Meta-work such as building skills, specs and agent reviews rose from 10% to 22% of interactive sessions, median meeting time rose 20% year over year, and internal transfers across departments rose 50%. The authors recommend keeping human decisions documented in open channels so agents have context, but caution that adoption was not random, so productivity estimates may reflect selection, and that many practices may not transfer to other organizations.","kImp":"AI가 초안을 빨리 만들수록 사람이 읽고 검토하는 시간이 병목이 된다는 점에서, 팀은 AI 결과물을 누가·어느 수준까지 검토할지 정하고, 중요한 결정은 메일·채팅 속에만 두지 말고 공유 문서에 남겨 사람과 AI 모두 같은 맥락을 보도록 하는 것이 좋다.","eImp":"As AI produces drafts faster, the time people need to read and review becomes the bottleneck, so teams should decide who reviews AI output and how deeply, and record important decisions in shared documents rather than leaving them in email or chat, so that people and AI work from the same context.","url":"https://www.anthropic.com/research/employment-at-anthropic","prio":1,"kor":false,"tags":["AI","WR","MTG"],"tool":""},{"code":"INNOV","date":"2026-10-13","src":"Atlassian (Teamwork Lab)","title":"아틀라시안 조사: AI 사용자 40% '사용량 감시·제한 겪어'…49%는 자신이 쓰는 AI 도구 비용을 몰라","eTitle":"Atlassian survey: 40% of AI users were asked to watch or justify usage, and 49% do not know what their AI tools cost","kSum":"아틀라시안 팀워크 랩은 2026년 10월 13일, 8월 25~28일 미국 정규직 지식노동자 1,008명을 조사한 결과를 공개했다. AI 사용자의 40%는 최근 3개월 사이 사용량을 지켜보거나 정당화하라는 요구를 받았거나 사용 한도·접근 차단·저가 도구 전환 같은 제한을 겪었다고 답했지만, 회사가 AI 투자를 유지(48%)하거나 확대(36%)한다는 응답이 84%로 축소(3%)를 크게 웃돌았다. 49%는 자신이 쓰는 AI 도구에 회사가 얼마를 내는지 모르거나 확신하지 못했고(비용을 아는 비율은 리더 67%, 관리자 37%, 일반 직원 22%), 46%는 '덜 쓰는 것' 말고는 비용을 줄이는 방법을 모른다고 했다. AI가 비용값을 하게 만드는 요인으로 도구(42%)와 사용자가 주는 맥락(41%)을 꼽은 비율이 모델(13%)보다 높았고, 별도 연구에서는 업무 맥락을 이해하는 AI를 쓴 직원이 도움을 느낄 가능성이 최대 6배, 고칠 필요 없는 결과물이 최대 48% 많았다.","eSum":"On October 13, 2026, Atlassian's Teamwork Lab published a survey of 1,008 full-time US knowledge workers conducted August 25 to 28, 2026. 40% of AI users said that in the past three months they had been asked to watch or justify their usage or had hit a hard limit such as a usage cap, lost access or a switch to a cheaper tool, yet 84% said their company is holding steady (48%) or going all-in (36%) on AI, against 3% reporting a pullback. 49% do not know or are unsure what their company pays for the AI tools they use (67% of leaders, 37% of managers and 22% of individual contributors know), and 46% do not know how to lower costs other than using AI less. Respondents credited the tool (42%) and the context they provide (41%) far more than the model (13%) for making AI worth its cost, and a separate Teamwork Lab study found workers whose AI understood their work were up to 6 times more likely to find it helpful and got up to 48% more output usable without rework.","kImp":"AI 비용을 줄이려고 '아껴 쓰라'는 지시만 내리기보다, 팀원에게 사용 비용을 보여 주고 일상 질문은 가벼운 도구로, 복잡한 작업은 상위 도구로 나눠 쓰는 기준을 정하며, 템플릿·지침·과거 문서 같은 업무 배경 자료를 잘 정리해 AI에 주는 방법을 알려 주는 편이 효과적이다.","eImp":"Rather than simply telling staff to use AI sparingly, show them what their usage costs, set a rule of lighter tools for everyday questions and stronger tools for complex work, and teach them to give AI well-organized background material such as templates, guidelines and past documents.","url":"https://www.atlassian.com/blog/ai-at-work/the-smartest-way-to-cut-ai-costs-isnt-to-use-less-ai","prio":2,"kor":false,"tags":["AI","DATA"],"tool":""},{"code":"INNOV","date":"2026-10-06","src":"Gallup","title":"갤럽 1만7천여 명 조사: 업무에 AI 주 1회 이상 쓰는 직원 28%…효과는 관리자·대졸자·자주 쓰는 사람에 집중","eTitle":"Gallup: 28% of US employees use AI at work weekly, and the benefits concentrate among managers, graduates and regular users","kSum":"갤럽은 2026년 10월 6일 미국 직무 질 연구(American Job Quality Study) 2년 차 첫 결과를 발표했다(2026년 1~3월, 미국 근로자 17,874명 조사). 주 1회 이상 업무에 AI를 쓰는 직원은 28%였고 54%는 업무에 AI를 써 본 적이 없었으며, 관리자(37%)가 일반 직원(25%)보다, 대졸자(40%)가 비대졸자(17%)보다 정기 사용 비율이 높았다. AI 사용자들은 일이 빨라졌다(63%), 더 창의적인 해법을 찾는다(56%), 흥미로운 업무에 시간을 더 쓴다(47%), 품질이 높아졌다(46%)고 답했고, 정기 사용자는 '빨라졌다'가 79%로 가끔 쓰는 사람(38%)의 두 배를 넘었다. 31%는 AI 때문에 회사가 더 많은 책임을 맡겼다고 했고(18~24세는 38%), 전체 직원의 52%는 새 기술 도입에 대한 자신의 영향력이 원하는 수준보다 적다고 답했다.","eSum":"On October 6, 2026, Gallup released first results from the second year of the American Job Quality Study, based on 17,874 US workers surveyed from January to March 2026. 28% of employees use AI at work at least weekly and 54% have never used it in their role, with regular use higher among managers (37%) than individual contributors (25%) and among college graduates (40%) than non-graduates (17%). AI users report faster work (63%), more creative solutions (56%), more time on interesting work (47%) and higher-quality work (46%), and regular users are far more likely than occasional users to say AI makes them faster (79% vs. 38%). 31% say AI has led their employer to give them more responsibilities (38% among those aged 18 to 24), and 52% of all employees say they have less influence over new technology adoption than they would like.","kImp":"AI 효과가 자주 쓰는 사람에게 몰린다는 결과이므로, '가끔 써 보는' 수준에 머문 팀원에게 반복 업무 한두 가지를 정해 매주 AI로 처리해 보게 하고, 도구를 고를 때 실무자 의견을 듣는 절차를 두는 것이 좋다; AI로 생긴 여유가 업무 추가로만 이어지지 않는지도 살펴야 한다.","eImp":"Because the benefits concentrate among regular users, managers could help occasional users pick one or two recurring tasks to do with AI every week and give staff a say when tools are chosen; they should also watch that time saved by AI does not simply turn into extra duties.","url":"https://news.gallup.com/poll/714602/benefits-work-unevenly-distributed.aspx","prio":3,"kor":false,"tags":["AI","CHG","WR"],"tool":""},{"code":"INNOV","date":"2026-09-16","src":"SHRM","title":"SHRM \"변화 속에서 신뢰를 주는 리더 행동 9가지\" — 이유 설명, 답이 없어도 정기 공유, 같은 규칙 따르기","eTitle":"9 Leadership Behaviors That Inspire Confidence During Change","kSum":"SHRM 인도판은 성장과 디지털 전환기에 직원이 변화를 믿고 따르게 만드는 리더 행동 9가지를 제시했다. 직원 관점에서 변화 이유 설명, 모든 답이 없어도 정기적으로 업데이트, 우려를 듣고 솔직하게 답하기, 목표와 일정에 현실적 기대치 설정, 중간 관리자가 수시로 안내·지원하도록 준비시키기, 잘 적응한 직원 인정, 새 기술 학습 기회 제공, 일관된 결정과 근거 설명, 리더 스스로 같은 규칙 따르기다. 어려운 대화를 피하지 않고 과제를 인정하며 현실적인 계획을 내놓는 리더가 직원의 신뢰를 얻을 가능성이 높다고 강조했다.","eSum":"SHRM India lists nine leader behaviors that help employees feel confident during growth and digital transformation: explaining the reasons for change from employees' perspective, giving regular updates even without all the answers, listening to concerns and answering honestly, setting realistic expectations for goals and timelines, equipping managers to give frequent guidance, recognizing people who adapt, offering chances to learn new skills, making consistent decisions with explained reasoning, and following the same rules as everyone else. Leaders who name challenges and present realistic plans, rather than avoiding difficult conversations, are more likely to win employees' trust.","kImp":"새 시스템이나 업무 절차를 도입할 때 공지 메일 한 통으로 끝내지 말고 '왜 바꾸는지'를 직원 입장에서 설명하고, 아직 정해지지 않은 부분도 2주마다처럼 정해진 주기로 진행 상황을 알려 주는 것이 정착을 돕는다. 경영진과 팀장부터 새 규칙을 똑같이 지키는지 점검하는 것도 신뢰를 얻는 조건이다.","eImp":"When rolling out a new system or work procedure, go beyond a single announcement email: explain from employees' point of view why it is changing and give progress updates on a fixed rhythm, such as every two weeks, even on open questions. Making sure executives and team leaders follow the new rules themselves is part of earning trust.","url":"https://www.shrm.org/in/topics-tools/news/blogs/leadership-behaviors-inspiring-confidence-change","prio":1,"kor":false,"tags":["CHG","LDR"],"tool":""},{"code":"INNOV","date":"2026-05-05","src":"Microsoft WorkLab","title":"MS 2026 업무동향지수: AI 성과 좌우 신호의 67%는 조직 요인(문화·관리자·인사제도)…'리더 AI 방향 일치' 26%뿐","eTitle":"Microsoft 2026 Work Trend Index: organizational factors account for 67% of the AI-impact signal, and only 26% say leaders are aligned on AI","kSum":"마이크로소프트는 2026년 5월 5일 '2026 업무동향지수(Work Trend Index)' 연례 보고서를 내고, 10개국 AI 사용 지식노동자 2만 명 조사(2026년 2~4월, 에델만 데이터 수행)와 마이크로소프트 365 사용 신호를 분석했다. AI 성과를 설명하는 신호의 67%가 조직 요인(문화·관리자 지원·인재 제도)에서, 32%가 개인의 태도·행동에서 나왔고, 리더십이 AI에 대해 명확하고 일관되게 정렬돼 있다는 응답은 26%, 결과가 미흡해도 업무 혁신을 보상받는다는 응답은 13%에 그쳤다. 별도 1,800명 연구에서는 관리자가 AI를 직접 쓰는 모습을 보이면 직원이 느끼는 AI 가치가 17포인트, 에이전트형 AI에 대한 신뢰가 30포인트 높았고, 응답자의 86%는 AI 결과물을 최종 답이 아닌 출발점으로 다룬다고 했다. 마이크로소프트 365 안의 활성 에이전트는 1년 새 15배로 늘었으며, 보고서는 결과가 자기 보고에 기반한 상관관계라는 한계를 밝혔다.","eSum":"On May 5, 2026, Microsoft published its 2026 Work Trend Index annual report, based on a survey of 20,000 knowledge workers who use AI across 10 countries, fielded by Edelman Data x Intelligence from February to April 2026, plus Microsoft 365 productivity signals. Organizational factors such as culture, manager support and talent practices accounted for 67% of the AI-impact signal versus 32% for individual mindset and behavior, while only 26% of AI users said leadership is clearly and consistently aligned on AI and 13% said they are rewarded for reinvention even if results fall short. In a separate study of 1,800 workers, employees whose managers modeled AI use reported a 17-point lift in AI value and a 30-point lift in trust in agentic AI, and 86% of respondents treat AI output as a starting point rather than a final answer. Active agents in Microsoft 365 grew 15-fold year over year, and the report notes that its findings are self-reported associations rather than causal evidence.","kImp":"AI 정착이 개인 의지보다 조직 문화와 관리자에 달렸다는 결과이므로, 팀장이 먼저 자신의 AI 활용 사례를 회의에서 공유하고 AI 결과물의 품질 기준과 '시도했다 실패해도 괜찮은' 실험 범위를 정해 주는 것부터 시작할 만하다.","eImp":"Since AI uptake depends more on organizational culture and managers than on individual will, team leaders could start by sharing their own AI use in meetings, setting quality standards for AI-assisted work and defining an area where experiments are allowed to fail.","url":"https://www.microsoft.com/en-us/worklab/work-trend-index/agents-human-agency-and-the-opportunity-for-every-organization","prio":3,"kor":false,"tags":["AI","CHG","LDR"],"tool":""}]},{"code":"EFFIC","kTitle":"업무 효율·생산성","eTitle":"Efficiency and productivity","items":[{"code":"EFFIC","date":"2026-10-22","src":"아웃소싱타임스","title":"주4.5일제 지원사업 부산 사례…IT 유지보수사, 하루 1시간 줄이고도 월간 보고서 작성 8시간→2시간, 전자결재 2.5일→0.5일","eTitle":"Busan Cases From Korea's 4.5-Day Week Support Project: An IT Maintenance Firm Cut a Daily Hour While Reducing Monthly Report Preparation From Eight Hours to Two and E-Approval From 2.5 Days to Half a Day","kSum":"노사발전재단이 임금 삭감 없이 실노동시간을 줄이는 기업을 지원하는 '워라밸+4.5 프로젝트'(올해 347개사 참여)의 10월 21일 부산 운영위원회에서 두 기업 사례가 소개됐다. IT 인프라 유지보수 기업 디아이앤씨(58명)는 4개 부서 33명에게 임금 삭감 없는 주 35시간제를 도입하고 신규 인력 3명을 충원해 업무 쏠림을 막았으며, 월간 보고서 작성 시간을 건당 8시간에서 2시간으로, 전자결재 처리 기간을 2.5일에서 0.5일로 줄이고도 기존 서비스 수준을 유지했다. 깔창 제조사 영창에코(31명)는 매월 셋째 주 금요일을 유급 휴무로 정해 주 평균 2시간을 줄이고, 병목 공정 다기능화·ERP·MES·반복 업무 자동화로 1만 켤레 생산 시간을 50시간에서 46시간으로 줄였다. 수치는 회사가 밝힌 것이다.","eSum":"At the 21 October Busan steering meeting of the Work-Life Balance +4.5 Project, run by the Korea Labor-Management Development Foundation to support firms that cut actual working hours without pay cuts (347 firms this year), two cases were presented. A Haeundae IT infrastructure maintenance firm (58 staff) moved 33 employees in four departments to a 35-hour week without pay cuts and added three staff to avoid overloading individuals, while cutting monthly report preparation from eight hours to two and e-approval from 2.5 days to half a day with service levels maintained. An insole maker in Sasang (31 staff) made every third Friday a paid day off, cutting average weekly hours by two, and reduced production time for 10,000 pairs from 50 to 46 hours through cross-training, ERP and MES systems and automating repetitive work. The figures are company-reported.","kImp":"근무시간을 줄이려면 먼저 시간을 많이 잡아먹는 사무 절차를 찾아야 하므로, 월간 보고서 양식 통일·자동 취합과 결재 단계 축소처럼 측정 가능한 개선 과제 두 가지를 정해 전후 소요 시간을 기록해 볼 만하다.","eImp":"Cutting hours starts with finding the office procedures that eat time, so a team could pick two measurable fixes, such as standardising and auto-collating monthly report templates and removing approval steps, and log the time taken before and after.","url":"https://www.outsourcing.co.kr/news/articleView.html?idxno=204140","prio":2,"kor":true,"tags":["WR","AUTO","POL"],"tool":""},{"code":"EFFIC","date":"2026-10-21","src":"HRD America","title":"자브라 6천여 명 조사: AI는 일을 줄이지 않고 넓힌다…85% '1년 새 늘어난 업무 있어', 전략·분석 업무 51% 증가","eTitle":"Jabra study of 6,000 workers: AI broadens work rather than reducing it, with 85% doing more of at least one type of work","kSum":"HRD 아메리카는 2026년 10월 21일, 자브라가 전 세계 지식노동자 6,000여 명을 조사한 'WorkLife 2026' 보고서를 소개했다. 응답자의 85%가 지난 1년 사이 적어도 한 종류의 업무가 늘었다고 답했고(일부 업무가 줄었다는 응답은 35%), 업무별로는 전략 기획·분석(51%), 창의 업무(50%), 행정·조율(49%) 순으로 늘었으며 가장 덜 늘어난 단순 실행 업무도 40%가 증가했다고 했다. 동료와의 협업이 늘었다는 응답이 42%로 줄었다는 응답(13%)을 크게 웃돌았고, AI를 자주 쓰는 사람은 64%가 협업이 늘었다고 답해 덜 쓰는 사람(25%)보다 많았다. 회의 시간 대부분을 문제 해결(40%)이나 의사결정(39%)에 쓴다는 응답이 현황 보고·조율(30%)보다 많았다.","eSum":"HRD America reported on October 21, 2026, on Jabra's WorkLife 2026 report, a survey of more than 6,000 knowledge workers worldwide. 85% said they did more of at least one type of work over the past year, while 35% said some part of their work had shrunk, with the biggest increases in strategic planning and analysis (51%), creative work (50%) and administrative and coordination tasks (49%), and even routine execution, which grew least, rising for 40%. 42% collaborate more with colleagues than a year ago versus 13% who collaborate less, and 64% of frequent AI users collaborate more compared with 25% of less frequent users. More respondents spend most meeting time on problem solving (40%) or decisions (39%) than on status updates and coordination (30%).","kImp":"AI로 아낀 시간이 행정·조율 업무 증가로 다시 채워지지 않도록, 팀장은 분기마다 팀의 업무 목록을 점검해 새로 늘어난 일을 확인하고 덜 중요한 보고·조율 업무를 정리하는 시간을 따로 두는 것이 좋다.","eImp":"So that time saved with AI is not simply refilled by more administration and coordination, team leaders should review the team's task list every quarter, identify work that has grown and set aside time to prune less important reporting and coordination tasks.","url":"https://www.hcamag.com/us/specialization/hr-technology/ai-broadens-work-rather-than-reducing-it-study-finds/594319","prio":2,"kor":false,"tags":["WR","AI","MTG"],"tool":""},{"code":"EFFIC","date":"2026-10-21","src":"메가경제","title":"직장인 881명 조사 \"AI 쓰면 생산성 올랐다\" 95.4%…유료 사용자 10명 중 7명은 자기 돈으로, 월평균 약 3.7만 원 지출","eTitle":"Survey of 881 Korean Office Workers: 95.4% of AI Users Report Higher Productivity, and Seven in Ten Paying Users Cover the Cost Themselves, Spending About 37,000 Won a Month","kSum":"오피스 미디어 기업 스페이스애드의 '2026 직장인 AI 활용 현황' 조사(직장인 881명)에서 95.2%가 업무에 AI를 쓰고 있었고, AI 사용자의 95.4%가 생산성이 올랐다고 답했으며 효과로는 '같은 시간에 더 많은 일 처리'(62.4%), '업무 착수가 빨라짐'(57.7%), '결과물 품질 향상'(56.5%)을 꼽았다. 주요 용도는 문서·보고서 작성(70.6%)과 데이터 분석·정리(69.6%)였고, 주 1시간 이상 쓰는 766명이 쓰는 도구는 챗봇·AI 검색(89.9%), 문서·발표 도구(35.4%), 회의·노트 도구(26.2%) 순이었다. AI 사용자의 62.4%가 유료 서비스를 쓰는데 그중 10명 중 7명은 전액 또는 회사 지원과 별도로 개인 비용을 냈고, 직접 비용을 내는 직장인의 월평균 지출은 약 3만7,000원(51.4%는 월 3만 원 이상)이었다.","eSum":"Space AD's 2026 survey of 881 Korean office workers found 95.2% use AI at work and 95.4% of users say their productivity has improved, citing handling more work in the same time (62.4%), starting tasks faster (57.7%) and better output quality (56.5%). The main uses were writing documents and reports (70.6%) and analysing and organising data (69.6%); among 766 people using AI at least an hour a week, chatbots and AI search led (89.9%), followed by document and presentation tools (35.4%) and meeting and note tools (26.2%). 62.4% of users pay for a service and seven in ten of them pay fully or partly out of their own pocket, with those paying directly spending around 37,000 won a month on average and 51.4% spending 30,000 won or more.","kImp":"직원들이 개인 돈으로 산 AI 서비스에 업무 자료를 넣고 있을 가능성이 높으므로, 팀에서 실제로 쓰는 도구를 한번 조사해 회사 차원의 승인 도구·계정을 마련하고 문서·보고서 작성처럼 효과가 큰 업무부터 사용 지침을 정하는 것이 좋다.","eImp":"Staff are probably feeding work material into AI services they pay for themselves, so a team can survey which tools people actually use, provide approved company tools and accounts, and start usage guidelines with high-impact tasks such as drafting documents and reports.","url":"https://www.megaeconomy.co.kr/news/newsview.php?ncode=1065586598843027","prio":1,"kor":true,"tags":["AI","TOOL","SEC"],"tool":""},{"code":"EFFIC","date":"2026-10-08","src":"Becker's Hospital Review","title":"병원 임원 6명의 회의 줄이기: 30분 회의 기본값을 25분으로, 금요일 오후는 회의 없는 시간, 정보성 보고는 메일로","eTitle":"Shorter meetings, tighter agendas: six hospital executives on how they cut meeting overload","kSum":"베커스 호스피털 리뷰는 2026년 10월 8일, 미국 병원 임원 6명이 올해 회의 부담을 줄인 방법을 소개했다. 그레이트리버헬스는 아웃룩 기본값을 30분 회의는 25분, 1시간 회의는 50분으로 바꿔 이동·정리 시간을 두고, 대형 시스템 도입 때 만든 금요일 오후 회의 없는 시간을 프로젝트가 끝난 뒤에도 집중 업무용으로 유지했다. 쿠테나이헬스는 회의를 25·45·75분으로 줄이고 정보성 보고는 이메일로 돌려 회의를 집단 결정·실행에만 쓰며, 운영·투자·프로젝트·전략 안건을 별도 회의로 나눴다. 스크립스헬스는 정기 회의를 재검토해 시간과 참석자를 줄이고 글로 대신할 수 있는 보고는 서면으로 공유했으며 일부 인원은 관련 안건에만 참석하게 했다(절감 시간 수치는 제시되지 않았다).","eSum":"Becker's Hospital Review reported on October 8, 2026, how six US hospital executives cut meeting overload this year. Great River Health changed Outlook defaults so 30-minute meetings are scheduled for 25 minutes and hour-long ones for 50, and kept a Friday afternoon no-meeting block created during a major system implementation for focused work after the project ended. Kootenai Health shortened meetings to 25, 45 and 75 minutes, moved informational updates to email so meetings are reserved for group decisions and actions, and split operational, capital, project and strategic items into separate sessions. Scripps Health reviewed recurring meetings, shortened them, narrowed attendance and shared writable updates in writing, with some people attending only relevant agenda items; no figures on time saved were given.","kImp":"팀 일정표 기본값을 25분·50분으로 바꾸고, 주간 회의 안건에서 단순 보고를 빼 메일·공유 문서로 돌리며, 주 1회 반나절은 회의 없는 집중 시간으로 정해 두는 것부터 바로 해 볼 만하다.","eImp":"Teams can start right away by setting calendar defaults to 25 and 50 minutes, moving simple status reports out of the weekly meeting agenda into email or shared documents, and reserving one half-day a week as meeting-free focus time.","url":"https://www.beckershospitalreview.com/strategy/shorter-meetings-tighter-agendas-how-6-execs-reshaped-their-calendars-in-2026/","prio":1,"kor":false,"tags":["MTG","TIME"],"tool":""},{"code":"EFFIC","date":"2026-10-06","src":"SHRM","title":"NBER 연구(약 9천 명): 회의에 주 4.7시간·인건비 14%…회의 많은 기업이 임금·매출 높아 '줄이기보다 가려내기'","eTitle":"NBER study of 9,000 workers: meetings take 4.7 hours a week and 14% of payroll, yet meeting-intensive firms show higher wages and revenue","kSum":"SHRM은 2026년 10월 6일, 하버드 케네디스쿨 데이비드 데밍 교수 등이 약 9,000명의 설문·행정 데이터를 분석한 미국 전미경제연구소(NBER) 워킹페이퍼를 소개했다. 직원들은 주당 평균 4.7시간(표준 근무시간의 약 12%)을 회의에 쓰며, 회의 시간은 조직 인건비의 약 14%에 해당하는 것으로 추산됐다. 회의가 많은 기업일수록 임금·매출·1인당 매출이 높았고 회의 시간이 많은 직원일수록 임금 상승이 빠르고 업무 중 학습을 더 많이 했다고 답해, 연구진은 회의가 조직 역량에 대한 투자처럼 작동한다고 해석했다. 기사는 회의 축소 자체를 목표로 삼지 말고, 문제 해결·전문 업무 조율·지식 공유·인재 육성에 기여하는 회의와 정보만 전달하는 반복 현황 회의를 구분해 후자부터 줄이라고 권했다.","eSum":"SHRM reported on October 6, 2026, on a National Bureau of Economic Research working paper led by David Deming of the Harvard Kennedy School, based on survey and administrative data from about 9,000 workers. Employees average 4.7 hours a week in meetings, about 12% of a standard workweek, and meeting time is estimated to account for roughly 14% of an organization's payroll costs. Meeting-intensive companies had higher wages, revenue and revenue per worker, and workers who spent more time in meetings saw faster wage growth and reported more on-the-job learning, which the authors read as meetings functioning as investments in organizational capital. The article advises against treating fewer meetings as a goal in itself and suggests separating meetings that solve problems, coordinate specialized work, share knowledge or develop people from recurring status meetings that only relay information, which are the strongest candidates for cutting.","kImp":"회의를 일괄 줄이기보다 팀의 정기 회의를 '결정·문제 해결·학습' 회의와 '현황 공유' 회의로 나눠 보고, 현황 공유는 서면 보고나 공유 문서로 돌리되 여러 부서 전문가가 모이는 회의는 지키는 편이 낫다.","eImp":"Rather than cutting meetings across the board, sort the team's recurring meetings into decision, problem-solving and learning meetings versus status updates, move status updates to written reports or shared documents, and protect meetings that bring together experts from different departments.","url":"https://www.shrm.org/topics-tools/news/meetings-may-be-more-valuable-than-many-think","prio":2,"kor":false,"tags":["MTG","TIME"],"tool":""},{"code":"EFFIC","date":"2026-09-16","src":"Harvard Business Review","title":"HBR: 팀이 감당 못 할 만큼 일이 몰릴 때…멈출 일·줄일 일을 팀과 함께 정하고 결정 기준과 권한을 아래로","eTitle":"HBR: When there's more work than your team can handle, decide with the team what to pause or cut and push authority down","kSum":"하버드비즈니스리뷰는 2026년 9월 16일 경영 코치이자 헌터칼리지 교수인 멜로디 와일딩의 글에서, 업무가 팀 역량을 넘을 때 관리자가 일을 혼자 떠안거나 팀을 더 몰아붙이면 번아웃·신뢰 저하·이직이라는 비용이 따른다고 지적했다. 대신 무엇을 멈추거나 줄이거나 없앨지 팀과 함께 정하고, 위로는 추가 자원이나 일정 조정을 요청하며, 결정 기준을 명확히 해 팀이 관리자를 기다리지 않고 판단하게 하고, 업무와 함께 권한도 내려 주라고 권했다. 새 책임을 구성원의 동기와 연결하되 핵심 우선순위는 지키면서 부담을 인정하라는 조언도 담겼다. (구독 기사, 공개된 앞부분 기준)","eSum":"In a September 16, 2026 Harvard Business Review article, executive coach and Hunter College professor Melody Wilding wrote that when work exceeds a team's capacity, managers who absorb the extra work or push the team harder pay in burnout, eroded trust and attrition. She recommends deciding with the team what can be paused, scaled back or cut, advocating upward for more resources or timeline changes, making decision criteria explicit so the team can act without waiting for the manager, and pushing authority down along with tasks. She also advises connecting new responsibilities to what motivates people while holding the line on critical priorities and acknowledging the strain. (Subscription article; based on the publicly visible opening.)","kImp":"업무가 몰리는 시기에는 팀 회의에서 진행 중인 일 목록을 펴 놓고 '멈출 일·줄일 일·계속할 일'을 함께 정하고, 위로는 일정·인력 조정을 근거와 함께 요청하며, 팀원이 스스로 판단할 수 있도록 결정 기준을 문서로 공유할 만하다.","eImp":"In crunch periods, lay out the list of ongoing work in a team meeting and decide together what to pause, scale back or continue, ask upward for schedule or staffing changes with evidence, and share decision criteria in writing so team members can decide on their own.","url":"https://hbr.org/2026/09/when-theres-more-work-than-your-team-can-handle","prio":1,"kor":false,"tags":["TIME","LDR"],"tool":""},{"code":"EFFIC","date":"2026-08-24","src":"HR Insight","title":"\"야근 원인은 네 가지\"…업무 과부하·결재 지연과 재작업·'늦게 남아야 인정'·초과수당 유인, 유형별로 다른 데이터를 봐야","eTitle":"Four Kinds of Overtime: Workload Overload, Inefficient Approvals and Rework, Staying Late for Recognition and Overtime-Pay Incentives Each Need Different Data and Fixes","kSum":"김재순 J& COMPANY 대표는 HR Insight 9월호 기고에서 포괄임금제 오남용 방지 지침, 노동시간 기록 의무, '연결되지 않을 권리' 논의로 근무시간 관리가 기록·검토의 영역으로 넘어가고 있지만, 기록된 시간만으로는 장시간 근무의 원인을 알 수 없다고 짚었다. 그는 원인을 결원 미충원 등 업무 과부하형, 승인 지연·지시 변경에 따른 재작업 등 업무 방식 비효율형, 늦게 남는 것이 인정 기준처럼 학습된 인정 욕구형, 초과근로수당이 동기가 되는 보상 유인형으로 나누고, 각각 인원 대비 업무량·결원 기간, 결재 대기 시간·재작업·지시 변경 이력, 리더의 평가·발언 패턴, 임금 구조 등 다른 데이터를 보라고 했다. 정시 퇴근 캠페인보다 업무분장 조정, 결재·지시 체계 점검, 근무시간이 아닌 성과 기준의 인정이 필요하다고 권했다. (구독 기사, 공개된 앞부분 기준)","eSum":"In HR Insight's September issue, J& Company CEO Kim Jae-soon argues that guidance against misuse of all-inclusive pay, duties to record working hours and the 'right to disconnect' debate are turning working-time management into a matter of records and review, yet recorded hours alone do not explain long hours. He sorts the causes into workload overload such as unfilled vacancies, inefficient working methods such as approval delays and rework from changed instructions, recognition-seeking where staying late has become a learned signal, and pay incentives where overtime pay drives extra hours. Each calls for different data, from workload per head and vacancy periods to approval waiting times, rework and instruction-change records, leaders' remarks and appraisal patterns, and pay structure. He recommends adjusting the division of work, reviewing approval and instruction chains and recognising results rather than hours, instead of relying on leave-on-time campaigns.","kImp":"팀장은 야근이 잦은 직원을 개인 문제로 보기 전에 결재 대기 시간과 지시 변경으로 인한 재작업이 얼마나 되는지부터 확인하고, '늦게까지 남는 사람'을 칭찬하는 말버릇이 없는지 스스로 점검해 볼 만하다.","eImp":"Before treating frequent overtime as an individual problem, team leaders can check how much time goes on waiting for approvals and reworking after changed instructions, and examine whether they habitually praise people for staying late.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=112&bi_pidx=39495","prio":1,"kor":true,"tags":["TIME","WR","LDR"],"tool":""}]},{"code":"SOFT","kTitle":"업무 소프트웨어 소개","eTitle":"Work software","items":[{"code":"SOFT","date":"2026-10-27","src":"Microsoft Excel Blog (Tech Community)","title":"엑셀 코파일럿 '데이터 정리'·'스킬 빌더' 정식 배포…웹 엑셀에선 말로 Power Query 만드는 '데이터 가져오기'","eTitle":"Copilot in Excel adds Clean data and Skill builder, plus a Get data skill on the web that builds Power Query from plain language","kSum":"마이크로소프트는 2026년 10월 27일 'What's New in Excel(2026년 10월)'에서 엑셀 코파일럿 새 기능을 정리했다. '데이터 정리(Clean data)' 스킬은 불필요한 공백, 텍스트·숫자·날짜 서식 불일치, 중복, 잘못된 데이터 형식처럼 수식·조회·피벗테이블을 깨뜨리는 문제를 찾아 설명하고 고칠 항목을 골라 적용하게 하며 모든 플랫폼에 정식 배포 중이다. 지시문·이전 프롬프트·완성 예시로 반복 작업용 스킬을 만드는 '스킬 빌더'도 정식 배포 중이고, 직접 한 작업을 기록해 스킬로 만드는 '스킬 레코더'는 웹에서 정식, 윈도·맥은 인사이더 단계다. 웹 엑셀의 '데이터 가져오기(Get data)'는 원본과 원하는 형태를 말로 설명하면 Power Query 쿼리를 만들어 확인·수정·새로 고침할 수 있게 하고, 데이터를 자동 갱신 보고서로 바꾸는 '인터랙티브 캔버스'는 윈도 인사이더에 먼저 나왔다.","eSum":"In its October 2026 'What's New in Excel' post on October 27, 2026, Microsoft listed new Copilot in Excel features. A Clean data skill finds issues that break formulas, lookups and PivotTables, such as stray spaces, inconsistent text, number and date formats, duplicates and wrong data types, explains them and lets users accept fixes selectively; it is rolling out to general availability on all platforms. Skill builder creates reusable skills from instructions, prior prompts or completed examples and is also rolling out to general availability, while Skill recorder, which turns demonstrated steps into a skill, is generally available on the web and in Insiders on Windows and Mac. On Excel for the web, a Get data skill builds a Power Query query from a plain-language description that users can inspect, edit and refresh, and an Interactive canvas that turns workbook data into a live report is first in Insiders on Windows.","kImp":"매달 같은 형식으로 만드는 실적·비용·현황 집계표가 있다면 '데이터 정리'로 원본의 서식 불일치·중복부터 잡고, 반복 절차는 스킬로 저장해 담당자가 바뀌어도 같은 방식으로 돌리게 할 만하다; AI가 고친 셀은 변경 내역에서 확인하고, 사내 라이선스에 코파일럿이 포함됐는지도 먼저 확인해야 한다.","eImp":"For monthly reports and trackers built in the same format each time, teams can use Clean data to fix inconsistent formats and duplicates in the source first, and save recurring steps as a skill so the process stays the same when the person in charge changes; check AI-made edits in the change history and confirm that the organization's licences include Copilot.","url":"https://techcommunity.microsoft.com/blog/excelblog/whats-new-in-excel-october-2026/4549758","prio":2,"kor":false,"tags":["TOOL","AI","DATA"],"tool":"Microsoft Excel"},{"code":"SOFT","date":"2026-10-26","src":"Computerworld","title":"팀즈에 AI 피싱·사기 탐지 기능…새 연락처의 메시지 내용 분석해 경고, 11월 초 배포 시작","eTitle":"Microsoft Teams to get AI protection that analyzes chat messages for phishing and fraud, starting in early November","kSum":"컴퓨터월드는 2026년 10월 26일, 마이크로소프트가 팀즈에 피싱·사기·신원 도용을 잡아내는 AI 보안 기능을 추가한다고 보도했다(마이크로소프트 365 메시지 센터 공지 MC1519866 기반). 링크·파일 검사 위주였던 기존 방식과 달리 메시지 자체의 의심스러운 행태를 분석하며, 위험이 큰 새 연락처와의 대화에 우선 초점을 맞춘다. 처음에는 품질 검증을 위해 경고 없이 백그라운드에서 탐지하다가 이후 의심 메시지에 사용자 경고를 띄울 수 있으며, 메시지를 저장하거나 AI 학습에 쓰지 않고 보안 목적으로만 쓴다고 밝혔다. 배포는 2026년 11월 초 시작해 12월 상반기 정식 제공 예정이며, IT 부서가 따로 설정하지 않아도 자동으로 켜진다.","eSum":"Computerworld reported on October 26, 2026, citing Microsoft 365 Message Center post MC1519866, that Microsoft is adding an AI-powered security feature to Teams to detect phishing, scams and identity theft. Instead of relying mainly on scanning links and files, it examines the messages themselves for suspicious behavior, focusing mainly on new contacts as a higher risk. Detection may first run in the background without warnings while Microsoft validates quality, after which users may see a warning on suspected phishing, and Microsoft says messages are not saved or used to train AI models and the tool is for security only. The rollout starts in early November 2026 with general availability expected in the first half of December, and it is enabled automatically without IT configuration.","kImp":"외부 업체·대리점과 팀즈 채팅을 많이 하는 육상 팀은 새 경고가 뜨기 시작하면 무엇을 확인하고 누구에게 신고할지 미리 안내하고, 'IT 지원팀을 사칭한 원격 접속 요청'처럼 알려진 수법은 경고가 없어도 응하지 않는다는 원칙을 다시 공유해 두는 것이 좋다.","eImp":"Shore teams that chat on Teams with outside suppliers and agents should tell staff in advance what to check and whom to report to when the new warnings appear, and restate that known tricks such as remote-access requests from people posing as IT support must be refused even without a warning.","url":"https://www.computerworld.com/article/4240393/microsoft-teams-gets-ai-protection-against-phishing-and-fraud.html","prio":2,"kor":false,"tags":["TOOL","SEC","COLLAB"],"tool":"Microsoft Teams"},{"code":"SOFT","date":"2026-10-23","src":"Anthropic (Claude Blog)","title":"앤트로픽, 기업용 Claude에서 채팅과 Cowork 통합 정식 제공…문서·분석·발표자료를 클라우드에서 끝까지 작업","eTitle":"Anthropic unifies chat and Cowork for Claude Enterprise, finishing documents, analyses and decks in the cloud","kSum":"앤트로픽은 2026년 10월 23일 Claude Enterprise 고객에게 그동안 따로 쓰던 채팅과 Cowork를 하나로 합친 환경을 정식 제공한다고 밝혔다(Pro·Max는 9월 먼저 적용). 간단한 질문은 바로 답하고, 코드 실행이나 파일 작업이 필요한 일은 격리된 클라우드 가상머신에서 이어 처리해 완성된 문서·분석·발표자료를 돌려주며, 노트북을 닫아도 작업이 계속되고 웹·데스크톱·모바일에서 이어 볼 수 있다. 관리자는 역할별 접근, Sonnet·Haiku만 쓰는 Efficient 모드, 역할별 모델 지정, 조직·그룹·개인 단위 지출 한도, 그룹 공동 월 예산으로 사용량을 관리하며, 요금은 사용량 기반이다. 데이터는 전송·저장 시 암호화되고 기본적으로 모델 학습에 쓰이지 않으며, 엔터프라이즈는 외부 네트워크 접속(egress)이 기본 차단된다.","eSum":"On October 23, 2026, Anthropic made a unified chat and Cowork experience generally available to Claude Enterprise customers, after launching it for Pro and Max in September. Simple questions get quick answers, while tasks that need code or files continue in an isolated cloud virtual machine and return a finished document, analysis or deck, even after the user closes the laptop. Admins can manage usage-based costs with role-based access, an Efficient mode limited to Sonnet and Haiku, per-role model entitlements, spend limits at organization, group and member level, and pooled group budgets. Data is encrypted in transit and at rest, is not used for training by default, and network egress is off by default for Enterprise.","kImp":"AI 비서를 회사 단위로 들일 때는 이 사례처럼 역할별 권한·지출 한도·사용 모델을 먼저 정하고, 문서·분석 작업이 많은 한두 팀에 시범 적용해 비용과 결과물 품질을 확인한 뒤 넓히는 것이 안전하다.","eImp":"When bringing in an AI assistant company-wide, set role permissions, spend limits and allowed models first, as these controls allow, then pilot with one or two document- and analysis-heavy teams to check cost and output quality before expanding.","url":"https://claude.com/resources/articles/unified-claude-enterprise","prio":2,"kor":false,"tags":["TOOL","AI","SEC"],"tool":"Claude"},{"code":"SOFT","date":"2026-10-23","src":"서울경제","title":"AI 회의록 다글로, 목소리로 발화자 알아보는 '보이스매칭' 출시…'참석자 1' 대신 실명 자동 표기, 정확도 약 94%","eTitle":"AI Meeting-Notes Service Daglo Launches Voice Matching, Labelling Speakers by Name Instead of 'Participant 1' With About 94% Accuracy","kSum":"AI 음성 기술 기업 액션파워는 23일 회의록 서비스 다글로에 성문(목소리 특징) 인식으로 발화자를 알아보는 '보이스매칭' 기능을 내놨다. 사용자가 동의한 뒤 회의록의 '참석자 1'을 실명으로 바꾸면 AI가 그 목소리 특징을 학습해 이후 녹음에서 자동으로 이름을 붙이며, 실제 녹음 환경에서 측정한 화자 식별 정확도는 약 94%라고 회사는 밝혔다. 여러 회의에 걸친 특정 참석자의 발언만 모아 보거나 요약할 수도 있으며, 회사는 최근 팀 단위 요금제 '팀플랜'을 내놓고 ISO 27001 인증을 받았다. 기사에는 가격·지원 언어·음성 데이터 보관 방식이 나오지 않는다.","eSum":"AI voice company Action Power on 23 October added Voice Matching to its Daglo meeting-notes service, using voiceprint recognition to identify speakers. Once a user consents and renames 'Participant 1' in a transcript to a real name, the AI learns that voice and labels the speaker automatically in later recordings, with about 94% identification accuracy measured in real recording conditions, according to the company. Users can also gather or summarise one participant's remarks across several meetings; the company recently launched a team plan and obtained ISO 27001 certification. The article does not give pricing, supported languages or how voice data is stored.","kImp":"회의록 작성 부담이 큰 팀에 유용하지만 목소리는 생체 정보에 가까우므로, 도입 전 참석자 전원의 동의 절차와 음성 데이터 보관·삭제 정책을 확인하고 외부 회의(선주·협력사)에는 상대방 동의 없이 쓰지 않는 것이 원칙이어야 한다.","eImp":"It can ease minute-taking for busy teams, but voiceprints are close to biometric data, so teams should confirm consent procedures and voice-data retention and deletion policies first, and not use it in external meetings with owners or partners without their agreement.","url":"https://www.sedaily.com/article/20105030","prio":2,"kor":true,"tags":["TOOL","MTG","AI"],"tool":"Daglo"},{"code":"SOFT","date":"2026-10-22","src":"Google Workspace Updates","title":"구글 미트 실시간 음성 통역, 63개 언어로 확대…말하는 언어 자동 감지","eTitle":"Real-time speech translation in Google Meet expands to 63 languages with automatic language detection","kSum":"구글은 2026년 10월 22일 Gemini 3.5 Live Translate 기반 구글 미트 음성 통역을 63개 언어로 넓히고, 한 회의 안에서 지원 언어 간 어떤 조합이든 통역되도록 바꿨다고 밝혔다(이전에는 회의 전체에 한정된 언어 쌍만 설정 가능). 미트가 말하는 언어를 자동 감지해 참가자별로 통역하고, 화자가 언어를 바꿔도 따라가며 번역 자막이 통역 음성과 맞춰진다. Business Standard·Plus, Enterprise Standard·Plus 등에서 쓸 수 있고 기본 요금제는 회의당 90분 제한이 있으며, Rapid Release 도메인은 10월 22일, Scheduled Release 도메인은 11월 2일부터 순차 적용된다. 라이브 스트림·녹화·클라이언트 측 암호화 회의에서는 지원되지 않고, 관리자가 조직 단위·그룹별로 켜고 끌 수 있다.","eSum":"On October 22, 2026, Google said Gemini-powered speech translation in Google Meet, built on Gemini 3.5 Live Translate, now covers 63 languages and can translate between any pair of supported languages in the same meeting, instead of a limited set of pairs fixed for the whole meeting. Meet detects the spoken language automatically, follows speakers who switch languages, and keeps translated captions in sync with translated audio. It is available on Business Standard and Plus, Enterprise Standard and Plus and other eligible plans, with a 90-minute per-meeting cap on base plans; Rapid Release domains start October 22 and Scheduled Release domains November 2. Live streams, recordings and client-side encrypted meetings are not supported, and admins can switch it on or off by organizational unit or group.","kImp":"해외 사무소·대리점·외국인 직원과 화상회의가 잦은 육상 팀이라면 시험 통화로 한국어 지원 여부와 통역 정확도부터 확인하고, 계약 조건·기술 사양처럼 오역 위험이 큰 내용은 회의 뒤 서면으로 다시 확인하는 규칙을 함께 두는 것이 좋다.","eImp":"Shore teams that often hold video calls with overseas offices, agents or foreign colleagues should first run a test call to check whether Korean is supported and how accurate the translation is, and keep a rule that contract terms or technical specifications discussed through translation are confirmed again in writing.","url":"https://workspaceupdates.googleblog.com/2026/10/real-time-speech-translation-in-google-Meet-expands-to-63-languages-with-automatic-language-detection.html","prio":2,"kor":false,"tags":["TOOL","COLLAB","XC"],"tool":"Google Meet"},{"code":"SOFT","date":"2026-10-22","src":"TechTarget","title":"데스크톱 AI 에이전트 비교: Claude Cowork·Copilot Cowork·ChatGPT Work·Gemini Spark…'어디서 실행되고 무엇에 접근하며 어떻게 과금되나'로 고르라","eTitle":"TechTarget compares desktop AI agents Claude Cowork, Copilot Cowork, ChatGPT Work and Gemini Spark on where they run, what they reach and how they bill","kSum":"테크타깃은 2026년 10월 22일 데이터 전략가 도널드 파머의 글에서 사용자 PC나 클라우드에서 여러 단계 작업을 직접 수행하는 '데스크톱 에이전트'를 비교했다. Claude Cowork는 PC의 격리된 가상환경에서 사용자가 허용한 폴더의 워드·엑셀·파워포인트·PDF 파일을 읽고 만들며 정액 구독 사용량 안에서 쓰지만 작업 1건이 채팅 메시지의 50~100배 토큰을 쓸 수 있고, Microsoft Copilot Cowork는 마이크로소프트 365 테넌트 안에서 아웃룩·팀즈·셰어포인트·원드라이브·엑셀과 연동하지만 로컬 파일은 다루지 못하며 기본 꺼짐·코파일럿 라이선스 필요·작업당 Copilot Credits 과금이라 끝나기 전까지 비용을 알 수 없다. ChatGPT Work는 PC가 꺼져도 이어지는 클라우드 가상머신 모드와 로컬 모드를 지원하고 네트워크 접근이 기본 차단되며, Gemini Spark는 미국 한정 베타로 개인 계정만 지원해 대부분 기업에는 맞지 않는다고 평가했다. 필자는 실행 위치·자율성 수준·과금 방식의 세 질문으로 고르고 통제된 시범 운영부터 단계적으로 도입하라고 권했다.","eSum":"In an October 22, 2026 TechTarget article, data strategist Donald Farmer compared desktop agents that carry out multistep tasks on a user's device or in the cloud. Claude Cowork works in a sandboxed VM on the local machine with user-selected folders, reading and creating Word, Excel, PowerPoint and PDF files under a flat subscription, though one task can use 50 to 100 times the tokens of a chat message; Microsoft Copilot Cowork runs inside the Microsoft 365 tenant with Outlook, Teams, SharePoint, OneDrive and Excel but cannot work on local files, is off by default, needs a Copilot license and bills per task in Copilot Credits, so costs are unknown until a task completes. ChatGPT Work offers an isolated cloud VM that keeps running when the user's machine is off as well as a local mode, with network access off by default, while Gemini Spark is a US-only beta for personal accounts that the author does not consider suitable for most organizations. He advises choosing by where the work runs, how much autonomy to allow and how the product is paid for, and rolling out in phases starting with a controlled pilot.","kImp":"에이전트 도구를 검토할 때는 성능 비교보다 먼저 '회사 문서가 PC·회사 클라우드·외부 클라우드 중 어디서 처리되는가', '사람 승인 없이 어디까지 실행하는가', '작업당 비용을 미리 알 수 있는가'를 확인하고, 민감 자료가 없는 업무로 시범 운영을 시작하는 것이 안전하다.","eImp":"When evaluating agent tools, first check where company documents are processed (on the PC, in the company cloud or in an outside cloud), how far the agent can act without human approval and whether per-task costs are predictable, and start the pilot with work that involves no sensitive material.","url":"https://www.techtarget.com/ai/tip/Agents-on-the-desktop-Claude-Cowork-and-its-equivalents","prio":2,"kor":false,"tags":["TOOL","AI","SEC"],"tool":"Claude Cowork, Microsoft Copilot Cowork, ChatGPT Work"},{"code":"SOFT","date":"2026-10-22","src":"한국경제","title":"국내 생성형 AI 결제액 1~9월 1조3,258억 원, 지난해 연간의 1.8배…3분기 점유율 클로드 51.2%·챗GPT 36.1%, 클로드는 법인카드 결제가 59.4%","eTitle":"Korean Card Spending on Generative AI Reaches 1.33 Trillion Won in January-September, 1.8 Times Last Year's Total, With Claude Taking 51.2% of Third-Quarter Payments and 59.4% of Its Spending on Corporate Cards","kSum":"한경에이셀이 약 2,000만 명 카드 이용자 패널로 추정한 '2026년 3분기 한국 생성형 AI 소비 동향 보고서'에 따르면 올해 1~9월 국내 생성형 AI 결제액은 1조3,258억 원으로 지난해 연간(7,408억 원)의 약 1.8배였고, 3분기만 5,796억 원으로 전 분기보다 26.5% 늘었다. 3분기 결제액 점유율은 클로드 51.2%, 챗GPT 36.1%, 제미나이 9.7%, 뤼튼 2.2% 순이었다. 클로드 결제액(2,965억 원)의 59.4%(약 1,760억 원)가 법인카드였고 건당 평균은 약 11만3,400원으로 챗GPT의 두 배 가까웠으며, 챗GPT는 3분기 결제액이 43.9% 늘며 점유율을 31.7%에서 36.1%로 높였다. 개인·법인카드가 모두 포함되며 앱마켓 인앱 결제와 대형 B2B 계약은 일부 빠질 수 있다.","eSum":"Hankyung Aicel's third-quarter 2026 report on Korean generative-AI spending, estimated from a panel of about 20 million card users, puts January-September payments at 1.3258 trillion won, about 1.8 times last year's total of 740.8 billion won, with 579.6 billion won in the third quarter alone, up 26.5% on the previous quarter. Claude took 51.2% of third-quarter payments, ChatGPT 36.1%, Gemini 9.7% and Wrtn 2.2%. 59.4% of Claude's 296.5 billion won came from corporate cards and its average ticket of about 113,400 won was nearly double ChatGPT's, while ChatGPT's quarterly payments rose 43.9%, lifting its share from 31.7% to 36.1%. Both personal and corporate cards are included, but in-app payments and large B2B contracts may be partly missing.","kImp":"직원들이 업무용 AI를 개인 카드·법인카드로 제각각 결제하고 있다면 비용과 데이터 관리가 흩어지므로, 팀별 실제 사용 서비스와 비용을 한 번 모아 보고 회사 차원의 계약·보안 조건을 갖춘 서비스로 정리할지 검토해 볼 만하다.","eImp":"If staff are paying for work AI piecemeal on personal and corporate cards, cost and data control are scattered, so it is worth collecting which services each team actually uses and what they cost, then considering consolidation onto services with company-level contracts and security terms.","url":"https://www.hankyung.com/article/202610227317g","prio":2,"kor":true,"tags":["TOOL","AI","DATA"],"tool":""},{"code":"SOFT","date":"2026-10-22","src":"Google Workspace Updates","title":"구글 Vault, Gmail·문서·미트 속 Gemini 대화 기록을 감사·법적 대응용으로 골라 내보내기 지원","eTitle":"Google Vault now supports filtered eDiscovery exports of Gemini in Workspace conversations","kSum":"구글은 2026년 10월 22일 Google Vault에서 Gmail·드라이브·문서·시트·슬라이드·미트에서 나눈 Gemini 대화를 전자증거개시(eDiscovery)용으로 골라 내보낼 수 있게 했다고 밝혔다. 대화 기록 설정이 켜져 있을 때만 수집되며, 관리자는 사용자·조직 단위(최대 5,000명)와 기간·시간대로 걸러 프롬프트·AI 응답·생성 첨부물·참조 파일 링크·인용을 JSON으로 내보낼 수 있다. Business Plus, Enterprise Standard·Plus 등과 Vault 부가 서비스에서 바로 쓸 수 있고 API는 화면 배포 후 14일 안에 지원된다. Gemini 대화에 대한 보존 규칙과 소송 보류(litigation hold)는 아직 없으며 추후 제공될 예정이다.","eSum":"On October 22, 2026, Google said Google Vault now supports filtered eDiscovery exports of users' Gemini in Workspace conversations from Gmail, Drive, Docs, Sheets, Slides and Meet, captured only when conversation history is on. Admins can filter by users or organizational units (up to 5,000 users), date range and time zone, and export JSON files with prompts, AI responses, generated attachments, links to referenced files and citations. It is available now on Business Plus, Enterprise Standard and Plus and other eligible editions, with API support due within 14 days of the UI rollout. Retention rules and litigation holds for Gemini conversations are not yet included and will follow in future releases.","kImp":"직원들이 메일·문서 속 AI에 업무 내용을 묻기 시작하면 그 대화 기록도 보존·감사 대상이 될 수 있다; IT·법무 담당은 AI 대화 기록의 보관 기간과 사용자 삭제 허용 여부를 사내 문서 보존 규정에 맞춰 미리 정해 두는 것이 좋다.","eImp":"Once staff start asking AI inside email and documents about work matters, those conversations can become records subject to retention and audit; IT and legal staff should decide how long AI conversation history is kept and whether users may delete it, in line with existing document retention rules.","url":"https://workspaceupdates.googleblog.com/2026/10/google-vault-now-supports-filtered-exports-for-Gemini-in-Workspace.html","prio":1,"kor":false,"tags":["TOOL","SEC","AI"],"tool":"Google Vault"},{"code":"SOFT","date":"2026-10-21","src":"Microsoft OneDrive Blog (Tech Community)","title":"원드라이브·셰어포인트 코파일럿 정식 제공…여러 엑셀 파일 동시 분석, 파일 하나에 링크 하나 'Hero Links', 동기화 100만 개","eTitle":"Copilot in OneDrive and SharePoint is generally available, with multi-spreadsheet analysis, single 'Hero Links' per file and sync for up to one million items","kSum":"마이크로소프트는 2026년 10월 21일 원드라이브 블로그에서 10월 20일 'OneDrive + Copilot' 행사 내용을 정리하며 원드라이브·셰어포인트의 코파일럿을 정식 제공한다고 밝혔다. 코파일럿은 여러 스프레드시트를 한 번에 분석해 차트와 추세를 짚고, 어수선한 프로젝트 폴더를 정리하며, 파일을 대화로 다듬는 인터랙티브 HTML 보고서로 바꿀 수 있고, 반복 절차를 개인 스킬로 저장할 수 있다. 공유 방식은 파일·폴더마다 링크 하나만 두고 권한을 바꿔도 같은 주소를 유지하는 'Hero Links'로 바뀌고 있으며, 90일 뒤 조직 전체 링크를 '추가된 사람만'으로 되돌리는 만료 정책이 곧 나온다. 동기화는 윈도·맥에서 최대 100만 개 항목(최소 8GB 메모리)을 지원하고, 관리자용 SharePoint Admin Agent와 폴더 단위 동기화 제외 정책(비공개 미리보기)도 소개됐으나 라이선스 조건은 밝히지 않았다.","eSum":"On October 21, 2026, Microsoft's OneDrive blog recapped its October 20 OneDrive + Copilot event and said Copilot in OneDrive and SharePoint is now generally available. Copilot can analyze several spreadsheets at once with charts and trend highlights, sort cluttered project folders, turn files into interactive HTML reports refined through follow-up prompts, and save repeated processes as personal skills. Sharing is moving to Hero Links, one link per file or folder that keeps the same URL when permissions change, with expiring-link controls coming soon, such as reverting organization-wide links to 'Only People Added' after 90 days. Sync now supports up to one million items on Windows and macOS with as little as 8GB of RAM, and admins get a SharePoint Admin Agent and a folder-level sync exclusion policy in private preview; the post does not state licensing requirements.","kImp":"공유 링크가 메일마다 따로 돌아 '어느 파일이 최신인지' 헷갈리던 팀이라면 파일당 링크 하나 방식과 링크 만료 정책을 함께 정비할 만하고, 여러 부서 집계표를 한꺼번에 비교하는 작업은 코파일럿 분석으로 초안을 만든 뒤 원본 수치와 대조하는 것이 좋다.","eImp":"Teams confused about which emailed link points to the latest file could adopt one link per file together with link-expiry policies, and for comparing several departments' spreadsheets at once, use Copilot's analysis as a first draft and then check it against the source figures.","url":"https://techcommunity.microsoft.com/t5/microsoft-onedrive-blog/onedrive-just-got-a-major-upgrade-new-copilot-capabilities/ba-p/4565995","prio":2,"kor":false,"tags":["TOOL","COLLAB","AI"],"tool":"Microsoft OneDrive"},{"code":"SOFT","date":"2026-10-21","src":"Anthropic (Claude Blog)","title":"앤트로픽 'Claude Duet' 공개…메일·일정·청구서를 몇 시간마다 살피고 승인받아 처리하는 선제형 업무 비서","eTitle":"Anthropic introduces Claude Duet, a proactive work agent that checks connected apps and acts only on approval","kSum":"앤트로픽은 2026년 10월 21일 Claude가 먼저 일을 챙기는 별도 앱 'Claude Duet'를 대기자 등록 방식의 연구용 미리보기로 공개했다. 매일 아침 연결된 앱의 중요 사항을 요약해 보내고, 몇 시간마다 계정을 확인해 놓친 Gmail·Slack 메시지 회신, 회의 일정 조율, 미수금 독촉 초안, 계약서 서명 요청 등을 돕는다. 메시지 발송·결제·서명·삭제 전에는 반드시 사용자 승인을 받고, 증권 거래와 계좌 간 이체는 승인해도 막혀 있으며, 비밀번호·로그인 토큰을 직접 보지 않도록 설계했다고 밝혔다. 우선 미국 Pro·Max 구독자에게 iOS·안드로이드 앱과 claude.ai로 제공되며, 별도 요금 없이 기존 사용 한도를 함께 쓴다.","eSum":"On October 21, 2026, Anthropic introduced Claude Duet, a separate app in which Claude works as a proactive agent, as a waitlisted research preview. It sends a morning brief of important items across connected apps, checks accounts every few hours, and helps reply to missed Gmail and Slack messages, schedule meetings, draft invoice reminders and send agreements for signature. It asks for approval before sending messages, making payments, signing or deleting anything, blocks securities trading and moving money between accounts even with approval, and never directly sees passwords or sign-in tokens. It starts with US Pro and Max subscribers on iOS, Android and claude.ai, at no extra charge within existing usage limits.","kImp":"국내에서는 아직 쓸 수 없지만 AI 비서가 '먼저 알려 주고 승인받아 실행하는' 방식으로 가고 있음을 보여 준다; 팀에서 이런 도구를 검토할 때는 어떤 행동에 사람 승인을 필수로 둘지, 어떤 업무 계정을 연결해도 되는지 기준부터 정해 두는 것이 좋다.","eImp":"It is not yet available in Korea, but it shows AI assistants moving toward a 'flag first, act on approval' model; teams evaluating such tools should first decide which actions always need human approval and which work accounts may be connected.","url":"https://claude.com/resources/articles/claude-duet","prio":1,"kor":false,"tags":["TOOL","AI","AUTO"],"tool":"Claude Duet"},{"code":"SOFT","date":"2026-10-21","src":"Google Workspace Updates","title":"구글 문서 모바일 'Docs Live'…말로 대화하며 메일·드라이브 자료를 끌어와 보고서 초안 작성","eTitle":"Docs Live in Google Docs mobile lets users build structured documents by voice, drawing on Gmail, Drive and Chat","kSum":"구글은 2026년 10월 21일 구글 문서 모바일 앱(안드로이드·iOS)에서 손을 쓰지 않고 대화로 구조화된 문서를 만드는 'Docs Live'를 Workspace 사용자에게 배포한다고 밝혔다. Gmail·드라이브·채팅과 웹 자료를 참고해 프로젝트 진행 보고, 제안서, 발표 대본 같은 초안을 함께 쓰는 방식이다. Business Standard·Plus, Enterprise Standard·Plus, Google AI Pro·Ultra 등이 대상이며 Rapid·Scheduled Release 도메인 모두 바로 쓸 수 있고, 문서에서 Gemini가 켜진 사용자에게는 기본으로 켜진다. 지원 언어는 공지에 밝히지 않았다.","eSum":"On October 21, 2026, Google said it is rolling out Docs Live to Workspace users in the Google Docs mobile app on Android and iOS, a hands-free assistant that helps build structured documents through conversation. It can draw on Gmail, Drive, Chat and web content to draft project updates, proposals and presentation talk tracks. It is available now for Rapid and Scheduled Release domains on Business Standard and Plus, Enterprise Standard and Plus, Google AI Pro and Ultra and other eligible plans, and is on by default for users with Gemini in Docs enabled. The post does not say which languages are supported.","kImp":"출장·현장 방문 중 이동 시간에 회의 결과나 방문 보고 초안을 말로 잡아 두는 데 쓸 수 있지만, 메일·드라이브 자료를 끌어오므로 문서 공유 범위를 확인하고 한국어 지원 여부를 먼저 시험해 보는 것이 좋다.","eImp":"Staff on business trips or site visits could use travel time to dictate first drafts of meeting outcomes or visit reports, but because it pulls from email and Drive, check document sharing scope and first test whether Korean is supported.","url":"https://workspaceupdates.googleblog.com/2026/10/create-structured-documents-using-just-your-voice-with-Docs-Live-in-Google-Docs-on-mobile.html","prio":1,"kor":false,"tags":["TOOL","WRT","AI"],"tool":"Google Docs"},{"code":"SOFT","date":"2026-10-21","src":"Microsoft Teams Blog (Tech Community)","title":"팀즈, 저사양 PC에 '효율 모드' 기본 적용…메모리 8GB 이하 기기에서 실행 최대 20% 빨라져","eTitle":"Microsoft Teams adds an Efficiency Mode that launches up to 20% faster on older or low-memory PCs","kSum":"마이크로소프트는 2026년 10월 21일 팀즈 블로그에서 팀즈의 반응 속도와 안정성을 높이는 개선 사항을 소개했다. 윈도·맥용 '팀즈 효율 모드'는 느리거나 오래된 CPU와 8GB 이하 메모리를 가진 기기에서 기본으로 켜지고(제목 표시줄에 표시) 다른 기기에서도 사용자가 직접 켜고 끌 수 있으며, 이 모드에서는 팀즈 실행이 최대 20% 빨라지고 회의 중에는 음성 품질을 지키기 위해 카메라 해상도를 조정한다. 안드로이드 앱은 메모리 누수 등을 고쳐 느린 화면 지표가 1년 새 40% 개선되고 이미지 썸네일 지연이 약 17% 줄었다고 밝혔다.","eSum":"On October 21, 2026, Microsoft's Teams blog described work to make Teams more responsive and reliable. Teams Efficiency Mode for Windows and macOS is enabled by default on devices with slower or legacy CPUs and 8 GB of RAM or less, shown by a title bar indicator, and users can switch it on or off manually on any device; in this mode Teams launches up to 20% faster, and during meetings camera resolution is adjusted to preserve CPU for audio. On Android, fixes to memory leaks and other issues improved the slow-frame metric by 40% year over year and cut thumbnail latency by about 17%.","kImp":"사무실에 오래된 노트북이 섞여 있다면 회의 중 끊김 불만이 잦은 PC부터 효율 모드가 켜졌는지 확인하고, 화상회의에서는 음성이 우선된다는 점을 직원들에게 알려 두면 불필요한 장비 교체 요청을 줄일 수 있다.","eImp":"If the office still has older laptops, check whether Efficiency Mode is on for the PCs with the most complaints about call problems, and tell staff that audio is prioritized in video meetings, which can cut unnecessary hardware replacement requests.","url":"https://techcommunity.microsoft.com/t5/microsoft-teams-blog/making-microsoft-teams-more-responsive-reliable-and-ready-for/ba-p/4564205","prio":1,"kor":false,"tags":["TOOL","COLLAB"],"tool":"Microsoft Teams"},{"code":"SOFT","date":"2026-10-20","src":"Zoom Newsroom","title":"줌, 회의·전화·채팅 맥락을 다른 AI로 넘기는 '통합 컨텍스트 계층' 공개…대면 회의 기록 앱·대리 참석 기능도 예고","eTitle":"Zoom unveils a Unified Context Layer that carries meeting decisions into other AI tools, plus My Notes upgrades for in-person meetings","kSum":"줌은 2026년 10월 20일 연례 행사 줌토피아에서 회의·전화·채팅·컨택센터 대화와 회사 지식, 외부 업무 시스템을 묶어 '무엇이 논의·결정·배정됐는지'를 정리하는 '통합 컨텍스트 계층(Unified Context Layer)'을 발표했다. MCP 커넥터와 API로 Claude·ChatGPT·Codex 같은 다른 AI에서도 줌의 회의 맥락을 쓸 수 있고, 2026년 11월부터는 Claude·Codex에서 줌 회의·채팅·전화 작업을 실행할 수 있게 한다. 회의 기록 기능 'My Notes'에는 회의 요약을 줌 채팅·세일즈포스 등으로 보내는 워크플로(10월 예정), 대면 회의를 녹음·전사하는 독립 모바일 앱과 사용자 대신 회의에 들어가 개인별 전사·요약을 주는 'Follow Meeting'(12월 예정)이 추가된다. 구글 드라이브·원드라이브 등 40여 개 외부 앱을 함께 찾는 에이전트 검색과 여러 에이전트의 작업을 합쳐 사람에게 검토받는 'AI Agent Teams'는 바로 쓸 수 있으며, 요금제·가격은 밝히지 않았다.","eSum":"At its Zoomtopia conference on October 20, 2026, Zoom announced a Unified Context Layer that combines conversations from meetings, phone, chat and contact center with company knowledge and connected systems of record, organizing what was discussed, decided and assigned. Through MCP connectors and APIs, Zoom context can be used in other AI platforms including Claude, ChatGPT and Codex, and from November 2026 users can launch Zoom meeting, chat and phone workflows from Claude and Codex. My Notes gains workflows that send meeting summaries to Zoom Chat, Salesforce and other destinations (expected October), plus a standalone mobile app for recording in-person meetings and a Follow Meeting feature that attends meetings on the user's behalf and delivers personalized transcripts and summaries (expected December). Agentic search across Zoom and more than 40 third-party apps such as Google Drive and Microsoft OneDrive, and AI Agent Teams that combine parallel agents' work into one deliverable for human review, are available now; the announcement does not state plans or pricing.","kImp":"줌으로 외부 화상회의를 자주 하는 팀이라면 회의 요약을 업무 채팅방이나 업무 시스템으로 자동 전달하는 기능을 시험해 볼 만하지만, 녹음·대리 참석 기능은 상대방 동의와 회의 내용을 외부 AI로 보내는 범위를 먼저 사내 규정으로 정해 두어야 한다.","eImp":"Teams that hold many external video calls on Zoom could test sending meeting summaries automatically to team chat or business systems, but recording and attend-on-my-behalf features need internal rules first on participant consent and on how much meeting content may be passed to outside AI tools.","url":"https://news.zoom.com/zoomtopia-2026-ai/","prio":2,"kor":false,"tags":["TOOL","COLLAB","MTG"],"tool":"Zoom"},{"code":"SOFT","date":"2026-10-19","src":"Google Workspace Updates","title":"구글 미트 회의가 끝나면 채팅방에 요약·결정사항·담당자별 할 일 카드 자동 게시","eTitle":"Google Chat now posts automatic meeting recaps with decisions and owner-assigned action items","kSum":"구글은 2026년 10월 19일, 구글 미트에서 'Take notes for me(회의록 작성)'를 켠 회의가 끝나면 해당 회의의 구글 채팅 대화방에 회의 요약 카드를 자동으로 올리는 기능을 발표했다. 카드에는 주요 논의 요약, 핵심 결정, 담당자가 지정된 실행 항목, Gemini 회의록·녹화·전사 링크가 담긴다. Business Standard·Plus, Enterprise Standard·Plus, Frontline Plus 대상이며 Rapid Release 도메인은 10월 16일, Scheduled Release 도메인은 10월 27일부터 최대 15일에 걸쳐 적용된다. 호스트가 회의록 공유를 호스트·공동 호스트로 제한하면 카드가 올라가지 않고, 참가자가 카드를 지워도 회의록 문서는 드라이브에 남는다.","eSum":"On October 19, 2026, Google announced that when 'Take notes for me' is active in a Google Meet call that has an associated Google Chat conversation, a recap card is posted to that Chat space after the meeting. The card includes a summary of the main topics, key decisions, action items with named owners, and links to the Gemini notes document, recording and transcript. It is available on Business Standard and Plus, Enterprise Standard and Plus and Frontline Plus, rolling out from October 16 for Rapid Release and October 27 for Scheduled Release domains, with up to 15 days for visibility. No card is posted if the host limits notes sharing to hosts and co-hosts, and deleting a card leaves the notes document in Drive.","kImp":"회의 뒤 '누가 무엇을 언제까지'를 정리해 돌리는 일을 줄일 수 있지만, AI가 뽑은 담당자·기한이 맞는지 회의 주관자가 당일 확인하고, 외부 참석자가 있는 회의는 회의록 공유 범위를 미리 정해 두는 것이 좋다.","eImp":"This can take over the post-meeting 'who does what by when' message, but the meeting owner should check the AI-assigned owners and deadlines the same day, and set the notes-sharing scope in advance for meetings with external participants.","url":"https://workspaceupdates.googleblog.com/2026/10/follow-through-on-your-meeting-tasks-with-meeting-recaps-in-Google-Chat.html","prio":2,"kor":false,"tags":["TOOL","COLLAB","MTG"],"tool":"Google Chat"},{"code":"SOFT","date":"2026-10-15","src":"Computerworld","title":"코파일럿 요금 복잡해졌다…월정액에 더해 Cowork·일부 에이전트는 사용량 과금, 가트너 '지침 없으면 낭비 불가피'","eTitle":"Copilot pricing gets complicated as Cowork and some agents move to usage-based Copilot Credits","kSum":"컴퓨터월드는 2026년 10월 15일 분석 기사에서, 마이크로소프트 코파일럿이 사용자당 월 30달러(중소기업용 21달러) 정액제로 시작했지만 에이전트 확대로 요금 구조가 복잡해졌다고 짚었다. Researcher·Analyst 같은 에이전트는 기존 구독에 포함되지만 일부 Copilot Studio 에이전트와 Copilot Chat을 통한 에이전트는 크레딧당 0.01달러인 Copilot Credits로 과금되고, 새 홈 화면에서 채팅 옆에 놓인 Cowork도 모델·작업 복잡도에 따라 사용량 과금된다. 가트너가 IT 리더 186명을 조사한 결과 51%가 코파일럿 가치 입증을 3대 장애물로 꼽았고, 가치를 느낀 분야는 콘텐츠 생성(49%)·지식 검색(44%)이 에이전트 기반 업무 자동화(20%)보다 높았다. 가트너·퓨처럼 그룹 애널리스트들은 채팅과 Cowork 사용 기준 마련, 지출 한도·알림 설정, 숙련 사용자 대상 소규모 시범을 권했다.","eSum":"In an October 15, 2026 analysis, Computerworld said Microsoft Copilot pricing, which began as a flat $30 per user per month ($21 for small and midsize businesses), has grown complicated as Microsoft pushes agents. Researcher and Analyst agents are included in the subscription, but some Copilot Studio agents and agents used through Copilot Chat are billed in Copilot Credits at $0.01 per credit, and Cowork, now placed beside Chat in a new Home interface, is charged by usage depending on the model and task complexity. A Gartner survey of 186 IT leaders found 51% named proving Copilot's value a top-three barrier, with more value seen in content generation (49%) and knowledge search (44%) than in agentic workflow automation (20%). Analysts from Gartner and The Futurum Group advised setting guidance on when to use Chat versus Cowork, applying spending caps and alerts, and starting with small pilots of experienced users.","kImp":"코파일럿을 쓰는 조직이라면 일상 질문은 정액 범위의 채팅으로, 여러 단계 작업만 Cowork로 쓰는 기준을 정해 직원에게 알리고, 관리 화면에서 부서·개인별 지출 한도와 알림부터 설정해 두는 것이 좋다.","eImp":"Organizations using Copilot should tell staff to use flat-rate Chat for everyday questions and keep Cowork for multi-step work that justifies it, and set department and user spending limits and alerts in the admin tools before usage grows.","url":"https://www.computerworld.com/article/4235201/microsofts-agent-push-complicates-copilot-pricing.html","prio":2,"kor":false,"tags":["TOOL","AI"],"tool":"Microsoft 365 Copilot"},{"code":"SOFT","date":"2026-10-13","src":"Notion Releases","title":"노션 3.8, 외부 AI 에이전트가 노션 문서·업무표를 읽고 고치는 MCP 연결 지원…변경 이력 강화·팀즈 알림 연동","eTitle":"Notion 3.8 lets outside AI agents read and update workspace docs via MCP, upgrades version history and adds Microsoft Teams notifications","kSum":"노션은 2026년 10월 13일 '노션 3.8'을 내놓고, MCP를 지원하는 외부 AI 에이전트가 노션 워크스페이스의 맥락을 읽고 문서·업무 추적표를 고칠 수 있게 했다. 관리자는 누가 어떤 AI 도구를 연결했는지와 마지막 사용 시점을 보고 한 사람의 접근만 따로 끊을 수 있으며, 노션 검증 도구나 지정한 도구만 허용하도록 설정할 수 있다. 페이지·데이터베이스 변경 이력이 강화돼 수정 부분 강조, 작성자 표시, 이전 버전 복원이 가능해졌고, 데이터베이스 소유자가 사람·에이전트별로 열람·편집 가능한 항목(열)을 정하는 권한 기능도 추가됐다. 마이크로소프트 팀즈에서 노션 멘션·댓글·접근 요청을 받아 바로 답할 수 있고, Business·Enterprise 요금제에서는 ChatGPT Plus·Pro 구독으로 노션 안의 AI 사용량을 웃돈 없이 충당할 수 있다.","eSum":"On October 13, 2026, Notion released Notion 3.8, letting MCP-compatible AI agents read workspace context and update docs and task trackers. Admins can see who connected each AI tool and when it was last used, revoke one person's access without affecting others, and allow only Notion-verified tools or tools they choose. Version history now covers pages and databases with highlighted edits, attribution and one-click restore, and database owners can set which properties each person or agent can view or edit. Users can receive and reply to Notion mentions, comments and access requests in Microsoft Teams, and on Business and Enterprise plans a ChatGPT Plus or Pro subscription can cover AI usage in Notion with no markup.","kImp":"노션으로 팀 문서·업무 목록을 관리한다면 외부 AI 도구 연결을 허용 목록 방식으로 제한하고 연결 현황을 분기마다 점검하며, 비용·인사 정보 같은 민감한 열에는 열 권한을 걸어 두는 것이 좋다; 팀즈를 함께 쓰는 조직은 알림 연동으로 앱 전환을 줄일 수 있다.","eImp":"Teams that manage documents and task lists in Notion should limit outside AI tool connections to an allowlist, review connections every quarter and apply column permissions to sensitive fields such as costs or personnel data; organizations that also use Teams can cut app switching with the notification integration.","url":"https://www.notion.com/releases/2026-10-13","prio":2,"kor":false,"tags":["TOOL","COLLAB","SEC"],"tool":"Notion"},{"code":"SOFT","date":"2026-10-07","src":"Atlassian Blog","title":"아틀라시안, 컨플루언스·룸·지라 새 기능…영상 녹화로 AI에 업무 지시, 팀즈·슬랙 대화를 지라 업무로 전환","eTitle":"Atlassian's Teamwork Collection update: Loom recordings as agent briefs, a Jira app for Slack and Teams, and capacity planning views","kSum":"아틀라시안은 2026년 10월 7일 Team '26 유럽 행사에서 지라·컨플루언스·룸·로보를 묶은 '팀워크 컬렉션'의 새 기능을 발표했다. 룸(Loom) 영상의 말과 화면을 AI 에이전트가 실행할 작업 지시로 바꿔 지라 업무 항목이나 컨플루언스 슬라이드를 만들게 하는 'Record for Agent'(공개 베타)와 제목·요점을 자동으로 넣는 AI 오버레이(얼리 액세스)가 나왔다. 지라 앱은 슬랙·마이크로소프트 팀즈의 대화 스레드를 추적 가능한 지라 업무로 바꿔 에이전트나 동료에게 배정하고, 팀원별 업무량 분포를 보여 관리자가 재배분할 수 있는 개인 용량 계획 화면과 예산 차이·위험 점수를 계산하는 프로젝트 예산 기능도 더해진다. 컨플루언스는 구글 드라이브 등 외부 앱 콘텐츠를 동기화하는 폴더를 지원하며, 베타·얼리 액세스 항목 외 기능의 출시 시점과 가격은 밝히지 않았다.","eSum":"At Team '26 Europe on October 7, 2026, Atlassian announced updates to its Teamwork Collection of Jira, Confluence, Loom and Rovo. Record for Agent, in open beta, turns the spoken and on-screen content of a Loom video into a brief an agent can act on, such as creating Jira work items or Confluence slides, and AI overlays that add titles and key-point highlights are in early access. A Jira app for Slack and Microsoft Teams turns chat threads into tracked Jira work routed to an agent or teammate, and new Individual Capacity Planning views show workload distribution so managers can rebalance, alongside Project Budgeting that calculates budget variance and risk scores. Confluence gains Third-Party Folders that sync content from apps such as Google Drive; apart from the beta and early-access items, availability dates and pricing were not stated.","kImp":"채팅으로 오가는 요청이 많아 일이 새는 팀이라면 대화를 바로 업무 항목으로 바꿔 담당자를 정하는 방식을 시험해 볼 만하고, 팀원별 업무량 화면은 업무 배분 회의 자료로 쓸 수 있다; 외부 에이전트를 연결할 때는 사람 검토 단계를 반드시 켜 두는 것이 좋다.","eImp":"Teams that lose track of requests made in chat could test turning conversations directly into tracked work items with an owner, and the per-person workload view can support workload-allocation meetings; keep the human review step switched on when connecting outside agents.","url":"https://www.atlassian.com/blog/company-news/team26-europe-teamwork-collection","prio":1,"kor":false,"tags":["TOOL","COLLAB","AI"],"tool":"Atlassian Teamwork Collection"},{"code":"SOFT","date":"2026-10-07","src":"Computerworld","title":"시스코 웹엑스, 대화방에 AI 에이전트를 '팀원'으로…Claude 에이전트 연동, 10개 언어 실시간 통역은 11월 정식 출시 예정","eTitle":"Cisco brings collaborative agents and Claude into Webex chats, with a ten-language translator agent planned for November","kSum":"컴퓨터월드는 2026년 10월 7일, 시스코가 WebexOne 행사에서 웹엑스 대화방(스페이스)에 AI 에이전트를 @멘션해 회의 일정 조율·메모·업무 추적을 맡기는 '협업 에이전트'를 발표했다고 보도했다. 앤트로픽의 Claude Managed Agents와 오픈AI 에이전트를 팀원처럼 그룹 대화에 추가할 수 있고, 통화 중에는 AI 어시스턴트 측면 창으로 에이전트를 부를 수 있으며, 우선순위·다가오는 회의·후속 조치를 보여 주는 개인 첫 화면도 생긴다. 웹엑스 앱과 데스크폰에서 10개 언어를 실시간 통역하는 번역 에이전트는 제한 제공 중으로 11월 정식 출시 예정이고, 발표자에게 속도·어조·단어 선택을 조언하는 Vidcast AI 코치는 바로 쓸 수 있으며, 통화를 선별하는 개인 에이전트는 2027년 1분기에 나온다. 일부 AI 기능은 웹엑스 스위트(사용자당 월 25달러)·엔터프라이즈 요금제에 포함되지만 번역·협업 에이전트 같은 고급 기능은 가격 미공개의 별도 'Enhanced AI' 부가 상품이 필요하다.","eSum":"Computerworld reported on October 7, 2026, that Cisco announced at WebexOne collaborative agents that users can @mention in Webex spaces to schedule meetings, take notes and track tasks. Anthropic's Claude Managed Agents and OpenAI's agents can be added to group conversations as team members, agents are reachable during calls through the AI Assistant side panel, and a personalized landing page highlights priorities, upcoming meetings and suggested follow-ups. A Translator agent offering real-time translation in ten languages in the Webex app and on desk phones is in controlled availability with general release planned for November, an AI Coach for Vidcast that gives presenters feedback on pacing, tone and word choice is available now, and Personal Agents that screen calls arrive in Q1 2027. Some AI features are included in Webex Suite ($25 per user per month) and Enterprise tiers, but advanced features such as the Translator and collaborative agents require a new Enhanced AI add-on with undisclosed pricing.","kImp":"웹엑스로 외부 회의를 하는 조직이라면 번역 에이전트가 한국어를 지원하는지와 사용자당 월 통역 시간 한도를 먼저 확인하고, 대화방에 외부 AI 에이전트를 들일 때는 그 에이전트가 볼 수 있는 대화·파일 범위부터 정해 두는 것이 좋다.","eImp":"Organizations that hold external meetings on Webex should first check whether the Translator agent supports Korean and how many translation minutes each user gets per month, and decide which conversations and files an outside AI agent may see before adding it to a space.","url":"https://www.computerworld.com/article/4231779/cisco-brings-collaborative-agents-and-claude-into-webex-chats.html","prio":1,"kor":false,"tags":["TOOL","COLLAB","AI"],"tool":"Cisco Webex"},{"code":"SOFT","date":"2026-10-05","src":"MSSP Alert","title":"MS 365 코파일럿 비즈니스, 12월 1일부터 신규 CSP 구매에 사용량 과금 기본 적용…사용자당 월 4,000 크레딧 기본 한도","eTitle":"Microsoft delays default usage-based billing for new Microsoft 365 Copilot Business purchases to December 1, with a 4,000-credit default cap","kSum":"MSSP 얼러트는 2026년 10월 5일(CRN 보도 인용), 마이크로소프트가 클라우드 솔루션 공급자(CSP) 채널로 새로 구매하는 '마이크로소프트 365 코파일럿 비즈니스'에 사용량 기반 과금을 기본으로 켜는 시점을 11월 2일에서 12월 1일로 미뤘다고 보도했다. 코파일럿 비즈니스 라이선스에는 사용자당 월 4,000 Copilot Credits의 조정 가능한 기본 지출 한도가 걸리고, 신규 구매 시 애저 구독이 자동으로 설정되며, 파트너가 지출 한도·접근 권한·결제 방식을 관리하고 사용량 요금은 CSP 청구서로 청구된다. 사용량 과금은 지원 시장부터 적용되고 호주·벨기에·독일은 제외되며, 'Copilot in 30' 체험은 신규 고객으로 제한된다. 크레딧 단가, 크레딧을 쓰는 기능, 지원 시장에 한국이 포함되는지는 기사에 나오지 않았다.","eSum":"MSSP Alert reported on October 5, 2026, citing CRN, that Microsoft delayed from November 2 to December 1 its plan to turn on usage-based billing by default for new Microsoft 365 Copilot Business subscriptions bought through the Cloud Solution Provider (CSP) program. Copilot Business licenses will carry an adjustable default spending limit of 4,000 Copilot Credits per user per month, new purchases automatically get an Azure subscription set up, partners manage spending limits, access controls and billing methods, and consumption charges flow through CSP invoices. Usage-based billing will first roll out in supported markets, excluding Australia, Belgium and Germany, and the 'Copilot in 30' trial is now limited to new customers. The article does not state the price per credit, which features consume credits or whether Korea is among the supported markets.","kImp":"CSP 파트너를 통해 코파일럿을 새로 사거나 늘릴 계획이라면 12월 1일 이전에 파트너와 기본 지출 한도(사용자당 월 4,000 크레딧)를 그대로 둘지 낮출지, 어떤 기능이 추가 요금을 만드는지, 청구서에 어떻게 표시되는지를 먼저 확인해 두는 것이 좋다.","eImp":"If you plan to buy or add Copilot through a CSP partner, confirm with the partner before December 1 whether to keep or lower the default spending limit of 4,000 credits per user per month, which features generate extra charges and how they will appear on the invoice.","url":"https://www.msspalert.com/brief/microsoft-delays-usage-based-billing-for-copilot-business","prio":2,"kor":false,"tags":["TOOL","AI","POL"],"tool":"Microsoft 365 Copilot Business"},{"code":"SOFT","date":"2026-09-30","src":"Computerworld","title":"오픈AI, ChatGPT에 공동 문서 편집기 'Pages'와 팀 작업 공간 'Space' 추가…MS·구글 오피스에 도전장","eTitle":"OpenAI adds a collaborative document editor, Pages, and a shared team hub, Space, to ChatGPT","kSum":"컴퓨터월드는 2026년 9월 30일(10월 2일 가격 정보 갱신), 오픈AI가 DevDay에서 ChatGPT 안의 공동 문서 편집기 'Pages'와 팀 작업 공간 'Space'를 공개했다고 보도했다. Pages는 노션과 비슷한 블록 구조로 하위 페이지·링크·선택 문구 댓글을 지원하고 내장 AI가 글·이미지·인터랙티브 시각화를 만들며, Space는 문서·업로드 파일·페이지·슬라이드·스프레드시트를 담는 팀 공용 공간으로 기존 Library를 대체한다(공동 슬라이드는 '곧 출시'). ChatGPT Pro·Business·Enterprise 고객이 웹·데스크톱 앱에서 별도 요금 없이 쓸 수 있고 모바일에서는 읽기·공유만 되며, AI 생성·편집은 기존 사용 한도를 따른다. 애널리스트들은 팀 단위로 도입해야 하고 기존 오피스에 쌓인 콘텐츠·업무 흐름이 커 기업이 쉽게 갈아타지는 않을 것이라고 봤다.","eSum":"Computerworld reported on September 30, 2026, updated October 2 with pricing information, that OpenAI unveiled Pages, a collaborative document editor in ChatGPT, and Space, a shared home for team work, at its DevDay event. Pages uses a Notion-like block layout with sub-pages, links and comments on selected text, and its embedded assistant can generate text, images and interactive visualizations, while Space stores documents, uploaded files, pages, slides and spreadsheets and replaces the Library, with collaborative slides 'coming soon'. Space and Pages are available to ChatGPT Pro, Business and Enterprise customers on the web and desktop app at no separate fee, with read-and-share only on mobile, and AI-generated content counts against existing usage limits. Analysts said teams rather than individuals must adopt it and that incumbents' years of shared content and workflows make switching suites unlikely.","kImp":"이미 마이크로소프트 365나 구글 워크스페이스로 문서를 관리하는 조직이라면 갈아타기보다 'AI 초안 작성 공간'으로서 시범 활용을 검토하되, 공유 공간에 올린 파일을 팀원이 AI로 다시 가공할 수 있으므로 공유 권한과 사내 문서 보관 위치 규정부터 정해야 한다.","eImp":"Organizations that already manage documents in Microsoft 365 or Google Workspace should consider piloting it as an AI drafting space rather than switching, but because teammates can rework shared files with AI, set sharing permissions and rules on where company documents are stored first.","url":"https://www.computerworld.com/article/4229031/openai-takes-on-microsoft-and-google-with-office-productivity-push.html","prio":2,"kor":false,"tags":["TOOL","COLLAB","AI"],"tool":"ChatGPT"},{"code":"SOFT","date":"2026-09-29","src":"요즘IT","title":"클로드로 회사 PPT 템플릿을 '스킬'로 저장하는 4단계…초안·폰트·레퍼런스 준비→2쪽 샘플→수정→스킬화로 같은 톤 반복 사용","eTitle":"Four Steps to Save a Company Slide Template as a Claude Skill: Prepare Draft, Fonts and References, Test Two Sample Pages, Revise, Then Turn the Design Into a Reusable Skill","kSum":"요즘IT에 실린 디자이너 디논의 글은 감마·제미나이보다 만족스러웠다는 클로드로 PPT 디자인을 만든 뒤 이를 '스킬'로 저장해 다른 사람도 같은 톤앤매너로 .pptx를 만들게 하는 방법을 4단계로 소개했다. 페이지별 내용이 담긴 초안·폰트 파일·레퍼런스 이미지를 준비하고, 토큰을 아끼려 2쪽 샘플부터 만들며 색상 코드·폰트·모서리 반경·로고 자리를 프롬프트에 지정하고, 수정 요청을 반영한 뒤 색상·폰트·여백 규칙과 로고를 담은 스킬을 만들어 입력창에서 '/'로 불러 쓰는 방식이다. 유료 구독이 필수는 아니지만 수정 요청이 3~4회를 넘으면 무료 사용량이 바닥날 수 있고, 글자 간격·도형 크기 같은 세부 조정은 여전히 파워포인트에서 사람이 손봐야 한다고 했다.","eSum":"In a Yozm IT how-to, designer Dinon explains how to build slide designs in Claude, which the author found more satisfying than Gamma or Gemini, and save them as a 'skill' so colleagues can produce .pptx files in the same look. The four steps are preparing a page-by-page draft, font files and reference images; generating a two-page sample first to save tokens while specifying colour codes, fonts, corner radius and logo space; applying revisions; and then creating a skill containing the colour, font and spacing rules plus the logo, called up with '/' in the input box. A paid plan is not required, but more than three or four revision requests can exhaust free usage, and fine adjustments such as letter spacing and shape sizes still need hand-editing in PowerPoint.","kImp":"보고서·제안서 PPT를 자주 만드는 팀이라면 회사 표준 양식 하나를 스킬로 만들어 공유하면 디자인 맞추는 시간을 줄일 수 있지만, 초안에 고객·계약 정보가 들어간다면 회사가 승인한 계정과 데이터 보관 조건에서만 써야 한다.","eImp":"Teams that often build report or proposal decks could save one company-standard template as a shared skill to cut formatting time, but if drafts contain client or contract details they should only be used under company-approved accounts and data-retention terms.","url":"https://yozm.wishket.com/magazine/detail/3967/","prio":1,"kor":true,"tags":["TOOL","AI","WRT"],"tool":"Claude"},{"code":"SOFT","date":"2026-09-23","src":"Microsoft Learn (Microsoft 365 Copilot release notes)","title":"마이크로소프트 365 코파일럿, 아웃룩에서 말로 메일 삭제·이동·분류·규칙 설정…회의는 채팅·전사 내용으로 검색","eTitle":"Microsoft 365 Copilot adds natural-language Outlook triage, meeting search across chats and transcripts, and a Planner chat","kSum":"마이크로소프트는 2026년 9월 23일 마이크로소프트 365 코파일럿 릴리스 노트에서, 아웃룩의 코파일럿 채팅에 '지난주 안 읽은 뉴스레터 삭제', '특정 거래처의 인보이스 메일을 재무 폴더로 이동' 같은 자연어 명령을 내려 메일 삭제·이동·복사·분류와 받은편지함 규칙·폴더 생성까지 할 수 있게 했다고 밝혔다. 메일 5통을 넘게 처리하거나 받은편지함 규칙을 바꿀 때는 먼저 확인을 요청하며, 클래식·새 아웃룩(윈도), 웹, 맥, 모바일에서 모두 지원된다. 회의는 본문·채팅·전사 내용의 주제나 키워드로 찾을 수 있게 됐고(전사 검색은 최근 2개월), 플래너에는 '이번 주 마감 업무 보여 줘'처럼 묻고 업무를 갱신하는 Planner Agent 채팅이, 폼즈에는 설문 개선·초대장 작성·응답 분석을 돕는 코파일럿 창(마이크로소프트 365 코파일럿 라이선스 사용자 대상)이 들어갔다.","eSum":"In its Microsoft 365 Copilot release notes dated September 23, 2026, Microsoft said users can now give natural-language commands in Copilot Chat in Outlook, such as deleting last week's unread newsletters or moving a supplier's invoice emails to a Finance folder, to delete, move, copy and categorize messages and to create and manage inbox rules and folders. Copilot asks for confirmation before acting on more than five emails or changing inbox rules, and the feature works in classic and new Outlook for Windows, Outlook on the web, Outlook for Mac and Outlook mobile. Copilot can also find meetings by topics or keywords in the meeting body, chat and transcripts, with transcript search covering the past two months, while Planner gains a Planner Agent chat for questions such as 'show me tasks due this week' and in-plan updates, and Microsoft Forms gets a Copilot pane for improving forms, drafting invitations and analyzing responses for Microsoft 365 Copilot licensed business users.","kImp":"하루 수십 통의 메일을 처리하는 직원이라면 뉴스레터·자동 알림처럼 위험이 낮은 메일부터 자연어 정리 명령을 써 보고, 일괄 삭제·규칙 변경 전 확인 창을 꼼꼼히 읽는 습관을 들이는 것이 좋다; 거래처·선박별 폴더 규칙을 만들 때도 시간을 줄일 수 있다.","eImp":"Staff who handle dozens of emails a day could start with low-risk mail such as newsletters and automated alerts, and make a habit of reading the confirmation prompt carefully before bulk deletions or rule changes; it can also save time when setting up folder rules by client or vessel.","url":"https://learn.microsoft.com/en-us/copilot/microsoft-365/release-notes","prio":2,"kor":false,"tags":["TOOL","AI","TIME"],"tool":"Microsoft 365 Copilot"},{"code":"SOFT","date":"2026-09-17","src":"지디넷코리아","title":"협업툴 플로우, 국내 최초 챗GPT·클로드 공식 앱 등록…\"이번 주 지연 업무 뭐지?\" 물으면 답하고 담당자 지정까지","eTitle":"Collaboration Tool Flow Becomes the First Korean Work App Listed in Both ChatGPT and Claude, Answering Questions on Delayed Tasks and Assigning Work From the Chat Window","kSum":"마드라스체크는 9월 17일 협업툴 플로우가 오픈AI 챗GPT와 앤트로픽 클로드에 동시에 공식 앱으로 등록됐다고 밝혔으며, 국내 협업툴로는 처음이라고 했다. 사용자는 대화창에서 '이번 주 우리 팀에서 지연된 업무가 뭐지?'처럼 묻거나 특정 동료에게 업무를 배정하라고 지시할 수 있고, 프로젝트·업무·게시글·일정·위키·조직도 등 39개 기능을 조회·생성·수정할 수 있다. MCP 기반 연동으로 AI는 사용자가 플로우에서 볼 권한이 있는 데이터만 조회하며, 6월 출시 뒤 약 3개월 동안 AI 업무 호출이 누적 100만 건을 넘었고 2,900개 회사·7,500명이 AI로 플로우를 쓰고 있다고 회사는 밝혔다.","eSum":"Madras Check said on 17 September that its collaboration tool Flow is now an official app in both OpenAI's ChatGPT and Anthropic's Claude, which it says is a first for a Korean collaboration tool. Users can ask questions such as which of their team's tasks are delayed this week, or tell the AI to assign a task to a colleague, across 39 functions covering projects, tasks, posts, schedules, the wiki and the org chart. The MCP-based link only lets the AI see data the user can already access in Flow, and the company says AI-initiated task calls passed 1 million in about three months, with 2,900 companies and 7,500 people using Flow through AI.","kImp":"팀 업무를 협업툴로 관리하는 조직이라면 주간 회의 전 '지연 업무·이번 주 일정' 확인을 AI 대화로 돌려 볼 수 있지만, 외부 AI 서비스와 사내 업무 데이터를 연결하기 전 IT·보안 담당과 접근 권한 범위와 데이터 처리 조건을 먼저 확인해야 한다.","eImp":"Teams that manage work in a collaboration tool could try checking delayed tasks and the week's schedule through an AI chat before weekly meetings, but should first confirm access scopes and data-handling terms with IT and security before linking an external AI service to company work data.","url":"https://zdnet.co.kr/view/?no=20260917135940","prio":2,"kor":true,"tags":["TOOL","AI","COLLAB"],"tool":"Flow"}]},{"code":"HRM","kTitle":"HR 제도·동향","eTitle":"HR practice and trends","items":[{"code":"HRM","date":"2026-10-28","src":"여성경제신문","title":"\"동료 육아휴직으로 일 늘었다\" 47.8%, 그중 70.5%는 보상 없어…정부 업무분담지원금은 사업장 12.4%만 적극 활용","eTitle":"47.8% of Korean Workers Say a Colleague's Parental Leave Increased Their Workload and 70.5% of Them Got No Compensation, While Only 12.4% of Workplaces Actively Use the Government's Work-Sharing Subsidy","kSum":"직장갑질119가 글로벌리서치에 의뢰해 9월 1~7일 직장인 1,000명을 조사한 결과 47.8%가 동료의 출산휴가·육아휴직·육아기 근로시간 단축으로 업무가 늘었다고 답했고, 이 중 별도 보상을 받은 사람은 29.5%에 그쳤다. 동료 업무를 나눠 맡은 직원에게 회사가 수당을 주면 정부가 지원하는 업무분담지원금(30인 미만 월 최대 60만 원, 30인 이상 40만 원)을 아는 사람은 37%였고, 회사가 적극 안내·활용한다는 응답은 12.4%뿐이었다. 원하는 보상은 업무대체수당 신설·확대(27.5%), 성과급·인사평가 혜택(24.8%), 대체 기간에 비례한 휴식(19.7%) 순이었으며, 2026년 대체인력지원금은 30인 미만 월 140만 원·30인 이상 130만 원 한도로 대체 기간 전액 지급으로 바뀌었다.","eSum":"A 1-7 September survey of 1,000 workers by Global Research for the civic group Workplace Gapjil 119 found 47.8% said a colleague's maternity or parental leave or reduced childcare hours increased their workload, and only 29.5% of them received any compensation. Just 37% knew of the government's work-sharing subsidy, which reimburses firms that pay staff covering a colleague's work up to 600,000 won a month at workplaces under 30 employees and 400,000 won at larger ones, and only 12.4% said their employer actively promoted and used it. Respondents most wanted a new or larger cover allowance (27.5%), bonuses or appraisal credit (24.8%) and rest time proportional to the cover period (19.7%); the 2026 replacement-staff subsidy now pays up to 1.4 million won a month (1.3 million at larger firms) for the whole replacement period.","kImp":"팀원이 육아휴직에 들어가면 남은 업무를 누가 얼마나 맡는지 문서로 정해 평가에 반영하고, 인사 담당과 함께 업무분담지원금·대체인력지원금 신청 요건을 확인해 '동료 희생'으로 굴러가지 않게 하는 것이 팀장의 몫이다.","eImp":"When a team member goes on parental leave, the team leader should document who covers which work and how much, reflect it in appraisals, and check with HR whether the work-sharing and replacement-staff subsidies apply, so the system does not run on colleagues' sacrifice.","url":"https://www.womaneconomy.co.kr/news/articleView.html?idxno=260282","prio":2,"kor":true,"tags":["POL","RET","PERF"],"tool":""},{"code":"HRM","date":"2026-10-27","src":"DBR","title":"DBR 스페셜 리포트 'AI 위임 시대, 성과 평가 어떻게 바꿀까' — 산출량만 보면 AI 결과를 검증한 직원이 손해, 도입 단계별 지표·사람과 AI 성과 분리·AI 없이 점검하는 역량 평가를","eTitle":"DBR Special Report: Rethinking Performance Reviews for AI Delegation - Output Counts Penalise Staff Who Check AI Work, So Use Stage-Based Measures, Separate Human and AI Results and Assess Checking Without AI","kSum":"동국대 이중학 교수는 DBR 11월 1호(10월 27일 발행) 스페셜 리포트에서 AI 도입은 늘었지만 성과의 증거는 드물다며, 문제는 기술이 아니라 AI 이전의 잣대로 AI 이후의 일을 평가하는 데 있다고 짚었다. 맥킨지 2025년 조사에서 AI를 한 개 이상 업무에 쓰는 기업은 열에 아홉이지만 이익에 의미 있게 기여했다는 곳은 6% 안팎이었고, 한국은행 2026년 6월 분석에서는 AI로 주당 약 1.5시간(4% 안팎)을 아꼈지만 업무 처리량 증가와의 상관은 0이었다. 그는 도입 초기에는 즉각적 재무 성과 대신 재작업률·업무 품질·재설계 실행률을 재고, AI 에이전트·개인·사람과 AI 결합 성과를 구분하되 에이전트 성과는 반드시 사람의 책임과 연결하며, 첫해에는 기록과 별도 포상으로 인정하고 AI 없이 점검·설명하는 역량을 평가에 넣으라고 제안했다(구독 기사, 공개된 앞부분 기준).","eSum":"In DBR's 1st November issue (published 27 October), Dongguk University professor Lee Jung-hak argues that AI adoption is spreading but evidence of results is scarce because work done with AI is still judged by pre-AI yardsticks. A 2025 McKinsey survey found about nine in ten firms use AI in at least one function but only around 6% report a meaningful profit contribution, and a June 2026 Bank of Korea analysis found AI saved about 1.5 hours a week (around 4%) with zero correlation to higher work throughput. He proposes measuring rework rates, work quality and redesign progress rather than immediate financial returns in the early stage; separating the performance of AI agents, individuals and human-AI combinations while always tying agent results to a person's accountability; recognising contributions through records and separate awards in the first year; and assessing people's ability to check and explain work without AI (subscriber article; summary based on the free opening section).","kImp":"보고서·자료 작성에 AI를 쓰기 시작한 팀이라면 산출 건수보다 재작업률과 오류를 잡아낸 검증 행동을 평가에 반영하고, 업무별로 'AI가 만든 결과물의 책임자'를 정해 두는 것이 좋다. 도입 첫해에는 업무 재설계 시도를 기록으로 남겨 따로 인정하는 방식도 고려할 만하다.","eImp":"Teams starting to use AI for reports and documents could factor rework rates and the verification work that catches errors into appraisals, rather than output volume, and name for each task who is accountable for AI-generated results. In the first year, logging attempts to redesign work and recognising them separately is also worth considering.","url":"https://dbr.donga.com/article/view/1101/article_no/12311","prio":2,"kor":true,"tags":["PERF","AI","WR"],"tool":""},{"code":"HRM","date":"2026-10-27","src":"Harvard Business Review","title":"HBR 연구: 관리자는 순위를 잘못 읽는다… 8개 실험·4,400여 명, 상대 위치가 같아도 '짧은 목록'의 상위권을 더 선호해 채용·보상이 왜곡된다","eTitle":"HBR Research: Managers Misread Rankings, Favouring Candidates From Shorter Lists Even at Equal or Worse Relative Standing, Across Eight Experiments With Over 4,400 Participants","kSum":"HBR이 2026년 10월 27일 실은 재키 실버먼(밴더빌트대)·우리 바르네아(보코니대)·앨리스 문(조지타운대)의 연구는 8개 실험(참가자 4,400명 이상)에서, 크기가 다른 집단의 순위를 비교할 때 사람들이 상대적 위치가 같거나 오히려 나쁜데도 짧은 목록에서 나온 후보·제품을 더 선호한다는 사실을 확인했다. 1등과 얼마나 가까운지에만 주목하고 몇 명 가운데의 순위인지는 충분히 따지지 않기 때문이다(예: 부서 12명 중 3등과 24명 중 6등). 연구진은 채용·보상 같은 결정에서 이런 왜곡을 줄이려면 순위 대신 백분위를 쓰고 몇 명을 앞섰는지를 함께 보여 주라고 권했다. (구독 기사, 공개된 앞부분 기준)","eSum":"In a Harvard Business Review article published on 27 October 2026, Jackie Silverman of Vanderbilt, Uri Barnea of Bocconi and Alice Moon of Georgetown report eight experiments with more than 4,400 participants showing that when people compare options ranked within groups of different sizes, they favour candidates and products from shorter lists even when their relative standing is equal or worse. People focus on closeness to first place and give too little weight to how many options were ranked, as in the case of a candidate third of 12 versus one sixth of 24. The authors suggest reporting percentiles and highlighting how many alternatives an option outperformed to keep rankings from skewing hiring and rewards. (Subscription article; based on the publicly visible opening section.)","kImp":"부서별 평가 결과를 모아 승진·포상 후보를 비교할 때 '부서 내 몇 등'만 올리지 말고 부서 인원과 백분위를 함께 적어야 인원이 많은 부서의 직원이 불리해지지 않는다.","eImp":"When departmental appraisal results are pooled to compare promotion or award candidates, listing each person's percentile and department size rather than just their rank keeps staff in larger departments from being disadvantaged.","url":"https://hbr.org/2026/10/why-managers-misread-rankings","prio":2,"kor":false,"tags":["PERF","RET","DATA"],"tool":""},{"code":"HRM","date":"2026-10-27","src":"경북도민일보","title":"주4.5일제 찬성 69.4%지만 \"임금 줄면 반대\" 55.6%…1,000인 이상 기업 84.2% vs 5인 미만 48.2% 찬성으로 온도차","eTitle":"Survey Finds 69.4% of Koreans Back a 4.5-Day Week but 55.6% Would Oppose It if Pay Fell, With Support at 84.2% in Firms of 1,000-Plus Staff Against 48.2% in Firms Under Five","kSum":"김위상 국민의힘 의원이 피앰아이(PMI)에 의뢰해 9월 29~30일 전국 20세 이상 직장인·자영업자 800명을 조사한 결과 주4.5일제 찬성은 69.4%였지만 임금이 줄면 반대한다는 응답이 55.6%였고, 임금 삭감 시 찬성은 35.8%에 그쳤다. 1,000인 이상 기업 종사자는 84.2%가 찬성한 반면 5인 미만 사업장은 48.2%였으며, 현재 직장에서 도입이 가능하다는 응답은 53.8%였다. 도입이 어려운 이유는 업종 특성(38.8%), 매출 감소·인건비 상승(19.4%), 대체인력 문제(16.3%) 순이었고, 선호하는 방식은 기업·업종별 자율 도입(26.8%), 법에 따른 단계적 도입(24.4%) 등으로 갈렸다.","eSum":"A survey of 800 workers and self-employed adults conducted by PMI on 29-30 September for People Power Party lawmaker Kim Wi-sang found 69.4% support a 4.5-day week, but 55.6% would oppose it if pay were cut and only 35.8% back it with lower pay. Support was 84.2% among staff of firms with 1,000 or more employees against 48.2% at workplaces with fewer than five, and 53.8% said it is feasible at their current workplace. The main obstacles cited were the nature of the industry (38.8%), lower sales and higher labour costs (19.4%) and finding cover staff (16.3%), and preferences split between voluntary adoption by firm or industry (26.8%) and phased legal introduction (24.4%).","kImp":"근로시간 단축 논의가 본격화되기 전에 팀별로 '대체인력 없이도 돌아가는 업무'와 '반드시 사람이 붙어 있어야 하는 업무'(당직·비상 대응 등)를 미리 나눠 보면, 제도 도입 때 현실적인 운영안을 빨리 만들 수 있다.","eImp":"Before shorter-hours schemes arrive, each team can sort its work into tasks that run without cover and tasks that always need someone available, such as duty and emergency response, so a realistic rota can be drawn up quickly when a scheme is introduced.","url":"https://www.hidomin.com/news/articleView.html?idxno=726611","prio":2,"kor":true,"tags":["POL","WR"],"tool":""},{"code":"HRM","date":"2026-10-26","src":"HR Dive","title":"모호한 채용공고는 지원자를 쫓는다: 미국 공고 약 140만 건 분석, 조회만 되고 지원 0건인 공고는 '의욕적인·성실한' 같은 성격 표현이 많아","eTitle":"Vague Job Postings Draw Fewer Applicants: An Analysis of 1.4 Million US Postings Finds 'Zero-Apply' Ads Lean on Trait Words Rather Than Checkable Requirements","kSum":"HR Dive가 2026년 10월 26일 보도한 구직 플랫폼 잡리즈(JobLeads)의 분석(4~6월 미국 채용공고 약 140만 건)에 따르면, 조회는 되지만 지원자가 한 명도 없는 '제로 지원' 공고는 다른 공고와 연봉 중간값·요구 기술이 비슷했지만 '의욕적인', '성실한', '지시를 잘 따르는' 같은 성격 표현을 더 많이 썼다. HR 직무 공고는 조회만 되고 지원이 없을 가능성이 기준보다 28% 높았고 재무 직무는 25% 낮았으며, 노트북·스마트폰 같은 장비를 강조한 공고도 성과가 나빴다. 보고서는 문제가 '기준이 너무 높아서가 아니라 보이는 기준이 아예 없어서'라며, 성격 대신 확인 가능한 요건과 실제로 쓰는 기술·시스템, 초기 성공 기준을 적으라고 권했다.","eSum":"HR Dive reported on 26 October 2026 on a JobLeads analysis of nearly 1.4 million US job postings from April to June, which found that 'zero-apply' postings, which get clicks but no applicants, offered similar median salaries and skill requirements but used more trait words such as 'motivated', 'hardworking' and 'following directions'. HR jobs were 28% more likely than the baseline to be clicked without applications, finance roles 25% less likely, and postings emphasising equipment such as laptops or smartphones also performed poorly. The report argues the problem is not that the bar is too high but that there is no visible bar, and recommends replacing trait language with checkable requirements, the systems a new hire will use and what early success looks like.","kImp":"채용공고를 쓸 때 '성실하고 책임감 있는 분' 같은 문구 대신 실제로 쓰는 업무 시스템, 입사 후 첫 3개월 동안 맡을 일과 성공 기준을 구체적으로 적으면 지원자가 스스로 적합성을 판단하기 쉬워진다.","eImp":"Job ads should swap phrases like 'diligent and responsible' for the actual systems the role uses, the work the hire will take on in the first three months and how success will be judged, so candidates can assess their own fit.","url":"https://www.hrdive.com/news/vague-job-postings-get-fewer-applicants/872770/","prio":1,"kor":false,"tags":["RET","WRT"],"tool":""},{"code":"HRM","date":"2026-10-23","src":"HR Insight","title":"직원 극단적 선택, 회사 책임은 ‘일이 힘들었나’가 아니라 ‘위험을 알 수 있었나’로 갈린다 — 산재 인정 기준과 판례 3건","eTitle":"Employee Suicide and Employer Liability: Courts Ask Whether the Company Knew or Could Have Known, Not Whether the Work Was Hard","kSum":"김경락 대상노무법인 대표 공인노무사는 산재보험법상 자해 사망은 원칙적으로 업무상 재해가 아니지만 업무상 정신질환 치료 중이거나 업무상 사유로 인한 정신적 이상 상태와 상당인과관계가 인정되면 치료 이력이 없어도 인정되며, 근로복지공단은 증상이 처음 나타난 시점의 약 6개월 전부터 인사·근태·괴롭힘 신고·징계 기록을 조사한다고 설명했다. 민사상 안전배려의무 위반은 회사가 위험을 알았거나 알 수 있었는데도 조치하지 않았는지로 판단되는데, 회사가 우울감 호소를 알지 못한 사건과 우울증을 안 뒤 유급병가·무급휴직·복직을 거듭 허용한 사건은 회사 과실이 부정됐다. 반면 직원 손등의 자해 흔적이 목격돼 상급자에게 보고됐는데도 별도 조치가 없었던 사건은 과도한 업무 강도와 ADHD 진단 고지까지 더해 예측 가능성이 인정돼 위자료 배상 책임이 인정됐고, 사건 뒤 임의로 고치거나 추측으로 쓴 기록은 회사에 유리하게 쓰이기 어렵다고 지적했다(구독 기사로 후반부 비공개).","eSum":"Labour attorney Kim Kyung-rak explains that under Korea's industrial accident insurance law a self-inflicted death is not normally an occupational injury, but it is recognised where the worker was being treated for a work-related mental illness or where a work-related mental disorder is causally linked, even without prior treatment, and the state compensation agency examines personnel, attendance, harassment-complaint and disciplinary records from about six months before symptoms first appeared. Civil liability for breach of the duty of care turns on whether the employer knew or could have known of the risk and failed to act: claims failed where the company was unaware of the employee's low mood and where it repeatedly granted paid sick leave, unpaid leave and reinstatement after learning of depression. Damages were awarded where self-harm marks on an employee's hand were seen and reported to a senior manager but nothing was done, given heavy workload and a disclosed ADHD diagnosis, and records altered or written from guesswork after the event carry little weight (subscriber article; later part not public).","kImp":"직원이 우울감을 호소하거나 위험 신호가 보일 때 팀장이 인사 담당자에게 알리고 상담 연결·업무 조정·휴직 안내 같은 조치를 그때그때 기록하는 흐름이 실제로 작동하는지 점검해 볼 만하다. 사후에 고치거나 추측으로 쓴 기록은 인정받기 어려우므로 면담 내용은 당일 사실 위주로 남기는 것이 좋다.","eImp":"Check that when an employee reports low mood or shows warning signs, the team leader alerts HR and each step, such as counselling referral, workload adjustment or leave guidance, is recorded at the time. Records altered or written from guesswork afterwards carry little weight, so note conversations factually on the same day.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=112&bi_pidx=39657","prio":2,"kor":true,"tags":["WELL","POL"],"tool":""},{"code":"HRM","date":"2026-10-23","src":"HR Insight","title":"한국건강가정진흥원 \"가족친화제도는 신청 없이 쓰게 하고 팀장 판단이 활용 좌우\"…올해부터 가족친화인증에 1인 가구·부모 돌봄 지원도 반영","eTitle":"Korea's Family Support Agency Says Family-Friendly Policies Should Work Without Applications and Depend on Team Leaders, as Its Certification Now Also Counts Support for Single-Person Households and Elder Care","kSum":"박구연 한국건강가정진흥원 이사장은 HR Insight 인터뷰에서 일·가정 양립 제도가 실제로 쓰이려면 출산휴가 뒤 육아휴직으로 자동 전환하는 식의 '신청 없는 구조', 업무 공백을 개인에게 떠넘기지 않는 대체인력·분담 기준, 정시 퇴근·불필요한 회의 축소 같은 일하는 방식 변화가 필요하다고 말했다. 팀장 등 중간관리자의 판단이 제도 활용을 좌우하므로 제도 이용자가 평가에서 불이익을 받지 않게 관리해야 하며, 가족돌봄 휴직·휴가와 가족돌봄 근로시간 단축 등 부모 부양까지 돌봄 범위를 넓혀야 한다고 했다. 올해부터 가족친화인증 심사에 1인 가구·무자녀·한부모·다문화·장애인 가족 지원제도가 반영됐고, 인증 기준은 중소기업 60점·중견기업 65점·대기업 70점 이상(100점 만점, 유효기간 3년)이며, 시간 단위 연차·조기 퇴근제처럼 비용이 적은 제도부터 시작하라고 권했다.","eSum":"In an HR Insight interview, Park Gu-yeon, president of the Korea Institute for Healthy Family, says work-family policies get used when they need no application, such as maternity leave converting automatically into parental leave, when cover and work-sharing rules stop gaps falling on colleagues, and when working habits change, for example leaving on time and cutting unnecessary meetings. Because middle managers' decisions largely determine take-up, users must not be penalised in appraisals, and support should extend to elder care through family-care leave and reduced hours. From this year Korea's family-friendly certification also counts support for single-person, childless, single-parent, multicultural and disabled-member households; pass marks are 60 for small firms, 65 for mid-sized and 70 for large companies out of 100, valid for three years, and she suggests starting with low-cost measures such as hourly annual leave and early-leave days.","kImp":"팀장은 육아·부모 돌봄 제도를 쓰는 직원의 업무를 누가 어떻게 나눠 맡을지 미리 정해 두고 평가에서 불이익이 없음을 분명히 밝히며, 시간 단위 연차처럼 부담이 적은 제도부터 팀 안에서 자연스럽게 쓰이게 하는 것이 좋다.","eImp":"Team leaders can agree in advance how the work of staff using childcare or elder-care leave will be covered, state clearly that using it will not hurt appraisals, and normalise low-cost options such as hourly annual leave within the team.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39676","prio":2,"kor":true,"tags":["POL","WELL","RET"],"tool":""},{"code":"HRM","date":"2026-10-22","src":"HR Insight","title":"“데이터는 AI에게, 코칭은 리더에게” — AI 성과 대시보드 숫자 너머 평가자가 읽어야 할 난이도·기여도·통제 불가 변수","eTitle":"'Data to AI, Coaching to Leaders': The Difficulty, Contribution and Uncontrollable Factors Evaluators Must Read Beyond AI Performance Dashboards","kSum":"이재형 농협대 교수(《성과관리 3.0》 저자)는 AI가 KPI 후보 제안과 피드백·평가 근거·면담 시나리오 초안을 맡으면서 평가자의 역할이 데이터 취합에서 코칭과 맥락 해석으로 바뀌고 있다며, VAR이 화면을 줘도 판정은 주심이 하듯 AI 데이터는 판단의 근거일 뿐 판단 자체가 아니라고 강조했다. 호황 시장에서 120점을 받은 직원과 기울던 프로젝트에서 -30%가 될 실적을 -10%로 막은 90점 직원을 예로 들어, 숫자와 실제 성과의 간극은 과업 난이도, 동료를 도운 기여도, 환율 급등 같은 통제 불가 변수에서 생긴다고 정리했다. 지표는 활동이 아닌 결과 중심으로 설계하고 AI가 제안한 지표는 사람이 검증·수정해야 하며, 평가 수용성은 사전에 합의한 기준에 따른 일관된 판단에서 나온다고 했다(구독 기사로 후반부 비공개).","eSum":"Lee Jae-hyung, a professor at Nonghyup University and author of 'Performance Management 3.0', says that as AI suggests KPIs and drafts feedback, rating rationales and appraisal-interview scripts, evaluators are shifting from collating data to coaching and interpreting context; like VAR in football, AI data supports a judgement but is not the judgement. Using the example of an employee who scored 120 in a booming market and one who scored 90 after limiting a looming 30% loss to 10% on a failing project, he identifies three gaps between numbers and real performance: task difficulty, contribution such as helping colleagues, and uncontrollable variables such as exchange-rate spikes. Metrics should measure outcomes rather than activity, AI-suggested indicators should be checked and revised by people, and acceptance of ratings depends on consistent judgements against criteria agreed in advance (subscriber article; later part not public).","kImp":"평가 면담 때 AI 대시보드나 KPI 숫자만 보지 말고 과제 난이도, 동료·다른 부서를 도운 기여, 환율·시장 변화 같은 통제 불가 변수를 함께 적게 하고, 평가 기준은 연초 목표 설정 면담에서 미리 합의해 둘 만하다. AI가 제안한 지표는 팀장이 직접 검증·수정해 활동이 아닌 결과 중심으로 다듬어야 한다.","eImp":"In appraisal interviews, look beyond AI dashboards and KPI figures to record task difficulty, help given to colleagues and other departments, and uncontrollable factors such as exchange-rate or market swings, with criteria agreed at the start-of-year goal-setting meeting. Team leaders should check and revise any AI-suggested metrics so they measure outcomes rather than activity.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=109&bi_pidx=39663","prio":1,"kor":true,"tags":["PERF","AI","COACH"],"tool":""},{"code":"HRM","date":"2026-10-20","src":"HR Dive","title":"'승진하려면 회사를 떠나야' 3명 중 2명… SHL 조사, 미·영 직장인 2,000여 명 중 '관리자가 내 역량을 제대로 안다'는 42%뿐","eTitle":"Two-Thirds of Workers Feel They Must Leave to Advance Despite Wanting to Stay, and Only 42% Say Their Managers Fully Understand Their Skills, SHL Survey Finds","kSum":"HR Dive가 2026년 10월 20일 보도한 인재평가 기업 SHL의 미국·영국 직장인 2,000여 명 조사에서 3분의 2는 지금 회사에 남고 싶지만 경력을 키우려면 떠나야 한다고 느낀다고 답했다. 대부분은 더 높은 직무나 다른 직무를 위해 재교육을 받겠다고 했고 10명 중 9명 가까이는 역량을 보여 주기 위해 공식 역량 평가도 받겠다고 했지만, 관리자가 현재 직무 너머의 자기 역량을 충분히 이해한다는 응답은 42%에 그쳤다. 미국 응답자의 59%는 회사가 내부 육성보다 외부 후보를 선호한다고 답했고, 유능한 부하 직원을 놓치기 싫어하는 관리자가 내부 이동을 막을 수 있다는 지적도 나왔다.","eSum":"HR Dive reported on 20 October 2026 that in an SHL survey of more than 2,000 employed adults in the US and UK, two-thirds feel they will have to leave their employer to advance even though they want to stay. Most said they would retrain for a more senior or different role and nearly nine in ten would sit a formal skills assessment, yet only 42% said their managers fully understand their skills beyond their current role. Some 59% of US workers said their employer favours outside candidates over internal development, and managers reluctant to lose skilled direct reports were cited as a barrier to internal mobility.","kImp":"유능한 팀원을 다른 팀으로 보내는 것을 손실로만 보지 말고, 연 1회 경력 면담에서 팀원의 현재 직무 밖 역량과 희망 직무를 기록해 두면 외부 채용 전에 내부 후보를 먼저 검토할 수 있다.","eImp":"Rather than treating a strong team member's move elsewhere as a loss, managers can record skills beyond the current role and preferred next roles in an annual career conversation so internal candidates are considered before hiring externally.","url":"https://www.hrdive.com/news/employees-say-they-have-to-leave-their-companies-to-advance-their-careers/833444/","prio":2,"kor":false,"tags":["RET","TRN"],"tool":""},{"code":"HRM","date":"2026-10-19","src":"INSEAD Knowledge","title":"INSEAD: 조직의 건강은 '작별하는 방식'에서 드러난다… 퇴직·이동 대화는 2~3년 앞서 시작하고 지식 이전·기한 있는 멘토링·후임 권위 보호를 설계하라","eTitle":"INSEAD: How an Organisation Says Goodbye Reveals Its Health, So Start Transition Talks Years Ahead and Design Knowledge Transfer, Time-Limited Mentoring and Successor Authority","kSum":"INSEAD Knowledge가 2026년 10월 19일 실은 그레이엄 워드 겸임교수와 이자벨 레베 코치의 글은 갑작스러운 퇴사·이직·은퇴·계획된 교체를 조직이 어떻게 다루는지가 조직 건강의 핵심 신호라며, 떠나는 사람에게 매달리는 '불안형', 사람을 소모품처럼 대하는 '회피형', 상실을 인정하면서 새 출발을 돕는 '안정형' 조직을 구분했다. 잘못 처리된 이별은 후임자의 권위를 약하게 하고 남은 직원의 신뢰를 깎으며 팀을 흔든다고 했다. 처방으로는 가능하면 2~3년 앞서 승계·인수인계·이후 계획을 이야기하고, 공식 지식 이전·단계적 업무 축소·기한을 정한 멘토링을 설계하며, 구체적 기여를 인정하는 작별 자리를 마련하고, 떠나는 리더가 후임을 공개적으로 지지하되 후임의 결정에는 관여하지 않게 하라고 권했다.","eSum":"In an INSEAD Knowledge article published on 19 October 2026, adjunct professor Graham Ward and executive coach Isabelle Lebbe argue that how an organisation handles sudden exits, resignations, retirements and planned transitions is a key sign of its health, distinguishing anxious organisations that cling to departing figures, avoidant ones that treat people as disposable and secure ones that acknowledge loss while supporting renewal. Poorly handled exits weaken successors' authority, erode remaining staff's trust and disrupt teams. They recommend starting conversations about succession, handover and future plans two to three years ahead where possible, designing formal knowledge transfer, phased work and time-limited mentoring, marking departures by recognising specific contributions, and having outgoing leaders publicly endorse successors while staying out of decisions that now belong to them.","kImp":"정년퇴직이나 장기 근속자의 이동이 예정된 팀은 6개월~1년 전부터 업무 매뉴얼화와 후임 동반 근무 기간을 계획하고, 떠난 뒤의 자문 역할은 범위와 기간을 정해 두어 후임의 결정권을 보호하는 것이 좋다.","eImp":"Teams expecting a retirement or the move of a long-serving colleague should plan documentation and an overlap period with the successor six to twelve months ahead, and set the scope and length of any post-departure advisory role to protect the successor's authority.","url":"https://knowledge.insead.edu/career-development/does-your-organisation-know-how-say-goodbye","prio":1,"kor":false,"tags":["RET","LDR"],"tool":""},{"code":"HRM","date":"2026-10-13","src":"아시아투데이","title":"노동장관 국감서 \"포괄임금제 금지 법에 담아야, 하반기 근기법 개정 지원\"·\"정년연장 법안 연내 처리\"…감독 101곳 중 82곳서 공짜 노동 적발","eTitle":"Labour Minister Tells Parliamentary Audit That All-Inclusive Pay Should Be Banned by Law With a Labour Standards Act Amendment Backed This Half, and That a Retirement-Age Extension Bill Must Pass This Year, as Inspections Found Unpaid Work at 82 of 101 Sites","kSum":"김영훈 고용노동부 장관은 13일 국회 기후에너지환경노동위원회 국정감사에서 연장근로 수당을 미리 정액으로 묶는 포괄임금제를 원칙적으로 법에 담아 금지해야 한다는 데 공감하고 하반기 근로기준법 개정안 통과를 지원하겠다고 밝혔다. 이용우 의원에 따르면 노동부는 올해 의심 사업장 101곳을 감독해 82곳에서 공짜 노동을 적발했지만 형사입건은 1곳이었고, 관련 법안 9건은 4월 법안소위에 올랐다가 노동부 이견으로 계류됐다. 장관은 정년연장 법안도 올해 안에 처리돼야 한다며 논의가 무르익으면 정부안을 조속히 내겠다고 했고, 메가특구 고소득 R&D 인력의 주52시간 적용 제외는 신중히 검토하겠다고 했다. 기사에 정년 연령 수치는 나오지 않는다.","eSum":"At the 13 October parliamentary audit of the Ministry of Employment and Labor, Minister Kim Young-hoon agreed in principle that all-inclusive pay, which bundles overtime into a fixed wage, should be banned by law and said he would support passing a Labour Standards Act amendment in the second half of the year. According to lawmaker Lee Yong-woo, the ministry inspected 101 suspected workplaces this year and found unpaid work at 82, but only one case was referred for prosecution, while nine related bills stalled in April after the ministry objected to an explicit ban. The minister also said a retirement-age extension bill must pass this year and that the government would table its own proposal once talks mature, and said exempting high-income R&D staff in mega special zones from the 52-hour cap needs careful review. The article gives no specific retirement age.","kImp":"포괄임금 계약으로 운영하는 사무직이 있다면 법 개정 전이라도 실제 연장근로 시간을 기록하는 방식(출퇴근·업무 로그)을 먼저 갖춰 두는 것이 좋고, 정년연장 논의에 대비해 고참 직원의 역할·임금 체계를 어떻게 바꿀지 인사 부서와 미리 검토할 만하다.","eImp":"Where office staff are on all-inclusive pay contracts, it is wise to start recording actual overtime, for example through attendance and work logs, before the law changes, and to review with HR how senior staff roles and pay structures might change ahead of a retirement-age extension.","url":"https://www.asiatoday.co.kr/kn/view.php?key=20261013010003792","prio":3,"kor":true,"tags":["POL","WR"],"tool":""},{"code":"HRM","date":"2026-10-01","src":"Kellogg Insight","title":"켈로그 연구: 원격근무 채용공고는 같은 직무 대면 공고보다 요구 역량이 25% 많다… 유럽 28개국 공고 5,000만 건 분석, 신입에게 원격 일자리 문턱 높아져","eTitle":"Kellogg Research: Remote Job Postings List 25% More Required Skills Than Comparable On-Site Ones, Based on Over 50 Million Postings in 28 European Countries","kSum":"Kellogg Insight가 2026년 10월 1일 소개한 왕스난·장러톈(켈로그)·랴오전위(노스이스턴대)의 Administrative Science Quarterly 논문은 유럽 28개국의 2018~2021년 채용공고 5,000만 건 이상을 분석해, 원격 공고가 같은 직종·고용주·연도의 비원격 공고보다 요구 역량을 25% 더 많이 적고 경력·학력 요건도 약간 높다는 사실을 확인했다. 인지·동료 소통·고객 소통·ICT 역량 모두에서 요구가 늘었고, 채용 경험자 1,250명 대상 사전등록 실험에서도 비슷한 결과가 나왔다. 효과는 완전 원격 직무에서 가장 컸고 하이브리드는 대면과 비슷했으며, 연구진은 원격 온보딩이 어려워 교육이 덜 필요한 지원자를 선호하는 것을 한 이유로 꼽으며 주니어 일자리가 줄어드는 악순환을 경고했다.","eSum":"Kellogg Insight on 1 October 2026 featured an Administrative Science Quarterly paper by Shinan Wang and Letian Zhang of Kellogg and Zhenyu Liao of Northeastern University, which analysed more than 50 million job postings from 28 European countries in 2018-2021. Remote postings listed 25% more required skills than non-remote postings for the same occupation, employer and year, along with slightly higher experience and education requirements, across cognitive, co-worker interaction, customer interaction and ICT skills, and a preregistered experiment with 1,250 people with hiring experience largely replicated the result. The effect was strongest for fully remote jobs, while hybrid postings resembled in-person ones, and the authors warn that a preference for candidates who need less training, given the difficulty of remote onboarding, could shrink junior roles over time.","kImp":"원격·재택 비중이 큰 직무를 채용할 때 요구 조건을 습관적으로 늘리기보다 실제 필요한 역량만 남기고, 신입은 하이브리드로 배치해 대면 지도와 온보딩 기간을 확보하는 편이 인재 풀을 넓히는 데 낫다.","eImp":"When hiring for roles with a large remote component, organisations should resist piling on requirements and keep only the skills truly needed, while placing new entrants in hybrid arrangements so they get in-person coaching and a proper onboarding period.","url":"https://insight.kellogg.northwestern.edu/article/theres-a-higher-bar-for-working-from-home","prio":2,"kor":false,"tags":["RET","REMOTE","TRN"],"tool":""},{"code":"HRM","date":"2026-09-30","src":"뉴시스","title":"삼일PwC 글로벌 직장인 조사 \"업무에 AI 활용 64%\"…한국은 'AI 선도 인력' 4%(세계 14%), '핵심 실무 인력' 81%(세계 56%)","eTitle":"Samil PwC's Global Workforce Survey Finds 64% Use AI at Work, but Only 4% of Korean Respondents Are 'AI Leaders' Against 14% Globally, While 81% Sit in the 'Core Workforce' Against 56%","kSum":"삼일PwC가 30일 공개한 '2026 글로벌 직장인 설문조사'(48개국 4만9,364명, 한국 1,013명)에 따르면 지난 12개월간 업무에 AI를 쓴 비율은 64%로 1년 새 10%p 늘었고, 생성형 AI를 매일 쓰는 비율은 22%(전년 14%)였다. 한국은 AI 활용을 이끄는 'AI 선도 인력'이 4%로 세계 평균(14%)보다 크게 낮고 '핵심 실무 인력'은 81%로 세계(56%)보다 높았다. AI 선도 인력의 85%가 고용 안정에 자신 있다고 답했고 80% 가까이가 학습 자원을 이용할 수 있다고 한 반면, 핵심 실무 인력은 학습 자원 접근이 40%에 못 미치고 경영진 신뢰도 낮았다. PwC는 AI 도구를 덧붙이기보다 업무·역할·운영 모델을 다시 설계하고, 핵심 실무 인력에는 업무 부담을 늘리지 않는 학습 기회를 주라고 권했다.","eSum":"Samil PwC's 2026 Global Workforce Survey, released on 30 September and covering 49,364 respondents in 48 countries including 1,013 in Korea, found 64% used AI at work in the past year, up 10 points, and 22% use generative AI daily, up from 14%. Only 4% of Korean respondents are 'AI leaders' against 14% globally, while 81% are 'core workforce' against 56%. 85% of AI leaders feel confident about job security and nearly 80% can access learning resources, but fewer than 40% of the core workforce have such access and their trust in executives is low. PwC recommends redesigning work, roles and operating models rather than bolting on AI tools, and giving the core workforce learning that does not add to their workload.","kImp":"팀 대부분이 'AI를 아직 업무에 깊게 못 쓰는 실무 인력'일 가능성이 높으므로, 따로 시간을 내는 교육보다 매주 실제 업무 하나(보고서 요약·자료 정리 등)를 AI로 해 보는 짧은 실습과 잘 쓰는 동료의 사례 공유를 근무시간 안에 넣는 것이 현실적이다.","eImp":"Most of a team is likely to be core workers who do not yet use AI deeply, so short in-hours practice on one real weekly task, such as summarising a report or organising data, plus peer sharing by colleagues who use AI well, is more realistic than separate training.","url":"https://www.newsis.com/view/NISX20260930_0003808181","prio":2,"kor":true,"tags":["AI","TRN","ENG"],"tool":""},{"code":"HRM","date":"2026-09-30","src":"한국경제","title":"\"팀장 안 해도 높은 레벨·연봉\"…10단계 직급 없애고 '매니저·전문가' 두 트랙 만든 300명 IT기업, 이직률 5.5%→0.9%","eTitle":"A 300-Person Korean IT Firm Scrapped Ten Seniority Ranks for Manager and Expert Tracks So Staff Can Reach Senior Levels and Pay Without Leading a Team, and Saw Turnover Fall From 5.5% to 0.9%","kSum":"한국노동연구원 임금직무혁신센터가 30일 낸 '임금정보브리프'에 소개된 금융 IT 솔루션 기업 A사(임직원 약 300명)는 사원부터 전무까지 10단계 연공형 직급을 없애고 직무능력에 따른 L1~L8 레벨과 프로·매니저·마스터·캡틴 호칭으로 단순화했으며, 관리 역할의 '매니저 트랙'과 전문성을 키우는 '개발 전문가 트랙'을 나눠 팀장을 맡지 않아도 높은 레벨과 처우에 오를 수 있게 했다. 승진은 기본 규칙(매너·태도 영역 점수)과 성장 규칙(공통·직무·프로젝트 미션 배지)을 거쳐 연 2회 하고, 부서장에게는 회사 목표 달성률에 연동한 인센티브를 준다. 제도 도입 뒤 매출은 2024년 716억 원에서 지난해 916억 원으로 27.9% 늘고 영업이익은 5억 원 적자에서 15억 원 흑자로 돌아섰으며 이직률은 5.5%에서 0.9%로 떨어졌지만, 기사는 성과를 임금체계 개편만의 효과로 단정할 수 없다고 덧붙였다.","eSum":"A financial IT solutions firm of about 300 staff, profiled in the Korea Labor Institute wage and job innovation centre's wage brief published on 30 September, replaced ten seniority ranks from staff to senior executive with competency-based levels L1-L8 and four simple titles, and split careers into a manager track and a development expert track so employees can reach high levels and pay without leading a team. Promotion, held twice a year, requires points on manners and attitude plus badges from common, job and project missions, and department heads receive incentives tied to company target achievement. After the change, revenue rose 27.9% from 71.6 billion won in 2024 to 91.6 billion won last year, operating results swung from a 500 million won loss to a 1.5 billion won profit and turnover fell from 5.5% to 0.9%, though the article cautions that the gains cannot be credited to the pay reform alone.","kImp":"팀장 자리가 한정된 육상 조직이라면 관리직이 아니어도 전문성(예: 기술 감독·법규·안전 전문가)으로 성장할 수 있는 단계와 처우 기준을 글로 정리해 보여 주는 것만으로도 핵심 인력의 이탈을 줄이는 데 도움이 될 수 있다.","eImp":"Shore organisations with few team-leader posts can help retain key people simply by writing down the levels and pay criteria through which staff can grow as specialists, for example in technical superintendence, regulation or safety, without becoming managers.","url":"https://www.hankyung.com/article/2026093059087","prio":2,"kor":true,"tags":["RET","PERF","LDR"],"tool":""},{"code":"HRM","date":"2026-09-29","src":"HR Dive","title":"교육 기회는 누구에게? 코넬대 실험, '능력주의' 문화에선 교육에서 밀린 고성과자가, '평등주의' 문화에선 저성과자가 더 크게 서운해해","eTitle":"Cornell Experiment: Under Meritocratic Norms High Performers Resent Being Passed Over for Training, While Under Egalitarian Norms Lower Performers Feel More Slighted","kSum":"HR Dive가 2026년 9월 29일 소개한 코넬대 SC존슨 경영대학원 마틴 비언스페르거 교수 연구(Journal of Accounting Research, 9월 20일 게재)는 3인 1조 참가자가 영어·독일어 관용구 퀴즈를 치른 뒤 관리자 역할을 맡은 1명이 결과를 보고 1명에게만 '교육'을 주는 실험을 했다. 참가자가 퀴즈를 스스로 고르게 해 능력주의 규범을 만든 조에서는 교육에서 빠진 고성과자가 더 부정적으로 반응했고, 퀴즈를 무작위로 배정해 평등주의 규범을 만든 조에서는 교육을 못 받은 저성과자가 더 서운함을 느꼈다. 연구진은 교육이 출장·네트워킹·향후 기회의 신호로 받아들여지므로 생산성만 보지 말고 조직의 공정성 규범을 고려해 배분하라고 조언했다.","eSum":"HR Dive on 29 September 2026 covered research by Cornell SC Johnson College of Business assistant professor Martin Wiernsperger, published in the Journal of Accounting Research on 20 September, in which three-person groups took quizzes on English and German idioms and a designated manager chose one member to receive training based on the results. Where members chose their quiz, simulating a meritocratic norm, high performers reacted more negatively when passed over; where quizzes were randomly assigned, simulating an egalitarian norm, lower performers felt more slighted. Because training signals travel, networking and future opportunities, the researcher suggests managers weigh their workplace's fairness norms rather than productivity alone.","kImp":"외부 교육·연수 대상자를 정할 때는 선정 기준(성장 필요, 직무 연관성, 순번 등)을 미리 공개하고 이번에 빠진 사람에게 다음 기회를 알려 주면, 교육이 '누가 인정받았나'의 신호로 오해되는 일을 줄일 수 있다.","eImp":"When choosing who attends external training, publishing the selection criteria in advance, such as development need, job relevance or rotation, and telling those left out about their next opportunity reduces the risk of training being read as a verdict on who is valued.","url":"https://www.hrdive.com/news/high-performers-might-resent-lower-performing-workers-getting-training-over/831613/","prio":1,"kor":false,"tags":["TRN","PERF"],"tool":""},{"code":"HRM","date":"2026-09-25","src":"Harvard Business Review","title":"HBR \"익숙한 말투를 '소통 능력'으로 착각한다\" — 말하는 방식이 직무 기회를 가른다","eTitle":"Research: How Speech Patterns Shape Opportunity at Work","kSum":"HBS 워킹 놀리지의 에이버리 포먼이 소개한 카딤 노레이의 연구는 수십 년간의 노동시장 데이터와 음성 녹음을 분석해, 말하는 방식이 능력을 제대로 보여 주지 않는데도 관리자들이 '익숙함'을 사회적 역량으로 착각한다고 밝혔다. 직장 규범과 말하는 방식이 비슷한 사람일수록 사람을 상대하는 대인 업무 중심 직무로 더 많이 이동했고, 지역 노동시장을 한 집단이 지배할수록 이 효과가 커져 '다르게 들리는' 사람의 기회가 좁아졌다. 기사는 AI가 분석 업무를 자동화할수록 소통의 비중이 커질 것이라며, 리더가 '적합성(fit)'의 정의를 넓히고 구조화된 인재 결정 방식을 써서 말투 때문에 소수 집단 지원자가 불이익을 받지 않게 하라고 권한다.","eSum":"An HBS Working Knowledge piece by Avery Forman describes research by Kadeem Noray that draws on decades of labor-market data and audio recordings and finds that managers often mistake familiar speech for social skill, even though speech patterns do not reliably signal ability. Workers whose communication style matches workplace norms are more likely to move into people-oriented, socially intensive roles, and the effect is stronger where one group dominates the local labor market, narrowing opportunities for people who sound different. The piece expects communication to matter more as AI automates analytical work and urges leaders to broaden their definition of 'fit' and use structured talent decisions so minority applicants are not penalized for how they sound.","kImp":"채용 면접이나 승진 심사에서 말투·억양이 익숙한지가 '소통 능력' 점수를 좌우하기 쉽다. 면접 평가표와 평가 면담의 소통 항목을 '요점을 먼저 말하는가', '질문에 정확히 답하는가' 같은 관찰 가능한 행동 기준으로 바꾸고, 국적·출신 지역별로 결과 편차가 없는지 점검해 볼 만하다.","eImp":"In hiring interviews and promotion reviews, how familiar a candidate's accent or speaking style sounds can quietly drive 'communication' scores. Anchor that criterion in observable behaviors such as leading with the main point and answering the question asked, and check outcomes for gaps by nationality or regional background.","url":"https://hbr.org/2026/09/research-how-speech-patterns-shape-opportunity-at-work","prio":2,"kor":false,"tags":["DI","XC","RET"],"tool":""},{"code":"HRM","date":"2026-09-22","src":"HR Dive","title":"'AI가 신입 업무를 가져가면 리더는 어디서 크나' — HR 전문가 78% 리더십 역량 개발 공백 우려(Talogy)","eTitle":"HR leaders worry about the loss of critical leadership skill development","kSum":"인재관리 기업 탤로지(Talogy)가 고위 HR 리더·채용 관리자·교육 전문가 200여 명을 조사한 결과, 78%가 AI가 신입 단계 업무를 대신하면서 핵심 리더십 역량 개발이 타격을 받을까 걱정한다고 답했다. 응답자들은 리더 파이프라인에 들어오는 사람이 줄면서 관리 역량이 예전처럼 자연스럽게 자라지 않을 수 있다고 우려했다. 기사에 인용된 IT 기업 GoTo 조사에서는 근로자의 39%, Z세대의 46%가 AI 의존으로 자신이 덜 유능하고 덜 똑똑해졌다고 답했다. 탤로지는 저절로 일어나던 현장 학습을 의도적으로 대체할 방법을 마련하고, 비판적 사고·적응력·협업 같은 인간 역량을 기르며, 리더십 개발을 경력 초기부터 시작하라고 권했다.","eSum":"A Talogy survey of more than 200 senior HR leaders, talent acquisition managers and learning experts found 78% worried that AI taking over entry-level tasks could harm the development of critical leadership skills, as managerial skills may no longer develop as naturally as they once did. A GoTo survey cited in the article found 39% of workers, and 46% of Gen Z, said relying on AI made them feel less competent and less intelligent. Talogy's Ali Shalfrooshan said teaching employees to work alongside AI tools 'simply isn't enough'. The recommendations are to replace lost on-the-job learning more purposefully, build human capabilities such as critical thinking, adaptability and collaboration, and start leadership development early in careers.","kImp":"AI가 자료 정리·초안 작성 같은 저연차 업무를 대신할수록 신입이 그 과정에서 저절로 익히던 판단력과 업무 감각이 자라지 않을 수 있다. 저연차 직원에게 AI 초안을 직접 검증·수정하게 하고 팀장이 결정의 근거를 설명해 주는 시간을 의도적으로 마련하며, 리더십 교육을 입사 초기부터 시작해 볼 만하다.","eImp":"As AI takes over junior tasks such as compiling data and drafting documents, new staff may stop picking up the judgment and feel for the work that used to come with them. Have junior employees verify and revise AI drafts themselves, deliberately schedule time for team leaders to explain the reasoning behind decisions, and start leadership development early in careers.","url":"https://www.hrdive.com/news/hr-leaders-worry-about-the-loss-of-critical-leadership-skill-development/830919/","prio":2,"kor":false,"tags":["TRN","AI","LDR"],"tool":""},{"code":"HRM","date":"2026-09-21","src":"HR Insight","title":"“교육은 이벤트가 아니라 구조” — 5,700만 건 교육 세션 분석에서 96%가 HRD 팀장직 축소, 학습 전이는 상사의 교육 전·중·후 역할이 좌우","eTitle":"Training Is a Structure, Not an Event: As 96% of Firms Cut L&D Leadership Roles, Transfer to the Job Depends on What Managers Do Before, During and After","kSum":"SK아카데미 임창현 Research Fellow는 HR 테크 기업 원허들(1Huddle)이 5,700만여 건의 기업 교육·온보딩 세션을 분석한 결과 추적 대상 기업 모두가 시니어 HR 직무를 하나 이상 줄였고 96%는 인재개발 조직의 팀장급 이상 직책을, 71%는 리더 직책 자체를 없앴다며 성장 요구는 커지는데 HRD 기능은 축소되는 역설을 짚었다. 교육이 끝나도 상사·동료·평가 기준이 그대로면 학습은 현업에 착지하지 못한다며 '무엇을 가르칠까'가 아니라 '현장에서 무엇이 달라져야 하나'를 먼저 묻고, 교육 전에는 현장 장면을 정의하고, 교육 중에는 실제 문제로 새 행동을 연습시키고, 교육 후에는 리더와 팀이 그 행동을 반복할 업무 환경과 점검 장치를 설계하라고 제안했다. 브로드와 뉴스트롬의 교육훈련 전이 매트릭스를 들어 상사가 교육 목적을 모르면 복귀한 구성원을 실무 과제로 연결할 수 없다며, 핵심인재 교육 때 소속 임원의 사전 참여를 참여 조건으로 걸었던 사례를 소개했다(구독 기사로 후반부 비공개).","eSum":"Lim Chang-hyun, a research fellow at SK Academy, cites HR tech firm 1Huddle's analysis of some 57 million corporate training and onboarding sessions, in which every tracked company cut at least one senior HR role, 96% cut team-lead or higher positions in talent development and 71% eliminated the function's leader role altogether. Because learning fails to land when managers, peers and evaluation criteria stay the same, he urges designers to ask what must change on the job rather than what to teach: define real work scenes before training, practise new behaviour on real problems during it, and build work routines and checkpoints so leaders and teams repeat the behaviour afterwards. Citing Broad and Newstrom's transfer-of-training matrix, he notes that a manager who does not know a course's purpose cannot link a returning employee to practical tasks, and describes making executives' prior involvement a condition of a high-potential programme (subscriber article; later part not public).","kImp":"직원을 외부 교육이나 사내 연수에 보낼 때 팀장이 교육 목표와 복귀 후 달라져야 할 업무 행동을 미리 정해 두고, 복귀 첫 달에 그 행동을 실제 과제에 적용하는지 함께 점검하는 짧은 1:1 대화를 넣어 볼 만하다. 교육 신청서에 '현업에서 무엇이 달라져야 하나'를 적는 칸을 두는 것도 방법이다.","eImp":"Before sending staff to external courses or in-house training, team leaders could agree on the course goals and the work behaviours that should change afterwards, then hold a short one-on-one in the first month back to check those behaviours are applied to real tasks. Adding a 'what should change on the job' field to training request forms also helps.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=109&bi_pidx=39567","prio":2,"kor":true,"tags":["TRN","LDR"],"tool":""},{"code":"HRM","date":"2026-09-03","src":"HR Dive","title":"신입 첫 주 서류 13건·12시간, '필요한 건 60%뿐' — Adobe 신규 입사자 1,000여 명 조사","eTitle":"Employees say only 60% of onboarding materials are necessary","kSum":"어도비가 최근 2년 안에 입사한 미국 근로자 1,000여 명을 조사한 결과, 신규 입사자는 첫 주에 평균 13건의 온보딩 문서를 받아 약 12시간을 검토했지만 꼭 필요하다고 본 자료는 60%였다. 절반 넘게 기억한다는 응답은 56%에 그쳤고, 상위 10%는 문서가 30건을 넘어 검토에 35시간 이상이 들 수 있었다. 4명 중 1명은 온보딩이 혼란스럽거나 빈틈이 있어 업무 성과나 자신감에 부정적 영향을 받았다고 했고, 5명 중 1명 이상은 입사 결정을 다시 생각하게 됐다고 답했다. 직무별 책임과 기대는 가장 잘 기억됐지만 IT, 법규·컴플라이언스, AI 사용 정책은 가장 덜 기억됐다.","eSum":"An Adobe survey of more than 1,000 U.S. adults who started a job in the past two years found new hires received an average of 13 onboarding documents in their first week and spent about 12 hours reviewing them, yet rated only 60% of the material as necessary. Just 56% said they retained more than half of it, and for the top 10% onboarding ran to more than 30 documents and over 35 hours. One in four said confusing or patchy onboarding hurt their performance or confidence, and more than one in five said it made them question their decision to join. Role-specific responsibilities were retained best, while IT, legal and compliance requirements and AI policies were retained least.","kImp":"신입 직원에게 첫 주에 규정·매뉴얼·서약서를 한꺼번에 넘기면 정작 중요한 내용이 묻히기 쉽다. 온보딩 자료를 '첫 주에 꼭 알아야 할 것'과 '첫 달 안에 익힐 것'으로 나누고, IT·보안·AI 사용 규정처럼 기억에 덜 남는 항목은 몇 주 뒤 담당 선배가 1:1로 다시 짚어 주는 후속 점검을 넣어 볼 만하다.","eImp":"Handing new hires every policy, manual and pledge form in their first week buries what matters most. Split onboarding material into 'must know in week one' and 'learn within the first month', and have a buddy revisit easily forgotten items such as IT, security and AI-use rules in a one-on-one a few weeks later.","url":"https://www.hrdive.com/news/employees-say-only-60-of-onboarding-materials-are-necessary/829526/","prio":2,"kor":false,"tags":["RET","TRN"],"tool":""},{"code":"HRM","date":"2026-08-25","src":"HR Dive","title":"'일에 필요한 사람에게 닿는다' 21%뿐 — 단절의 시대, 멘토링을 복지 아닌 업무 기능으로","eTitle":"What mentorship looks like in the disconnected era","kSum":"HR Dive가 인용한 어치버스 워크포스 인스티튜트의 '2026 몰입·유지 보고서'에 따르면 일하는 데 필요한 사람에게 접근할 수 있다는 직원은 21%, 회사 소통이 정보를 주고 연결해 준다는 직원은 20%에 그쳤다. 동료와 강하게 연결된 직원은 몰입할 가능성이 4.7배, 일에서 의미를 찾을 가능성이 3.3배 높았고, 성장 기회가 없다고 느끼는 직원의 77%는 다음 자리를 찾고 있었다. 건설 사업관리 회사 그룹 PMX는 체크리스트식 공식 프로그램을 접고 멘토 1명에 멘티 2~3명을 붙여 월 1회 만남만 정해 둔 유연한 방식으로 바꿨다. 기사는 멘토링을 복지가 아닌 업무 기능으로 운영하고, 관리자가 당연히 멘토가 될 것이라고 가정하지 말라고 조언한다.","eSum":"Achievers Workforce Institute's 2026 Engagement and Retention Report, cited by HR Dive, found only 21% of employees can access the people they need to be productive and 20% feel company communications keep them informed and connected. Employees with strong peer connections were 4.7 times more likely to be engaged and 3.3 times more likely to find work meaningful, while 77% of those who see no room for growth are looking for what is next. Construction project manager Group PMX dropped a box-checking formal program in favor of pairing one mentor with two or three mentees and requiring just one meeting a month. The piece advises running mentoring as a business function and not assuming managers will be default mentors.","kImp":"신입·저연차 직원에게 직속 팀장이 아닌 다른 부서 선배를 멘토로 이어 주면 '누구에게 물어야 할지 모르는' 단절을 줄이고 이른 퇴사를 막는 데 도움이 될 수 있다. 형식적인 체크리스트 대신 멘토 1명에 멘티 2~3명, 월 1회 만남만 정해 두는 가벼운 방식부터 시작해 볼 만하다.","eImp":"Pairing new and junior staff with a mentor from another department, outside their reporting line, can ease the feeling of not knowing whom to ask and reduce early resignations. Start light, with one mentor for two or three mentees and a single meeting a month, rather than a box-ticking checklist.","url":"https://www.hrdive.com/news/what-mentorship-looks-like-in-the-disconnected-era/828651/","prio":2,"kor":false,"tags":["TRN","ENG","RET"],"tool":""}]}]};
